window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-nefrologia-nef-2"]={"block":"medcurso:medcurso-nefrologia-nef-2","label":"Medcurso · NEF 2","count":384,"questions":[{"id":"medcurso-nefrologia-nef-2-50109","number":"50109","sourceNumber":"50109","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sua paciente é uma mulher assintomática de 26 anos, que você está examinando pela\nprimeira vez. Você observa tortuosidade arteriovenosa no exame oftalmoscópico e a PA é de\n220/132 mmHg. Ela é hospitalizada para uma avaliação mais profunda, que inclui arteriografia\nrenal, tendo em vista que você também detectou:","options":{"A":"História familiar de hipertensão arterial;","B":"Quatro a cinco leucócitos por campo de grande aumento no EAS;","C":"Que ela não está usando anticoncepcionais orais;","D":"Um discreto sopro na região subcostal esquerda, que apresenta componentes sistólicos e\ndiastólicos curtos."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-158734","number":"158734","sourceNumber":"158734","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, foi internada com quadro de anorexia, náuseas,\nvômitos, fraqueza muscular, poliúria e polidipsia. Durante a investigação, foram evidenciados os\nseguintes resultados de exames: glicosúria, aminoacidúria, bicarbonatúria, hiperfosfatúria e\nhiperuricosúria. Qual a principal etiologia dessa síndrome em adultos?","options":{"A":"Doença de Wilson.","B":"Mieloma múltiplo.","C":"Saturnismo.","D":"Amiloidose.","E":"Cistinose."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-134345","number":"134345","sourceNumber":"134345","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 87 anos de idade, diabético e hipertenso, em uso de glibenclamida,\nmetiformina e captopril. Evolui com acentuada\ndeterioração neurológica nos últimos 3 dias. Como\nfoi realizada tomografia de crânio sem contraste e essa não demonstrou achados que justificassem\no quadro, foi solicitado então tomografia com contraste. Aponte a alternativa em que o item NÃO\npode ser atribuído como boa prática.","options":{"A":"Tomografia sem contraste sempre antes, porque se ocorrer extravasamento de contraste ocorre\nextensão maior da lesão secundária.","B":"Podemos manter medicação ambulatorial.","C":"Pacientes internados e com deterioração se beneficiam com melhor controle metabólico.","D":"Importante adequada hidratação."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-140210","number":"140210","sourceNumber":"140210","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 45 anos, hipertensa de longa data, interna por dor precordial sendo\ndiagnosticado IAM e instituído tratamento medicamentoso com estreptoquinase (trombólise),\nAAS, propranolol e sinvastatina. Evolui com hipotensão e sinais de má perfusão tecidual no\ndécimo dia de internação. Nesta data apresentava Creatinina = 1,0 mg/dl. No dia seguinte\nevoluiu com oligúria, urina escura e os seguintes exames: Cr = 3,8 mg/dl, Exame de urina\n(EAS): pH-6,0 Densidade=1010, presença de hematúria ++/4 em fita reagente. Hemácias:\n2/campo (normal até 6). Sem proteinúria ou leucocitúria. Baseado nestes achados assinale a\nprincipal etiologia da injúria renal:","options":{"A":"Rabdomiólise.","B":"Baixo débito cardíaco.","C":"Nefrite intersticial aguda.","D":"Sepses.","E":"Obstrução intratubular."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-86589","number":"86589","sourceNumber":"86589","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Das causas abaixo de insuficiência renal aguda, qual a que mais frequentemente está\nassociada à hipocalemia?","options":{"A":"Nefrotoxicidade por anfotericina B.","B":"Sépsis.","C":"Rabdomiólise.","D":"Nefrotoxicidade por contraste.","E":"Pós-operatório de cirurgia cardíaca."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-49619","number":"49619","sourceNumber":"49619","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A síndrome de lise tumoral é quadro descrito após quimioterapia, neoplasias de\nnatureza hematológica ou extensa citorredução\ntumoral. Sua evolução não costuma cursar com:","options":{"A":"Hipocalcemia.","B":"Hipercalemia.","C":"Hiperuricemia.","D":"Hipofosfatemia.","E":"Desidrogenase láctica aumentada."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-49612","number":"49612","sourceNumber":"49612","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Nefropatia potencialmente grave pode ser encontrada 48-72h após exame contrastado.\nA melhor terapêutica para sua prevenção é:","options":{"A":"Iniciar captropil 12 horas antes do exame.","B":"Iniciar furosemida venosa 12 horas antes do exame.","C":"Iniciar dopamina 24 horas antes e após o exame.","D":"Iniciar acetilcisteína após exame.","E":"Hidratação com solução salina 12 horas antes e após exame."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-49608","number":"49608","sourceNumber":"49608","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"No dia seguinte ao cateterismo cardíaco com implante de stent, paciente evolui com\nfalência renal aguda, necessitando de terapia dialítica. A principal hipótese implicada é:","options":{"A":"Hipovolemia.","B":"Ateroembolia.","C":"Excesso de contraste isosmolar.","D":"Septicemia.","E":"Coagulação intravascular disseminada."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-252219","number":"252219","sourceNumber":"252219","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Furosemida, diurético usado com frequência no tratamento de diversas patologias, tem\nsua ação em qual região do rim?","options":{"A":"Membrana basal glomerular.","B":"Segmento ascendente da alça de Henle.","C":"Membrana basal tubular.","D":"Túbulo contorcido proximal."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26613","number":"26613","sourceNumber":"26613","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual a etiologia da doença transmitida por alimentos (não infecciosa) que cursa com\nperíodo de incubação de uma semana ou mais, tendo como sinais e sintomas: adormecimento,\nfraqueza nas pernas, paralisia espástica, alteração da visão, cegueira, coma e nas mulheres\ngrávidas o feto em desenvolvimento é especialmente vulnerável?","options":{"A":"Cobre.","B":"Mercúrio.","C":"Cádmio.","D":"Tálio.","E":"Zinco."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26455","number":"26455","sourceNumber":"26455","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O mecanismo pelo qual os Anti-inflamatórios Não Hormonais (AINH) podem levar à\nInsuficiência Renal (IR) é:","options":{"A":"aumento da diurese provocando uma IRA pré-renal.","B":"estimulação da produção das prostaglandinas renais que normalmente mantêm a arteríola\naferente dilatada.","C":"inibição da produção das prostaglandinas renais que normalmente mantêm a arteríola aferente\ndilatada.","D":"estimulação da produção das prostaglandinas renais que normalmente mantêm a arteríola\neferente dilatada.","E":"inibição da produção das prostaglandinas renais que normalmente mantêm a arteríola eferente\ndilatada."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-281871","number":"281871","sourceNumber":"281871","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A proteinúria tubular patológica é observada em qual situação?","options":{"A":"Peritonite bacteriana espontânea.","B":"Síndrome do quebra-nozes.","C":"Nefropatias tubulointersticiais.","D":"Proteinúria ortostática."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-215588","number":"215588","sourceNumber":"215588","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 9 anos, com diagnóstico de linfoma de Burkitt, encontra-se internada na\nUTI pediátrica. Realizou primeiro ciclo de\nquimioterapia. Evoluiu com síndrome de lise tumoral. Nas\núltimas 24 horas, teve diurese de 0,25 ml/kg/hora. Das alternativas abaixo, qual é o diagnóstico\nmais improvável para essa paciente?","options":{"A":"Hiperfosfatemia.","B":"Hiperuricemia.","C":"Hipopotassemia.","D":"Insuficiência renal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-62802","number":"62802","sourceNumber":"62802","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, 70 anos de idade, portador de hipertensão arterial sistêmica, diabetes e\ndislipidemia, realizou cineangiocoronariografia após quadro de angina instável. Nega insuficiência\nrenal prévia. Após 15 dias do procedimento, evolui com quadro de febre, dor abdominal e livedo\nreticular em membros inferiores. A avaliação laboratorial mostrou leucograma de 14500 com 15%\nde eosinófilo, LDH: 1500 e cretinina: 2,4 mg/dl. O diagnóstico mais provável é","options":{"A":"nefropatia por contraste.","B":"ateroembolismo.","C":"tromboangeíte obliterante.","D":"dissecção de aorta.","E":"vasculite de Churg-Strauss."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34953","number":"34953","sourceNumber":"34953","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A manifestação mais comum de nefrotoxicidade, após uso de anti-inflamatórios não\nhormonais, é:","options":{"A":"hemodinamicamente mediada com diminuição da síntese renal de prostaglandinas.","B":"nefrite intersticial aguda por reação imunológica.","C":"síndrome nefrótica por aumentar a excreção de proteínas urinárias.","D":"necrose cortical por mecanismos ainda não esclarecidos.","E":"obstrução tubular por precipitação intraluminal de ácido úrico."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-181149","number":"181149","sourceNumber":"181149","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O achado de glicosúria isolada em um exame de urina, não associada à hiperglicemia\ndo paciente, sugere alteração em qual segmento\nrenal?","options":{"A":"No túbulo distal.","B":"Na alça de Henle.","C":"No tubo coletor.","D":"No túbulo proximal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-134750","number":"134750","sourceNumber":"134750","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Apresenta grande importância clínica o conhecimento de medicações que são\npotencialmente nefrotóxicas. NÃO possui essa característica, apenas:","options":{"A":"As cefalosporinas.","B":"Os aminoglicosídeos.","C":"A vancomicina.","D":"O metronidazol."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-259726","number":"259726","sourceNumber":"259726","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"M.I.S.A., 78 anos, refere fraqueza intensa, náuseas, vômitos e cefaleia. Antecedentes\nde hipertensão arterial sistêmica, diabetes\nmellitus e hipercolesterolemia, em tratamento com\nanlodipina 10 mg, hidroclorotiazida 25 mg, bisoprolol 10 mg, empaglifozina 25 mg, sinvastatina 40\nmg e clopidogrel 75 mg com início há uma semana de ramipril 5 mg ao dia. Relata procedimento\ncirúrgico há 1 ano devido à obstrução de carótida. É ex-tabagista em abstinência há 1 ano (35\nmaços/ano). Ao exame: estado geral regular, hipocorada (1+/4+), desidratada (1+/4+), peso = 72\nkg, pressão arterial = 180 x 100 mmHg, saturação de oxigênio = 96%, frequência cardíaca = 70\nbatimentos/minuto, frequência respiratória = 22 incursões/minuto, temperatura = 36,6ºC; restante\ndo exame físico sem alterações, exceto por edema em membros inferiores (2+/4+). Exames\nlaboratoriais: hemoglobina = 10,5 g/dl (Valor de Referência (VR) 13?16 g/dl), creatinina = 2,8 mg/dl\n(VR 0,6?1,2 mg/dl), glicose = 181 mg/dl (VR 70?100 mg/dl), potássio = 5,2 mmol/L (VR 3,5?5,5\nmmol/L), cálcio iônico = 0,98 mmol/L (VR 1,17?1,3 mmol/L), fósforo = 4,5 mg/dl (VR 2,5?4,5 mg/dl),\nureia = 119 mg/dl (VR 16?40 mg/dl), pH = 7,28 (VR 7,35?7,45), pO? = 79 mmHg (VR 80?100\nmmHg), pCO? = 32 mmHg (VR 35?45 mmHg), HCO? = 15 mEq/L (VR 22?26 mEq/L), BE = -6\n\nmEq/L (-3 a +3 mmol/L), sumário de urina com densidade de 1.010 (VR 1.005?1.030), proteína 2+\n(VR negativo), hemácias 5 por campo (VR até 2 p/c) e leucócitos 20?30 por campo (VR 2?5 p/c);\nsedimento urinário com cilindros granulares e cilindros de células epiteliais. Ultrassonografia de\nabdômen mostra rins de tamanhos normais. Qual o diagnóstico e conduta mais adequados para o\ncaso clínico acima?","options":{"A":"Infecção do trato urinário ? iniciar antibioticoterapia empírica.","B":"Nefropatia diabética crônica ? otimizar tratamento conservador.","C":"Insuficiência renal aguda secundária a encefalopatia hipertensiva ? otimizar tratamento\nanti-hipertensivo.","D":"Necrose tubular aguda secundária ao uso de inibidor da ECA ? suspender ramipril e considerar\ninvestigação com doppler de artérias renais."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81304","number":"81304","sourceNumber":"81304","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 32 anos apresentava cefaleia e disartria há 3 semanas. Há 12 dias fez\numa tomografia computadorizada com contraste endovenoso, que revelou um tumor cerebral\nvolumoso. Há 24h foi admitido no hospital por estado epiléptico, tipo grande mal, controlado com\nfenitoína. Evolui com dores difusas pelo corpo e oligúria nas últimas 12 horas. Seus exames\nmostram hemoglobina 10 g/dl, Aspartatoaminotransferase (AST), Desidrogenase Láctica (LDH) e\nácido úrico elevados. Seu sumário de urina mostra hemoglobina +++ com 3 hemácias por campo.\nHaptoglobina 300 mg/dl (ref. 36 a 195 mg/dl), ureia 95 mg/dl e creatinina 10,2 mg/dl. Qual a causa\nmais provável da insuficiência renal desse paciente?","options":{"A":"Lise tumoral.","B":"Rabdomiólise.","C":"Hemólise intravascular.","D":"Toxicidade pelo contraste radiológico."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-65774","number":"65774","sourceNumber":"65774","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente foi submetido ao tratamento quimioterápico para linfoma de Burkitt. Após a\nprimeira sessão de quimioterapia e suporte terapêutico adequado, apresentou diminuição da\ndiurese para 200 ml/24h e aumento de 20% do seu peso usual. Queixava-se de adinamia. Ao\nexame físico: peso: 40 kg, pressão arterial: 120/80 mmHg, presença de adenopatia cervical.\n\nLaboratorialmente evidenciava hipocalcemia (cálcio total de 7,8 mg/dl); hiperfosfatemia (PO4--: 8,0\nmg/dl); hiperuricemia (ácido úrico: 15,6 mg/dl); aumento da creatinina sérica para 3,6 mg/dl (antes\ndo tratamento era 0,6 mg/dl), hipercalemia (5,8 mg/dl) e bicarbonato de 17 mEq/L. Sedimentoscopia\nurinária: numerosos cristais de ácido úrico. O eletrocardiograma está reproduzido na figura abaixo.\nO estudo ecográfico abdominal e renal foi normal. A conduta inicial mais adequada ao caso seria\nprescrever: (VER IMAGEM)","options":{"A":"alopurinol.","B":"hemodiálise.","C":"gluconato de cálcio.","D":"insulina IV e glicose.","E":"bicarbonato de sódio."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-51171","number":"51171","sourceNumber":"51171","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 68 anos, diabética, procurou a emergência com dor lombar, mialgia\ngeneralizada, febre e calafrios. Encontrava-se\ntaquicárdica, hipotensa e com volume urinário de 250\nml/dia. Exames laboratoriais apresentavam uma proteína C-reativa elevada; hemograma com\nleucocitose; ureia e creatinina elevadas. Uma urografia excretora evidenciou imagem tipo ?ring\nshadow?. Qual o diagnóstico mais provável?","options":{"A":"Abscesso renal.","B":"Pielonefrite aguda.","C":"Tuberculose renal.","D":"Necrose de papila renal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-36996","number":"36996","sourceNumber":"36996","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 65 anos, portador de diabetes mellitus tipo 2, necessita de realização de\ntomografia contrastada. Qual das estratégias abaixo é a mais efetiva na proteção da função renal?","options":{"A":"Uso de n-acetilcisteína IV.","B":"Hidratação venosa com solução salina.","C":"Uso de corticoides e anti-histamínicos.","D":"Uso de gadolínio no lugar de contraste iônico."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-30861","number":"30861","sourceNumber":"30861","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Menina, 1 ano e 6 meses, apresenta poliúria e deficit ponderoestatural. Os exames\nlaboratoriais revelam alcalose metabólica\nhipoclorêmica e hipocalêmica e níveis elevados de renina\ne aldosterona. Esse quadro corresponde, provavelmente, a:","options":{"A":"Síndrome de Bartter.","B":"Síndrome de Fanconi.","C":"Acidose tubular renal.","D":"Diabetes insipidus nefrogênico.","E":"Galactosemia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-37435","number":"37435","sourceNumber":"37435","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O raquitismo é uma doença óssea. Possui múltiplas etiopatogenias, dentre as quais\npodemos citar as doenças gastrointestinais que cursam com má absorção, EXCETO:","options":{"A":"Doença celíaca.","B":"Fibrose cística do pâncreas.","C":"Síndrome de Fanconi.","D":"Espru.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-196682","number":"196682","sourceNumber":"196682","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Determinado paciente de 32 anos de idade, advogado, refere que iniciou a prática de\ntreinamento resistido com enfoque em hipertrofia muscular há cerca de 10 anos, assim como\ncorrida de 30 minutos cinco vezes por semana, associados ao uso de suplementação nutricional de\nwhey protein (30 g/dia) e creatina (5 g/dia). O paciente possui 1,70 m de altura e 95 kg de peso\ncorporal. A medida da circunferência abdominal é de 85 cm. A frequência cardíaca é de 62 bpm, a\nfrequência respiratória é de 16 irpm e a saturação de oxigênio equivale a 98%. Apresenta exames\nlaboratoriais solicitados por outro médico, por \"rotina\", com os seguintes Valores de Referência\n(VR) do laboratório de realização: creatinina de 1,4 mg/dl (VR: 0,7?1,3); ureia de 45 mg/dl (VR:\n10?40); creatinofosfoquinase de 500 U/L (VR: 22?344); e Exame Sumário de Urina (ESU, EQU,\nurina tipo I, urinálise) sem alterações. Relata um consumo proteico de cerca de 200 g por dia, na\nforma de cerca de 1 kg de peito de frango. Com base nos dados apresentados nesse caso clínico e\nnos conhecimentos médicos correlatos, julgue o item a seguir. O aumento da creatinofosfoquinase\né comum nesse tipo de paciente, não despertando necessidade de investigações adicionais.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-334878","number":"334878","sourceNumber":"334878","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma paciente de 20 anos de idade apresenta perda aguda da função renal, associada\na automedicação com anti-inflamatório, sendo feito o\ndiagnóstico de nefrite intersticial aguda.\n\nAcerca dessa condição nefrológica, assinale a alternativa correta.","options":{"A":"Eosinofília constitui manifestação clínica sugestiva do referido diagnóstico.","B":"O exame sumário de urina (EAS) dessa paciente costuma mostrar-se normal.","C":"O aumento difuso dos rins, visto na tomografia computadorizada, representa a confirmação de\ncerteza do diagnóstico de afecção renal.","D":"A maioria dos pacientes nos quais o citado diagnóstico é confirmado evolui para insuficiência\nrenal crônica terminal.","E":"Cerca de 75% dos casos estão relacionados a comprometimento associado de outros órgãos,\ncomo pele e pulmão."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-206129","number":"206129","sourceNumber":"206129","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente no terceiro pós-operatório de ponte aorto-bifemoral evoluiu com rabdomiólise,\napresentou a seguinte alteração eletrocardiográfica. Qual distúrbio eletrolítico é mais provável?","options":{"A":"Hipocalcemia.","B":"Hipocalemia.","C":"Hipercalemia.","D":"Hipercalcemia."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-159603","number":"159603","sourceNumber":"159603","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, obeso mórbido, portador de dislipidemia, hipertenso,\ndiabético, com IMC de 43%, em uso contínuo\ndiário de metformina 850 mg, losartana sódica 50 mg,\nhidroclorotiazida 100 mg e sinvastatina em dose dobrada, foi submetido a tratamento cirúrgico da\nobesidade com a realização de cirurgia de Fobi-Capella por via aberta. O procedimento cirúrgico\nteve duração de 4 horas e 35 minutos, sem incidentes. No primeiro dia do pós-operatório, o\npaciente passou a sentir dor lombar associada a empastamento muscular. Constatou-se, então,\nque o paciente apresenta insuficiência renal aguda, sendo necessária a realização de hemodiálise.\nApós avaliação laboratorial adequada, atestou-se de que se tratava de um caso de rabdomiólise\naguda. Com base no caso clínico apresentado, julgue o seguinte item. O uso de doses elevadas de\nestatinas durante o pré-operatório é motivo para o aparecimento de rabdomiólise no pós-operatório\ndo paciente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-129014","number":"129014","sourceNumber":"129014","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente com 23 anos de idade foi vítima de acidente ofídico e procurou\natendimento médico queixando-se de pouca dor\nno local da picada, boca seca, diplopia, dificuldade\nde deglutição, dores musculares generalizadas, oligúria e urina com coloração vermelha escura. Ao\nexame, apresentou ptose palpebral bilateral, midríase e plegia dos pares cranianos III, IV e VI. O\nresultado do exame de urina evidenciou mioglobinúria. Com base nesse caso hipotético, assinale a\nalternativa que apresenta o tipo de acidente ofídico descrito.","options":{"A":"Crotálico.","B":"Botrópico.","C":"Laquético.","D":"Elapídico.","E":"Colubrídeo."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-75526","number":"75526","sourceNumber":"75526","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem com 27 anos de idade, sem antecedentes patológicos, é admitido no Hospital\ncom quadro de dor e edema em membros\ninferiores. O paciente informa ter corrido uma maratona\nsob tempo chuvoso há cinco dias. O paciente relata também redução do volume urinário e urina de\ncoloração escura. No dia anterior à hospitalização, apresentou náuseas, vômitos e tremores de\nextremidades. O exame físico não mostra outras alterações além da dor à compressão de\nestruturas musculares e da PA = 150 x 90 mmHg. Os exames iniciais mostram: (VER IMAGEM) O\nraio X de tórax e a ultrassonografia de abdome foram normais. Com base nos dados apresentados,\no diagnóstico e a conduta inicial a ser tomada são, respectivamente:","options":{"A":"Leptospirose; hemodiálise.","B":"Polimiosite; glicocorticoides.","C":"Rabdomiólise; hidratação endovenosa.","D":"Desidratação; hidratação endovenosa.","E":"Síndrome hepatorrenal; albumina associada à\nterlipressina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-291634","number":"291634","sourceNumber":"291634","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, com 15 anos de idade, relatou ser portador de hipertensão arterial de difícil\ncontrole há 1 ano. Na ocasião, ele não apresentou outras queixas. Os exames laboratoriais por ele\nrealizados revelaram potássio = 2,8 mEq/L, sódio = 148 meq/L, creatinina = 0,8 mg/dl, ureia = 27\nmg/dl, pH = 7,52, bicarbonato = 38, pCO? = 45 (gasometria arterial), aldosterona sérica e urinária\nnormais e atividade de renina baixa. Considerando o quadro clínico e os resultados dos exames\nlaboratoriais apresentados, assinale a opção CORRETA.","options":{"A":"Nesse caso, é recomendada a administração de amilorida, pois a resposta ao uso de\nespironolactona será ruim (Síndrome de Liddle).","B":"Esse paciente deve ser submetido à tomografia computadorizada, para diferenciação entre\nhiperplasia bilateral de adrenal e adenoma de adrenal.","C":"Provavelmente, esse é um caso de apresentação atípica de hiperaldosteronismo primário.","D":"A presença de alcalose metabólica e hipocalemia, nesse caso, afasta o diagnóstico de síndrome\nde Bartter.","E":"Um provável diagnóstico, nesse caso, consiste na síndrome de Giltelman, desordem\nautossômica recessiva, caracterizada pela falha da Bomba Na/K/2CL."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-172818","number":"172818","sourceNumber":"172818","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A principal causa da hipertensão renovascular é:","options":{"A":"Aterosclerose de artéria renal.","B":"Displasia fibromuscular.","C":"Arterite de Takayasu.","D":"Dissecção da aorta."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-351610","number":"351610","sourceNumber":"351610","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"De acordo com as diferentes fases em que a necrose tubular aguda ocorre, o momento\nque se pode observar a diferenciação das\nstem cells em células tubulares renais, é:","options":{"A":"Na fase inicial, quando também ocorrem alterações da reatividade vascular e da perfusão renal.","B":"Na fase de extensão, quando esse processo leva à ativação das células residentes, como\ncélulas dentríticas, macrófagos, células endoteliais e células epiteliais levando a um estado\npró-inflamatório.","C":"Na fase de manutenção, em que a restauração das células tubulares é acompanhada pela\nreferenciação e proliferação das células tubulares adjacentes.","D":"Na fase de reparação, quando a polaridade e a função são as últimas a serem reconstituídas."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-155486","number":"155486","sourceNumber":"155486","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em um paciente, com 22 anos de idade, apresentando cãimbras, fraqueza muscular e\nnormotensão arterial, os achados laboratoriais mostraram hipopotassemia (K = 2,5 mEq/L), renina e\naldosterona elevadas no sangue, alcalose metabólica, hipomagnesemia e excreção reduzida de\ncálcio na urina. Pela anamnese e pelas dosagens na urina, foram afastadas as possibilidades de\nvômitos sub-reptícios e abuso de diuréticos. A hipótese diagnóstica mais provável para explicar os\nachados clínicos e laboratoriais, nesse caso, é de:","options":{"A":"Síndrome de Bartter clássica.","B":"Síndrome de Gilteman.","C":"Hiperaldosteronismo primário.","D":"Síndrome de Liddle.","E":"Síndrome de Fanconi."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106397","number":"106397","sourceNumber":"106397","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 70 anos apresenta quadro de desidratação. Sua creatinina na\nadmissão era de 3,5 mg/dl e, após hidratação vigorosa, caiu para 2,1 mg/dl, dois dias após a\nadmissão. Ele está melhor, mas relata dor intensa na região dorsal. O clínico responsável pelo\npaciente prescreveu ibuprofeno para a analgesia. Por qual mecanismo este medicamento pode\ncomprometer a função renal deste paciente?","options":{"A":"Vasoconstrição da arteríola renal aferente.","B":"Vasodilatação arteriolar renal aferente.","C":"Vasoconstrição arteriolar renal eferente.","D":"Toxicidade tubular proximal.","E":"Obstrução ureteral."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106404","number":"106404","sourceNumber":"106404","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente hipertenso e diabético de 60 anos vai se submeter a um cateterismo\ncardíaco daqui a 4 horas. Na avaliação\npré-procedimento, você identifica que ele tem um clearence\nde creatinina estimado de 30 ml/minuto por 1,73 m². Ele não tem insuficiência renal aguda. Qual\ndas medidas abaixo irá DEFINITIVAMENTE reduzir o risco de nefropatia induzida por contraste\nneste paciente?","options":{"A":"Dopamina.","B":"Fenoldopam.","C":"Indometacina.","D":"N-acetilcisteína.","E":"Bicarbonato de sódio."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-9379","number":"9379","sourceNumber":"9379","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Quais das doenças abaixo podem diminuir o débito urinário quando associadas ao\nDiabetes Insípido?","options":{"A":"Mixedema e insuficiência supra-renal.","B":"Diabetes mellitus e dislipidemia.","C":"Diabetes mellitus e hipoparatireoidismo.","D":"Insulinoma e hiperparatiroidismo.","E":"Hipercortisolismo primário e secundário."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-316317","number":"316317","sourceNumber":"316317","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente deu entrada no PS com quadro de rash cutâneo, alteração da função renal, no\nhemograma com aumento dos eosinófilos, após uso de medicação (AINE), sendo feito diagnóstico\nde nefrite intersticial aguda. Quando solicitamos um EAS, qual o cilindro que esperamos encontrar\nnesse exame?","options":{"A":"Cilindro hemático.","B":"Cilindro hialino.","C":"Cilindro leucocitário.","D":"Cilindro epitelial."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-295362","number":"295362","sourceNumber":"295362","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 24 anos, 70 kg, portador de síndrome nefrótica desde os\n17 anos de idade, corticodependente.\nApresentou recidiva da síndrome nefrótica e foi optado por\nmanter prednisona em 10 mg por Via Oral (VO) pela manhã. Iniciado ciclosporina (CSA) por VO\n125 mg de 12/12h. Medicamentos já em uso pelo paciente e mantidos: enalapril 10 mg VO de\n12/12h, sinvastatina 20 mg VO à noite, vitamina D 1.000 U dia, carbonato de cálcio 500 mg VO.\nPaciente retornou ao pronto-socorro do hospital 15 dias após a introdução da CSA. Com queixa de\ndor no corpo, redução do volume urinário e urina de cor acastanhada. Os exames evidenciaram\nelevação da creatinina sérica de 1,0 mg/dl (basal) para 2,5 mg/dl. Qual o diagnóstico mais provável\ne o exame pra confirmação diagnóstica com base nas potenciais interações medicamentosas?","options":{"A":"Nefrite intersticial ? pesquisa de eosinófilos na urina.","B":"Cálculos renais ? ultrassonografia do aparelho urinário.","C":"Pré-renal ? cálculo da fração de excreção de sódio.","D":"Rabdomiólise ? dosagem de creatinofosfoquinase sérica."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-247423","number":"247423","sourceNumber":"247423","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 43 anos, portador de transtorno bipolar do humor em uso de lítio, evolui\ncom poliúria (diurese de 5.500 ml em 24 horas).\nAssinale a alternativa que apresenta,\nrespectivamente, a provável causa do aumento de débito urinário e a conduta mais adequada para\nmanejo do paciente:","options":{"A":"Nefrite intersticial aguda. Aumentar a ingesta hídrica para 6.000 ml/dia.","B":"Tubulopatia proximal. Administrar diurético de alça.","C":"Insuficiência adrenal. Iniciar fludrocortisona.","D":"Diabetes insipidus nefrogênico. Administrar diurético tiazídico."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-216997","number":"216997","sourceNumber":"216997","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na investigação da insuficiência renal aguda, o que indica a presença de cilindros\ngranulares na análise microscópica da urina?","options":{"A":"Proteinúria glomerular.","B":"Necrose tubular aguda.","C":"Hematúria glomerular.","D":"Nefrite intersticial aguda.","E":"Inflamação parenquimatosa."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-339762","number":"339762","sourceNumber":"339762","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 74 anos, diabético de longa data, estava internado para tratamento de\npielonefrite. Apesar de a urocultura ter confirmado que a bactéria era sensível ao antibiótico em\nuso, ele permanecia com picos febris no quarto dia de tratamento, quando apresentou hematúria\nmacroscópica e passou a evoluir com disfunção renal, apesar de estável hemodinamicamente. Que\ncomplicação poderia justificar essa evolução desfavorável?","options":{"A":"Abscesso perinefrético.","B":"Necrose cortical bilateral.","C":"Necrose papilar renal.","D":"Pielonefrite enfisematosa.","E":"Abscesso renal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-254220","number":"254220","sourceNumber":"254220","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Nefropatia autossômica recessiva em que há mutação no gene que codifica o\ncotransportador Na/2Cl. Acomete adultos e leva\na alcalose metabólica, hipocalemia, hipercalcemia,\nhipocalciúria e hipomagnesemia. É correto afirmar que a doença descrita trata-se de:","options":{"A":"Síndrome de Bartter.","B":"Síndrome de Gitelman.","C":"Síndrome de Fanconi.","D":"Doença de Hartnup."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-241698","number":"241698","sourceNumber":"241698","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 62 anos, em tratamento para diabetes mellitus e dislipidemia com\nmetformina, sinvastatina e ezetimiba, apresenta\nprostração, dores generalizadas e desidratação á\nadmissão hospitalar. Rastreio laboratorial com CPK 1770, urina de aspecto avermelhado. O\nprincipal mecanismo associado a tal patologia envolve:","options":{"A":"colúria.","B":"hemoglobinúria.","C":"litíase renal.","D":"lise muscular.","E":"necrose tubular aguda."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-202667","number":"202667","sourceNumber":"202667","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente vítima de acidente automobilístico chega\nhipotenso à unidade de emergência, com\nesmagamento do membro inferior direito. Em um primeiro\nmomento é indicada conduta conservadora quanto ao membro afetado. 24 horas após o\natendimento inicial, o paciente passa a apresentar o seguinte eletrocardiograma: Que medida deve\nser tomada imediatamente para este paciente?","options":{"A":"Amputação do membro comprometido.","B":"Infusão de solução cristaloide.","C":"Introdução de antibioticoterapia com aminoglicosídeo.","D":"Administração de bicarbonato de sódio."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-186501","number":"186501","sourceNumber":"186501","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 31 anos, vem em consulta ambulatorial de rotina. Nega\nqueixas e uso contínuo de medicamentos.\nRefere hábitos intestinais diários, evacuação sem\nanormalidades. Alega \"problema ósseo\" quando criança, mas não se lembra como foi tratado. Ao\nexame físico, PA 120 x 80 mmHg e demais sinais vitais dentro da normalidade. Chama a atenção a\nbaixa estatura. Após investigação clínica, forma solicitados exames complementares e o EAS\nenvidenciou pH urinário 3,5. Diante deste achado, o médico logo pensou que poderia estar diante\nde uma tubulopatia importante. Assim, realizou teste do bicarbonato, o qual foi positivo, com\nelevação do pH urinário a 7,4 após a ingesta de bicarbonato de sódio e solicitou eletrólitos e\ngasomentria arterial, com os seguintes resultados: Na+ sérico: 140 mEq/L (referência: 135 a 145\nmEq/L); K+ sérico: 2,9 mEq/L (3,5 a 5,1 mEq/L); Cl- sérico: 116 mEq/L (98 a 107 mEq/L); pH:\n\n7,28 (referência: 7,35 a 7,45); HCO?: 15 mEq/L (referência: 22 a 28 mEq/L); pO?: 90 mmHg; pCO?:\n30 mmHg; SpO?: 98% em ar ambiente. Diante\ndisso, pode-se afirmar que a principal hipótese\ndiagnóstica para o quadro clínico-laboratorial exposto é de:","options":{"A":"Acidose tubular rela do tipo I.","B":"Acidose tubular rela do tipo IV.","C":"Síndrome de Liddle (pseudo-hiperaldosterismo).","D":"Acidose tubular rela do tipo II."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-185137","number":"185137","sourceNumber":"185137","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A nefrite intersticial aguda está associada principalmente a","options":{"A":"sarcoidose","B":"hepatite C","C":"legionella","D":"medicamentos"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-187578","number":"187578","sourceNumber":"187578","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma mulher de 60 anos, portadora de diabetes melitus, será submetida a cateterismos\nde artérias coronárias. A conduta adequada na\nprevenção de injuria renal aguda por contraste é:","options":{"A":"solução salina, furosemida, contraste hiperosmolar.","B":"solução salina, N acetilcisteina, contraste isosmolar.","C":"bicarbonato de sódio, manitol, contraste isosmolar.","D":"bicarbonato de sódio, furosemida, contraste hiposmolar."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-150692","number":"150692","sourceNumber":"150692","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Leia o caso clínico a seguir: paciente do sexo masculino, de 70 anos, com história de\nfibrilação atrial, apresenta-se no pronto-socorro com dor no flanco esquerdo há várias horas. Ao\nexame clínico, sua temperatura é de 37,8°C. Nos exames laboratoriais, sua creatinina sérica é de\n1,8 mg/dl, e o exame de urina demonstra hematúria. Nesse caso clínico, qual é o diagnóstico?","options":{"A":"Trombose da artéria renal.","B":"Dissecção aórtica.","C":"Êmbolo na artéria renal.","D":"Glomerulonefrite."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-157324","number":"157324","sourceNumber":"157324","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São drogas que podem cursar com necrose tubular aguda, EXCETO:","options":{"A":"Metotrexate.","B":"Anfotericina B.","C":"Ceftazidima.","D":"Ciclosporina.","E":"Gentamicina."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-157001","number":"157001","sourceNumber":"157001","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"No comprometimento renal das colagenoses, pode-se dizer que:","options":{"A":"A glomerulonefrite difusa com síndrome nefrítica é comum pacientes com artrite reumatoide.","B":"A necrose tubular aguda é comum em pacientes com lúpus.","C":"A glomerulonefrite rapidamente progressiva é típica na espondilite anquilosante.","D":"A nefrite intersticial crônica pode ocorrer na síndrome de Sjögren primária\n\n."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-127604","number":"127604","sourceNumber":"127604","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, de 38 anos, procurou a Unidade de Pronto Atendimento\n(UPA) devidoà urina cor de ''coca-cola'' há 12\nhoras. Nega febre e edema. Refere mialgia. Faz uso\nde atorvastatina e correu 20 quilômetros há dois dias. Ao exame, hidratado; PA = 120 x 75 mmHg;\nFC = 84 bpm. Exames realizados: hematócrito = 43%; Hg = 14,5 g/dl; leucócitos = 8.500; plaquetas\n\n= 210.000. Creatinina sérica = 2,2 mg/dl; sódio urinário = 82 mEq/L; exame de urina: D = 1.015; pH\n\n= 6,0; proteínas = negativo; hemoglobina = ++/4; leucócitos = 2.000/ml; hemácias = 1.000 m/L. O\ndiagnóstico provável e o mecanismo patogênico envolvido são:","options":{"A":"Necrose tubular aguda; rabdomiólise.","B":"Glomerulonefrite aguda; pós-infecciosa.","C":"Lesão renal aguda pré-renal; depleção de volume.","D":"Nefrite intersticial aguda; uso de estatina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-111388","number":"111388","sourceNumber":"111388","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação ao tratamento das rabdomiólises, que conduta não pode ser tomada?","options":{"A":"Reposição hídrica agressiva.","B":"Acidificação da urina.","C":"Correção da hiperpotassemia.","D":"Correção da hiperfosfatemia.","E":"Hemodiálise (se necessário)."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-112386","number":"112386","sourceNumber":"112386","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual é a causa mais frequente de necrose tubular aguda?","options":{"A":"Lesão isquêmica.","B":"Lesão tóxica.","C":"Lesão intersticial.","D":"Lesão infiltrativa."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-111396","number":"111396","sourceNumber":"111396","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação aos diuréticos, que alternativa é incorreta?","options":{"A":"Triantareno diminui a absorção de sódio nos túbulos distais terminais.","B":"Furosemida diminui a absorção de sódio, potássio e cloro na alça.","C":"Acetazolamida diminui a absorção de sódio nos túbulos proximais.","D":"Espironolactona é um agonista da aldosterona.","E":"Amilorida é um não antagonista da aldosterona e age nos túbulos distais terminais."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-109326","number":"109326","sourceNumber":"109326","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual das drogas a seguir costuma induzir nefrite intersticial aguda, que se manifesta\ncomo síndrome nefrótica?","options":{"A":"Fenoprofeno.","B":"Omeprazol.","C":"Amoxicilina.","D":"Ciprofloxacina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83797","number":"83797","sourceNumber":"83797","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Assinale a alternativa incorreta sobre insuficiência renal:","options":{"A":"São sintomas de uremia crônica: prurido cutâneo, pericardite e anemia.","B":"A ureia é metabólito excretado primariamente pelos rins, sendo o mais importante do\ncatabolismo de proteínas.","C":"São sintomas de insuficiência renal aguda: anorexia, náuseas, soluço, vômitos, hematêmese.","D":"Agentes de contraste radiológico não apresentam relação com insuficiência renal aguda.","E":"Diabetes mellitus, hipertensão, glomerulonefrite crônica são as etiologias mais frequentes de\ninsuficiência renal crônica."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84589","number":"84589","sourceNumber":"84589","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Dentre as causas de Insuficiência Renal Aguda Nefrotóxica Exógena estão, exceto:","options":{"A":"Aminoglicosídeos.","B":"Cisplatina.","C":"Tetracloreto de Carbono.","D":"Anfotericina B.","E":"Quinolonas."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-78080","number":"78080","sourceNumber":"78080","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, de 68 anos, portador de diabetes mellitus tipo 2 e\nhipertensão arterial, em uso de losartana e repaglinida, apresenta creatinina sérica 1,7 mg/dl\n(filtração glomerular estimada de 42 ml/min). Será submetido a cateterismo cardíaco para\ninvestigação de doença coronariana. Quanto às recomendações de profilaxia para lesão renal\naguda, sugeridas pela KDIGO Clinical Practice Guideline for Acute Kidney Injury, 2012, deve-se\nutilizar solução salina isotônica endovenosa associada a:","options":{"A":"N-acetilcisteína via oral.","B":"Contraste iodado com alta osmolaridade.","C":"Teofilina endovenosa.","D":"Suspensão da repaglinida."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-85328","number":"85328","sourceNumber":"85328","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente com 57 anos, sexo feminino, diabética há 10 anos, em uso de\nhipoglicemiantes orais com controle\nsatisfatório da glicemia. Chega à emergência com história de\n\"dor no corpo\" há cerca de 4 dias, de início insidioso e progressivo. Associado ao quadro, queixa-se\nde \"dificuldade para urinar e urina avermelhada\" há 2 dias. Nega a disúria. Apresentou febre no\nperíodo (37.5°C) mal estar geral e prostração. Ao exame físico: apresenta dor à palpação dos\ngrupos musculares, generalizada. Edema +/4+ nos MMII; dispneia. Antecedentes pessoais: HAS\nem uso de atenolol e hidroclorotiazida. Hiperlipidemia, descoberta há um mês e vem usando\nestatina e fibrato desde então. Qual a melhor conduta?","options":{"A":"Iniciar paracetamol 750 mg de 6/6 horas.","B":"Solicitar exames: TGO, TGP, CPK, Mioglobina, ureia e creatinina.","C":"Iniciar com antidepressivo tricíclico.","D":"Solicitar Raio X de tórax, hemocultura e urocultura."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-61267","number":"61267","sourceNumber":"61267","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com respeito à nefrite intersticial aguda, identifique a alternativa correta:","options":{"A":"os anti-inflamatórios não esteroides desencadeiam nefrite intersticial crônica, mas não a nefrite\nintersticial aguda.","B":"a doença é comum, sendo responsável por cerca de metade dos casos de hematúria e\nproteinúria associada.","C":"a nefrite intersticial por drogas se estabelece dias a semanas após o início do tratamento.","D":"são comuns níveis de proteinúria maciça (acima de 3 g/24h), embora possam ocorrer casos de\nproteinúria discreta.","E":"o tratamento com altas doses de imunossupressores, por tempo prolongado, normalmente não\naumenta o risco de infecções sérias ou mortais."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-61265","number":"61265","sourceNumber":"61265","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A causa mais comum de hipertensão renovascular no jovem é:","options":{"A":"Arterite renal.","B":"Coarctação da aorta.","C":"Displasia fibromuscular.","D":"Aterosclerose.","E":"Nefroangiite."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-51056","number":"51056","sourceNumber":"51056","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A furosemida age inibindo a reabsorção de sódio em qual das seguintes estruturas?","options":{"A":"Ducto coletor.","B":"Túbulo contorcido proximal.","C":"Túbulo contorcido distal.","D":"Parte descendente da alça de Henle.","E":"Parte ascendente da alça de Henle."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-51068","number":"51068","sourceNumber":"51068","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O senhor Onofre, 69 anos de idade, com hipertensão arterial de longa data\ndesenvolveu, em um período de seis meses,\nhipertensão arterial mais grave. Apesar da medicação\nanti-hipertensiva, sua pressão arterial costumeira passou de 140/90 mmHg para 170/110 mmHg.\n\nHá um mês, teve um episódio de \"edema pulmonar súbito\", que provocou sua hospitalização por\numa semana. O senhor Onofre continuou a tomar\nsua medicação anti-hipertensiva com aderência à\nprescrição após essa internação, mas desenvolveu claudicação intermitente na perna esquerda.\n\nEmbora o senhor Onofre seja tabagista de longa duração, não apresentou outros problemas\nclínicos. Qual é a causa mais provável do distúrbio clínico apresentado pelo senhor Onofre?","options":{"A":"Feocromocitoma.","B":"Coarctação da aorta.","C":"Estenose da artéria renal.","D":"Agravamento primário da pressão arterial.","E":"Hiperaldosteronismo primário."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-48495","number":"48495","sourceNumber":"48495","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 70 anos apresentou diarreia evoluindo com desidratação e posterior\ndisfunção renal. Os exames laboratoriais\nrevelaram ureia sérica 90 mg/dl, creatinina sérica 2,4\nmg/dl, Na urinário > 40 mEq/L, fração de excreção de Na > 1%, osmolaridade urinária 250 mOsm/L.\nO diagnóstico compatível é:","options":{"A":"Necrose tubular aguda.","B":"Pielonefrite.","C":"Azotemia pré-renal.","D":"Glomerulonefrite aguda.","E":"NDA."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-48826","number":"48826","sourceNumber":"48826","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Assinale a alternativa que responde corretamente a pergunta abaixo. Vários membros\nde uma família apresentam alcalose\nmetabólica hipocalêmica. Qual dos seguintes achados, se\npresente em todos os membros da família afetados, seria mais sugestivo ao diagnóstico de\nSíndrome de Gitelman?","options":{"A":"Hiperuricosúria","B":"Hipercalciúria","C":"Hipomagnesemia","D":"Fraqueza muscular severa","E":"Apresentação no recém-nato"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-48831","number":"48831","sourceNumber":"48831","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Assinale a alternativa que indica a melhor conduta na prevenção da nefropatia por\ncontraste.","options":{"A":"Infusão de 2 µcg/kg/min de dopamina.","B":"Infusão de furosemida 5 mg/h.","C":"Administração de n-acetilcisteína.","D":"Hemodiálise profilática.","E":"Administração endovenosa de soluções salinas como SF ou Bicarbonato de sódio."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-53582","number":"53582","sourceNumber":"53582","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Que droga é usada para o tratamento do diabetes insipidus durante a gravidez?","options":{"A":"Angiotensiva.","B":"Acetato de desmopressiva (DDAVP).","C":"Ocitocina.","D":"Renina.","E":"Metformina."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22968","number":"22968","sourceNumber":"22968","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Das doenças enumeradas abaixo, a que NÃO está relacionada a fenômenos\ntromboembólicos para as extremidades é:","options":{"A":"o infarto agudo do miocárdio.","B":"a cardiopatia chagásica.","C":"a arritmia cardíaca.","D":"a hipertensão renovascular."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-23023","number":"23023","sourceNumber":"23023","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente do sexo masculino, com 28 anos, está em tratamento com\npoliquiomioterapia para hanseníase (dapsona,\nrifampicina e clofazimina). Apresentou, no quarto\nmês de tratamento, diminuição do volume urinário, rash cutâneo, dor lombar e elevação de ureia e\ncreatinina. O diagnóstico mais provável, nesse caso, é:","options":{"A":"Glomerulonefrite crescêntica associada à hanseníase.","B":"Nefrite intersticial aguda por rifampicina.","C":"Necrose tubular aguda associada à dapsona.","D":"Síndrome hemolítica-urêmica associada à clofazimina."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-218041","number":"218041","sourceNumber":"218041","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São achados na síndrome de Fanconi, EXCETO:","options":{"A":"Fosfatúria.","B":"Glicosúria.","C":"Poliúria.","D":"Acidose metabólica hiperclorêmica.","E":"Alcalose metabólica hipoclorêmica."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-216361","number":"216361","sourceNumber":"216361","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, soldado do exército, estava acompanhado há 10 dias em\ntreinamento para titulação como paraquedista e é trazido por seus companheiros ao\n\npronto-atendimento, com relato de mialgia intensa e ausência de eliminação urinária de hoje. Ao\nexame,o paciente encontra-se desidratado e apresenta edema importante na coxa esquerda, com\nbastante dor à palpitação.Não há edema de membro inferior contralateral. Ausculta\ncardiorrespiratória é normal. Laboratório revela creatinina de 6,9 mg/dL, ureia de 220 mg/dL e CK\ntotal de 12.000 U/L, ácido úrico de 8,5 mg/dL, potássio de 5,9 mg/dL, cálcio de 7,8 mg/dL. EAS com\ncilindros hialinos, com hemoglobinúria e sem hematúria. Neste momento, ESTÁ INDICADA:","options":{"A":"Infusão de bicarbonato de sódio.","B":"Administração intravenosa de manitol.","C":"Hemodiálise.","D":"Hidratação vigorosa com soro fisiológico"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84881","number":"84881","sourceNumber":"84881","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre a Hipertensão Arterial Sistêmica e o seu tratamento: I - A decisão terapêutica\ndeve ser baseada no risco cardiovascular\nconsiderando-se a presença de fatores de risco, lesão\nem órgão-alvo e/ou doença cardiovascular estabelecida, e não apenas no nível da PA. II - Os\nalfabloqueadores atuam sobre a musculatura da parede vascular, promovendo relaxamento\nmuscular com consequente vasodilatação e redução da resistência vascular periférica. São\nutilizados em associação com diuréticos e/ou betabloqueadores. Hidralazina e metildopa são dois\ndos principais representantes desse grupo. III - Os Inibidores da Enzima Conversora da\nAngiotensina (IECA) quando usados em indivíduos com DRC, podem eventualmente agravar a\nhiperpotassemia. Em pacientes com hipertensão renovascular bilateral ou unilateral associada a rim\núnico podem promover redução da filtração glomerular com aumento dos níveis séricos de ureia e\ncreatinina. IV - O uso dos IECA em pacientes com função renal reduzida pode causar diminuição de\naté 30% da creatinina, mas a longo prazo preponderá seu efeito nefroprotetor. Marque a alternativa\nCORRETA:","options":{"A":"As alternativas I, III e IV estão corretas.","B":"Todas as alternativas estão corretas.","C":"As alternativas I, II e III estão corretas.","D":"As alternativas I, II e IV estão corretas.","E":"As alternativas I e III estão corretas."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-140034","number":"140034","sourceNumber":"140034","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma paciente de 66 anos de idade, portadora de doença arterial crônica, após ser\nsubmetida à angioplastia coronária bem-sucedida com a colocação de 4 stents. Cinco dias após o\nprocedimento, apresentou lesões de pele caracterizadas como livedo reticular em membros\ninferiores, foi reinternada e constatada elevação dos níveis de creatinina sérica e de ureia. Sobre\nesta condição, podemos afirmar que:","options":{"A":"Estes achados provavelmente resultaram de fragmentos das placas ateroscleróticas tratadas\nnas coronárias.","B":"A eosinofilia transitória pode fazer parte dessa síndrome.","C":"Geralmente não há consumo de complemento sérico.","D":"No tratamento desta condição há uma resposta dramática aos corticoides.","E":"É uma condição limitada e sua progressão para insuficiência renal em estágio terminal nunca\nacontece."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-89227","number":"89227","sourceNumber":"89227","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com relação à rabdomiólise, é incorreto afirmar:","options":{"A":"É uma importante causa de insuficiência renal aguda","B":"O uso de etanol consiste na causa mais comum dentre as drogas e toxinas que causam\nrabdomiólise","C":"A combinação de estatinas e fibrato implica aumento de risco de rabdomiólise","D":"A determinação sérica de mioglobina é melhor que a de CPK na avaliação da rabdomiólise","E":"Durante o tratamento o volume de fluidos necessário pode chegar a 10-14 L/dia ou mais"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-87606","number":"87606","sourceNumber":"87606","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo feminino, 64 anos, hipertensa e coronariopata, abriu quadro de dor\nabdominal moderada há 3 dias. Hoje pela manhã notou pronunciada piora da dor abdominal, iniciou\nsubitamente uma dor descrita como insuportável em primeiro pododáctilo esquerdo e começou a\napresentar vômitos recorrentes, cefaléia e confusão mental. Acompanhante comenta ainda não ter\nobservado exteriorização de diurese pela paciente hoje. Informa que há 11 dias foi submetida a\numa cineangiocoronariografia (cateterização femoral esquerda), com colocação de stent não\nfarmacológico em 1/3 proximal da A. descendente anterior, e vinha evoluindo sem precordialgia\ndesde então. Faz uso de AAS 100 mg/d, Clopidogrel 75 mg/d (este último recém-iniciado após o\nprocedimento descrito), Losartana 100 mg/d, Atenolol 50 mg/d e Atorvastatina 80 mg/d. Exame\nfísico revela uma paciente corada, com edema bipalpebral e de MMII, acianótica, com FR de 24\nirpm, sem esforço. A PA é de 170 X 100 mmHg, FC de 68 bpm. Observam-se ainda pulmões\nlimpos, e ausculta cardíaca com B4, sem sopros. Pulsos pediosos palpáveis. Perfusão capilar\nperiférica lentificada em primeiro pododáctilo esquerdo. Laboratório de entrada: Hb: 13,6; 13.800\nleucócitos, sendo 74% PMN e 10% de eosinófilos, sem desvio à esquerda; 162.000 plaquetas; Na:\n135 mEq/L; K: 6,6 mEq/L Creatinina: 3,1 mg/dl; U: 96 mg/dl; Gli:120 mg/dl; amilase elevada.\n\nTroponina I normal; CK total (300 U/L); CK-MB normal; EAS com cilindros granulosos e piúria.\nECG: sobrecarga volumétrica do VE, apenas. Rx\ntórax: hilos pulmonares ingurgitados, área\ncardíaca normal. Pergunta-se: A alteração da função renal no caso acima mais provalvemente se\ndeve a:","options":{"A":"Ateroembolismo por colesterol;","B":"Vasculite sistêmica associada ao Clopidogrel;","C":"Dissecção de porção supra-renal de Aorta abdominal;","D":"Nefropatia por contraste;","E":"Rabdomiólise."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-65624","number":"65624","sourceNumber":"65624","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação à rabdomiólise, é CORRETO afirmar que:","options":{"A":"O consumo de álcool etílico é uma das mais importantes causas de miopatia e rabdomiólise,\nsendo responsável por 20% dos casos.","B":"A mioglobinúria é uma característica invariável da rabdomiólise e sua ausência exclui o\ndiagnóstico.","C":"Hiperfosfatemia e hipercalcemia são observadas precocemente com frequência na rabdomiólise.","D":"A dosagem da CK, por si só, já permite predizer quais pacientes progredirão para insuficiência\nrenal mioglobinúrica.","E":"A Coagulação Intravascular Disseminada (CIVD) é uma complicação que raramente ocorre na\nrabdomiólise."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-52179","number":"52179","sourceNumber":"52179","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual a principal medida na profilaxia da nefrotoxidade por contraste iodado?","options":{"A":"Fazer bicarbonato de sódio 1 ml/kg/H, EV, 12h antes e depois do procedimento.","B":"Hidratação com SF 0,9%.","C":"Suspender medicamentos nefróticos 48h antes do procedimento.","D":"Acetilcisteína 600 mg, VO, 6/6h.","E":"Acetilcisteína + Vitamina C."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-274120","number":"274120","sourceNumber":"274120","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, 52 anos, portadora de HAS, DM, tabagista, é submetida a implante\nendovascular de stent na aorta, sem\nintercorrências. Dois meses depois, a paciente queixa-se de\nmal-estar, manifestações em pele e dor lombar bilateral. Ao exame: orientada, hidratada, PA 130 x\n80 mmHg e sinais de má perfusão periférica com presença de livedo reticular e \"síndrome do dedo\nazul\". Exames: Hb 11,7 g/dl, leucócitos 9.200 (presença de eosinofilia), plaquetas 170.000/mm³,\ncreatinina sérica 3,2, ureia 110 e proteinúria de 400 mg/24h. Paciente foi internada em UTI com\npiora progressiva da função renal, porém mantendo débito urinário normal. Foram negativos na\ninvestigação complementar o fator antinuclear, p-ANCA, c-ANCA, assim como os complementos\nséricos (C3 e C4). Qual o diagnóstico para o caso descrito?","options":{"A":"Lúpus eritematoso sistêmico.","B":"Nefropatia por contraste.","C":"Doença renal ateroembólica.","D":"Nefropatia crônica do enxerto renal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-362835","number":"362835","sourceNumber":"362835","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 61 anos, renal crônico estádio IV por nefropatia diabética, já com fístula\narterio-venosa com bom frêmito em região braqui-basílica, é internado em unidade coronariana\npara realização de angioplastia. Ao exame físico encontra-se euvolêmico e com exames\n\nlaboratoriais com creatinina de 3,8 mg/dl; uréia de 103 mg/dl; sódio de 139 mEq/L e potássio de 4,9\nmEq/L. A melhor conduta para evitar nefropatia induzida pelo contraste é:","options":{"A":"n-acetilcisteína e bicarbonato oral","B":"n-acetilcisteína e aumentar ingesta hídrica","C":"hidratação pré e pós exposição ao contraste","D":"hemodiálise imediatamente após uso do contraste"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-327336","number":"327336","sourceNumber":"327336","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 28 anos, admitido na emergência com história de oligúria, urina escura,\nmialgia generalizada, náuseas e vômitos. Tabagista\n(20 maços/ano) e usuário de cocaína há 5\nanos, cerca de 4 vezes por semana. Nega uso de drogas injetáveis. Refere uso de cocaína\ninalatória ontem. Exame físico: orientado, desidratado ++/4+, FC= 110 bpm, FR= 20 irpm, PA=\n150x100 mmHg, Temp. axilar 36,8° C. Dor à palpação da musculatura difusamente em membros\ninferiores e avaliação da força muscular limitada pela dor. Demais achados do exame físico sem\nalterações. Em relação ao quadro clínico do paciente, qual a hipótese diagnóstica?","options":{"A":"Insuficiência renal aguda por rabdomiólise","B":"Nefrite intersticial aguda","C":"Glomerulonefrite difusa aguda","D":"Vasculite imune de grandes vasos"},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-208564","number":"208564","sourceNumber":"208564","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual é o contraste que usualmente é utilizado na ressonância magnética e qual é a\ndoença que ele pode ocasionar,\nrespectivamente:","options":{"A":"fluorodesoxiglicose (FDG-18); angioedema","B":"tecnécio-99m; exantema","C":"gadolínio; fibrose nefrogênica sistêmica","D":"FDG-18; diabetes mellitus","E":"gadolínio; artrite"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84996","number":"84996","sourceNumber":"84996","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 72 anos, diabética tipo 2, admitida no pronto-socorro com dor precordial, com\ndiagnóstico após 2 horas da admissão de Infarto Agudo do Miocárdio (IAM) com supra de ST.\nExames laboratoriais na admissão: ureia: 72 mg/dl; creatinina: 1,0 mg/dl; Na: 140 mEq/L; K: 4,0\nmEq/L; glicemia: 142 mg/dl. Realizou cineangiocoronariografia e angioplastia primária de lesão\noclusiva em 1/3 médio da artéria descendente anterior. Manteve estabilidade hemodinâmica na\ninternação. Após 48h do procedimento, apresentou elevação das escórias nitrogenadas e acidose\nmetabólica compensada. A causa mais provável da lesão renal aguda é:","options":{"A":"Diabetes Mellitus.","B":"Nefrotoxicidade.","C":"Hipovolemia.","D":"Hipoperfusão secundária ao IAM."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-88421","number":"88421","sourceNumber":"88421","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A síndrome de Fanconi é encontrada em qual região do néfron?","options":{"A":"Túbulo proximal.","B":"Alça de Henle.","C":"Ducto coletor.","D":"Túbulo contornado distal."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-88429","number":"88429","sourceNumber":"88429","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Dos medicamentos abaixo, qual não está associado à nefrite intersticial alérgica?","options":{"A":"Penicilinas.","B":"Eritromicina.","C":"Rifampicina.","D":"Sulfas."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-152347","number":"152347","sourceNumber":"152347","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 10 anos de idade, pesando 32 quilos, soropositivo para HIV de\ntransmissão vertical, apresenta diagnóstico de linfoma abdominal não Hodgkin há 1 semana. Fez\nquimioterapia há 4 dias. Hoje está hipoativo, hipotenso, desidratado, em anasarca, descorado e\nreferindo dor lombar à direita de forte intensidade. Tem diurese de 8 ml/hora; ureia de 205;\ncreatinina de 4,8; potássio de 6,1; cálcio de 8,2; ácido úrico urinário de 0,75 mg/dl; e gasometria\ncom acidose metabólica. Acerca desse caso, qual é o diagnóstico MAIS provável?","options":{"A":"Cálculo impactado em ureter distal.","B":"Cálculo coraliforme em pelve renal direita.","C":"Desidratação secundária a vômitos pós-quimioterapia.","D":"Síndrome da lise tumoral aguda."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-183452","number":"183452","sourceNumber":"183452","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Analise os itens a seguir. I. hidratação com soro fisiológico. II. acetilcisteína. III.\nbicarbonato de sódio. Assinale a alternativa que se refere ao(s) item(ns) que é(são)\ncomprovadamente eficaz(es) na prevenção de nefrotoxicidade por contraste.","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas I e II.","D":"Apenas II e III.","E":"I, II e III."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-45886","number":"45886","sourceNumber":"45886","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 40 anos, 72 kg, diabético, apresentando creatinina sérica: 3,0, está\nem avaliação cardiológica e necessita realizar um cineangiocoronariografia, devendo receber\ncontraste iodado. Nesta situação, pode-se afirmar:","options":{"A":"Não há risco de nefrotoxicidade, pois o paciente apresenta clearance estimado de creatinina\nmaior que 30 ml/min","B":"Hidratação com solução fisiológica 0,9% deverá ser prescrita e iniciada antes do exame para\nprevenção da nefrotoxicidade","C":"Este paciente deverá receber uma solução de hidratação hipotônica associada com dopamina, a\nfim de evitar nefrotoxicidade do contraste","D":"O exame está contraindicado neste paciente devido ao alto risco de nefrotoxicidade irreversível\npelo contraste","E":"Hidratação com solução hipertônica 3% constitui-se na melhor conduta na prevenção da\nnefrotoxicidade do contraste"},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34540","number":"34540","sourceNumber":"34540","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A etiologia da Lesão Renal Aguda (LRA) é diversa e pode ser devido a várias injúrias\nfisiológicas. Assinale a alternativa INCORRETA com relação às diferentes causas da insuficiência\nrenal aguda:","options":{"A":"A azotemia pré-renal é a causa mais comum de LRA e é responsável por cerca de 60 a 70% dos\ncasos adquiridos na comunidade e 40% dos\nadquiridos no hospital.","B":"A LRA intrínseca é classificada de acordo com o sítio histológico primário de lesão: túbulos,\ninterstício, vasculatura ou glomérulos.","C":"A lesão celular dos túbulos renais, comumente chamada de necrose tubular aguda, ocorre com\nmaior frequência quando há aumento do fluxo sanguíneo renal, embora os túbulos renais também\npossam ser danificados por toxinas renais específicas.","D":"A LRA secundária à lesão no interstício renal é chamada de nefrite intersticial aguda, sendo os\nmedicamentos comumente implicados: penicilinas, cefalosporinas e sulfonamidas.","E":"Em pacientes com lesão renal aguda pós-renal, a obstrução intraluminal pode ser vista em\npacientes com necrose papilar e coágulos de sangue, enquanto a obstrução extraluminal está\nassociada à fibrose retroperitoneal e aos linfomas."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22633","number":"22633","sourceNumber":"22633","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual das medidas para prevenir ou atenuar a insuficiência renal aguda mostrou-se\neficaz?","options":{"A":"dopamina em doses renais.","B":"infusão de fator natriurético atrial.","C":"infusão de soro fisiológico 0,9% previamente e após a infusão de contraste radiológico.","D":"diuréticos de alça endovenoso em altas doses.","E":"infusão de fator de crescimento semelhante à insulina."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-233817","number":"233817","sourceNumber":"233817","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 45 anos vai ao pronto atendimento queixando-se de mialgia difusa, fraqueza\nnos 4 membros e urina amarronzada em\nvolume reduzido. Possui dislipidemia e gota, e está em\nuso diário de sinvastatina e colchicina prescritos há 15 dias. Ao exame físico, apresenta FC = 115\nbpm; PA = 130/84 mmHg; FR = 21 irpm, SpO? em ar ambiente 95%, TAx 38,3ºC. Encontra-se\nalerta e orientado, com força muscular grau 4/5 nos grupos proximais de membros superiores e\ninferiores, e 5 nos grupos musculares distais. Exames de laboratório: Hb = 15,5 g/dl; LG =\n12.400/mm³; NS = 8.570/mm³; Linf = 2.030/mm³; PCR = 34 mg/L; Creat = 1,3 mg/dl; ureia = 55\nmg/dl; K+ = 5,7 mEq/L; CPK = 2.570U/L. Assinale a alternativa CORRETA sobre a fisiopatogênese\ndo quadro clínico em questão:","options":{"A":"A fraqueza muscular se deve principalmente à hipercalemia.","B":"A hipercalemia se deve principalmente à disfunção renal.","C":"A injúria renal aguda se deve aos níveis elevados de CPK.","D":"A lesão do miócito se deve ao uso da sinvastatina e da colchicina."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-174799","number":"174799","sourceNumber":"174799","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma adolescente de 15 anos desenvolveu quadro de amigdalite, motivo pelo qual lhe\nfoi prescrito amoxicilina. Vinha evoluindo\nbem, sendo que a adinofagia e a febre que\nacompanhavam a amigdalite desapareceram rapidamente após ter começado o tratamento. Porém,\numa semana após o início do antibiótico, passou a apresentar rash cutâneo, reaparecimento da\nfebre, mal-estar e redução do volume urinário. Procurou serviço de pronto atendimento e, ao\nexame, apresentava-se com temperatura axilar = 38,8ºC; pressão arterial = 115 x 75 mmHg;\nfrequência de pulso = 92 bpm e frequência respiratória = 16 irpm. Demais aspectos do exame físico\nsem alterações. Os exames complementares evidenciaram títulos elevados de antiestreptolisina O;\nmoderada eosinofilia; ureia = 51 mg/dl e creatinina = 2,37 mg/dl. O exame de urina revelou\n\nmicro-hematúria sem cilindros hemáticos, leucocitúria com numerosos eosinófilos e raros cilindros\nleucocitários. Dentre as opções abaixo, qual é o diagnóstico mais provável?","options":{"A":"Glomerulonefrite pós-estreptocócica.","B":"Necrose tubular aguda.","C":"Nefrite intersticial aguda.","D":"Pielonefrite aguda."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-155240","number":"155240","sourceNumber":"155240","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre as acidoses tubulares renais, é CORRETO afirmar que:","options":{"A":"Na ATR tipo 1, ou ATR proximal, o defeito está na reabsorção tubular proximal de bicarbonato.","B":"A ATR tipo 4 é caracterizada por um distúrbio misto que contém componentes de ATR proximal\ne distal.","C":"A ATR tipo 4 está associada a alterações relacionadas à aldosterona.","D":"Pode haver nefrocalcinose, mais observada quando há alterações de túbulo proximal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-233821","number":"233821","sourceNumber":"233821","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma mulher de 28 anos, previamente hígida, foi à UPA no dia 10 de abril de 2019\nqueixando-se de disúria, dor no flanco\ndireito e febre (38,4ºC). O exame de urina revelou 54\npiócitos/campo, 13 hemácias/campo e presença de bastonetes Gram-negativos. Optou-se pelo\ntratamento ambulatorial com ciprofloxacino. Evoluiu com melhora dos sintomas e da febre após 48h\ndo uso do medicamento. No dia 14 de abril, retornou à UPA com queixa de prurido generalizado,\nrecidiva da febre e edema de membros inferiores. Ao exame físico, apresentava PA = 120/70\nmmHg, FC = 89 bpm, FR = 17 irpm, SpO2 em ar ambiente 97%. Edema maleolar bilateral\ndepressível. O restante do exame físico não apresentava anormalidades. Exames de laboratório:\nem 10/04/2019: Hb = 13,1 g/dl; LG = 15.800/mm³; NS = 11.570/mm³; Linf = 2.450/mm³; Eos =\n360/mm³; Plq = 178.000/mm³; Creat = 1,1 mg/dl; ureia = 23 mg/dl. Urocultura: Escherichia coli,\n\n100.00 UFC/ml, resistente à ampicilina; sensível a ciprofloxacino, nitrofurantoína, cefalexina,\nceftriaxona, sulfametoxazol-trimetoprim e\namoxicilina-clavulanato. Em 14/04/2019: Hb = 13,5 g/dl;\nLG = 11.800/mm³; NS = 6.570/mm³; Linf = 2.890/mm³; Eos = 1.550/mm³; Plp = 160.000/mm³, Creat\n\n= 2,5 mg/dl; ureia = 32 mg/dl; K+ = 5,2 mEq/L. A injúria renal nesse caso se deve MAIS\nPROVAVELMENTE à:","options":{"A":"Glomerulonefrite pós-infecciosa.","B":"Necrose tubular aguda.","C":"Nefrite intersticial aguda.","D":"Pielonefrite aguda."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-233822","number":"233822","sourceNumber":"233822","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma mulher de 28 anos, previamente hígida, foi à UPA no dia 10 de abril de 2019\nqueixando-se de disúria, dor no flanco\ndireito e febre (38,4ºC). O exame de urina revelou 54\npiócitos/campo, 13 hemácias/campo e presença de bastonetes Gram-negativo. Optou-se pelo\ntratamento ambulatorial com ciprofloxacino. Evoluiu com melhora dos sintomas e da febre após 48h\ndo uso do medicamento. No dia 14 de Abril, retornou à UPA com queixa de prurido generalizado,\nrecidiva da febre e edema de membros inferiores. Ao exame físico, apresentava PA 120/70mmHg,\nFC 89bpm, FR 17irpm, SpO² em ar ambiente 97%. Edema maleolar bilateral depressível. O\nrestante do exame físico não apresentava anormalidades. Exames de laboratório: Em 10/04/2019:\nHb13,1g/dL; LG 15.800/mm³; NS 11.570/mm³; Linf 2.450/mm³; Eos 360/mm³; Plq 178.000/mm³;\nCreat 1,1mg/dL; Ureia 23mg/dL. Urocultura: Escherichia coli, 100.00UFC/mL, resistente a\nampicilina; sensível a ciprofloxacino, nitrofurantoína, cefalexina, ceftriaxona,\n\nsulfametoxazol-trimetoprim e amoxicilina-clavulanato. Em 14/04/2019: Hb 13,5g/dL; LG\n11.800/mm³; NS 6.570/mm³; Linf 2.890/mm³;\nEos 1.550/mm³; Plp´160.000/mm³, Crat 2,5mg/dL;\nUreia 32mg/dL; K+ 5,2mEq/L. Considerando o diagnóstico mais provável, a conduta imediata MAIS\nADEQUADA é:","options":{"A":"Manter o ciprofloxacino e adicionar a hidrocortisona.","B":"Substituir o ciprofloxacino por ceftriaxona e adicionar a hidrocortisona.","C":"Substituir o ciprofloxacino por nitrofurantoína.","D":"Substituir o ciprofloxacino por sulfametoxazol-trimetoprim."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-149934","number":"149934","sourceNumber":"149934","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 76 anos procurou o Pronto Socorro com queixa de urina mais escura,\ncansaço, náuseas e alguns episódios de vômitos.\nApresentou nos dias precedentes, influenza e\ndesde então, vem queixando-se de dor muscular difusa e fraqueza. Ao exame clínico ele se\nmostrava um pouco agitado, taquipneico, com pressão arterial de 130/90mmHg (decúbito e\nortostalismo) e frequência cardíaca de 92bpm. As extremidades estavam bem perfundidas e havia\nraras crepitações teleinspiratórias em ambas as bases pulmonares. A palpação dos músculos era\nmuito dolorosa. Há alguns anos, vem fazendo uso esporádico de ibuprofeno devido a dores\narticulares. Os exames complementares realizados no soro revelaram: uréoa 50mg/dL, creatinina\n6,1mg/dL, K+ 6,0mEq/L, ácido úrico 18mg/dL (valor normal até 6,0mg/dL), cálcio total 6,5mg/dL\n(valor normal entre 8,9-10,1mg/dL) PO4 7,5mg/dL (valor normal entre 2,5 a 4,5mg/dL), albumina\n4,0g/DL. Urina: fita reagente mostrando positividade para sangue (+++/4) e proteína (+/4);\nsedimentoscopia com 2 leucócitos e um eritrócito por campo. Dentre as opções abaixo, assinale o\ndiagnóstico MAIS PROVÁVEL:","options":{"A":"A insuficiência renal aguda induzida pelo antiinflamatório","B":"Insufuciência renal aguda secundária a obstrução por tumor de bexiga","C":"Insuficiência renal aguda causada por rabdomiólise","D":"Insuficiência renal pré-renal"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22841","number":"22841","sourceNumber":"22841","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Aproximadamente 3 dias após esforço inusitado, homem diabético, de 56 anos, buscou\nassistência médica queixando-se de fortes dores musculares no dorso e nos membros inferiores\nque praticamente o impediam de deambular sem ajuda e que não cederam após uso de\n\nanti-inflamatórios não hormonais. Nas últimas horas, passou a apresentar também urina mais\nescura, dispneia, náuseas e alguns episódios de\nvômitos. Ao exame clínico, o paciente mostrava-se\num pouco agitado, taquipneico, tinha os dados vitais dentro dos valores normais, perfundia bem as\nextremidades e apresentava crepitações teleinspiratórias no terço inferior de ambos os hemitórax. A\npalpação dos músculos do dorso e dos membros inferiores era muito dolorosa. Exames\nlaboratoriais: hemoglobina = 11,5 mg/dl, glicemia = 204 mg/dl, creatinina = 16 mg/dl, ureia = 180\nmg/dl, pH = 7,25, HCO3 = 12 mEq/L, Na+ = 128 mEq/L e K+ = 8,3 mEq/L. O plasma estava turvo e\navermelhado, mas, após centrifugação, mostrou-se amarelado pálido. O exame da urina, pela fita\nreagente, evidenciou presença de sangue (+++/4) e glicose (++/4) e a sedimentoscopia mostrou\nraros leucócitos e eritrócitos. A fração de excreção de sódio foi de 5%. A intervenção imediata mais\napropriada é:","options":{"A":"Administração de NaHCO3, por via intravenosa, para correção da acidose metabólica.","B":"Diálise para correção da hipervolemia e da hiperpotassemia.","C":"Administração, por via intravenosa, de solução salina hipertônica para correção da hiponatremia.","D":"Administração rápida de volume e insulina regular contínua para controle da cetoacidose\ndiabética."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22924","number":"22924","sourceNumber":"22924","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, 56 kg, dá entrada em um pronto atendimento com\nqueixa de dor abdominal inicialmente epigástrica e que se localizou, algumas horas depois, na\nfossa ilíaca direita. Queixa anorexia, náuseas e teve um episódio de febre (37,8°C). Relata que está\ngrávida, encontrando-se na 17ª semana de gestação. Ao exame físico, observa-se dor intensa à\npalpação superficial do ponto de McBurney. Hemograma demonstra anemia discreta e leucocitose\nde 14.000 mm³ sem desvio para a esquerda. Exame de urina evidencia a presença de 8 piócitos\npor campo, flora moderada, sem outras alterações. Em relação a esse caso clínico é CORRETO\nafirmar:","options":{"A":"A paciente deve ser internada e ter sua infecção do trato urinário tratada com antimicrobiano\nendovenoso, em decorrência do grande risco de sepse materna e abortamento nesses casos\n\n.","B":"Os aminoglicosídeos não deveriam ser empregados por seu potencial ototóxico e nefrotóxico,\nembora esses efeitos colaterais não sejam\nassim tão frequentes.","C":"Nessa fase de gestação, as alterações hematológicas citadas não deveriam ser mais\nconsideradas fisiológicas, como ocorre no primeiro trimestre de gestação.","D":"A profilaxia de trombose venosa profunda com heparina subcutânea representaria um risco\ndesnecessário para a saúde fetal."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-372274","number":"372274","sourceNumber":"372274","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Para a realização de exames com necessidade de uso de contraste, a avaliação da\nfunção renal do paciente deve ser analisada\nanteriormente. Como prevenção de Nefropatia\ninduzida por contraste em pacientes com alteração de função renal, as medidas abaixo podem ser\nindicadas, EXCETO:","options":{"A":"Hidratação venosa com soro fisiológico isotônico antes e após o exame;","B":"Solução de bicarbonato de sódio;","C":"Utilizar agente não iônico com a menor osmolaridade possível;","D":"Hemofiltração venosa contínua durante a realização do exame;","E":"Suspender diuréticos antes do procedimento caso o paciente utilize."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-239886","number":"239886","sourceNumber":"239886","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Relacione as acidoses tubulares renais com as suas características. COLUNA I ?\nAcidose tubular renal ? ATR; 1. ATR 1; 2. ATR\n2; 3. ATR 3; 4. ATR 4; COLUNA II ? Característica; (\n\n) Distúrbio misto com componente proximal e distal. ( ) Diminuição da reabsorção distal de Na+; ( )\nDefeito na reabsorção proximal tubular de bicarbonato. ( ) hipoaldosternonismo; Assinale a\nalternativa que apresenta a sequência CORRETA.","options":{"A":"4 2 1 3.","B":"4 1 2 3.","C":"3 1 2 4.","D":"2 1 4 3."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-179217","number":"179217","sourceNumber":"179217","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente vítima de trauma ocorrido há 5 horas, com esmagamento de membros\ninferiores e suspeita de rabdomiólise. São\ncondutas adequadas no manejo desse caso, EXCETO:","options":{"A":"Solicitar dosagem sérica de mioglobina, uma vez que, esse é o método mais sensível para\nconfirmar\n\no diagnóstico.","B":"Solicitar dosagem de potássio, uma vez que, hipercalemia é comum e pode necessitar de\ntratamento.","C":"Iniciar hidratação vigorosa, em caso de confirmação do diagnóstico de rabdomiólise.","D":"Acompanhar a função renal, em caso de confirmação do diagnóstico de rabdomiólise."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106014","number":"106014","sourceNumber":"106014","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, 28 anos, em pós-operatório de gastroplastia redutora em y de Roux,\ncomplicou com fístula gástrica e choque\nséptico de foco abdominal. Após laparotomia exploradora e\ncorreção da fístula, foi encaminhada ao CTI. Iniciado antibiótico e mantida ventilação mecânica\ninvasiva. Após 24 horas, apresentou piora da creatinina e oligúria não responsiva às medidas\nclínicas. Laboratório: HB = 10; leucócitos = 23.000; creatinina = 2,8 mg/dl; ureia = 95 mg/dl; K =\n6,8\nmEq/L; HCO3 = 12. Sobre IRA intrínseca, marque a CORRETA:","options":{"A":"É comum encontrar na IRA intrínseca: fração de excreção de sódio < 1% e concentração de\nsódio urinário alto.","B":"A Necrose Tubular Aguda (NTA) evoluiu sempre para doença renal dialítica.","C":"Não existe relação entre sepse e o desenvolvimento de NTA.","D":"Nesse caso o diagnóstico provável é NTA, sendo indicada diálise."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-60808","number":"60808","sourceNumber":"60808","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Marque a alternativa CORRETA. Pacientes com crise convulsiva, ou com imobilização,\nachado de hemoglobinúria (++++) sem\nmicro-hematúria, sugere o diagnóstico de:","options":{"A":"Rabdomiólise.","B":"Hemólise.","C":"Mieloma múltiplo.","D":"Lise tumoral."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-181885","number":"181885","sourceNumber":"181885","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 29 anos, com diagnóstico recente de diabetes mellitus não\ninsulinodependente, refere febre e artralgias há\n3 dias. O EAS demonstra cilindros leucocitários,\nleucocitúria com predomínio de eosinófilos, proteinúria e hematúria. O diagnóstico mais provável é:","options":{"A":"Pielonefrite.","B":"Necrose tubular aguda tóxica.","C":"Nefrite intersticial aguda.","D":"Glomerulonefrite.","E":"Lúpus eritematoso sistêmico."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-159860","number":"159860","sourceNumber":"159860","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 60 anos com histórico de diabetes tipo 2 há 15 anos, em uso de\ngliclazida 30 mg 2x/dia e metformina 1 g\n2x/dia. Durante consulta de rotina é diagnosticado\nhipertensão arterial; os valores de ureia e creatinina são normais; sua hemoglobina glicada = 7,0%;\no exame de urina de rotina normal, e a microalbuminúria é de 24 mg nas 24 horas. Foi medicado\ncom enalapril 20 mg/dia. No seu retorno, após 30 dias, houve um aumento significativo nos níveis\nde ureia e creatinina, no exame de urina de rotina presença de glicosúria ++, sem hematúria e\nleucocitúria. A causa mais provável, nesse caso, é:","options":{"A":"Nefrite intersticial aguda.","B":"Nefropatia diabética.","C":"Insuficiência renal pré-renal.","D":"Trombose da veia renal.","E":"Estenose da artéria renal."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-369440","number":"369440","sourceNumber":"369440","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Condições que determinam alterações na homeostase de sódio e água podem\ndeterminar grande mortalidade em pacientes\nhospitalizados. Sobre esta condição, analise as\nafirmativas abaixo. I. O controle do balanço hídrico, embora possa ser realizado em pacientes\ncríticos, têm valor de avaliação limitado, pois não é possível estimar efetivamente o volume\nrecebido pelo paciente. Dessa forma, não se recomenda sua avaliação diária. II. Osmorreceptores\nestão localizados nos núcleos supraópticos e paraventriculares do hipotalamo. III. Síndromes de\nBartter ou Gitelman não costumam estar associado a distúrbios da reabsorção tubular de sódio. A\nalternativa que contém todas as afirmativas corretas é:","options":{"A":"I, II e III","B":"I e II","C":"I","D":"II","E":"III"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-343683","number":"343683","sourceNumber":"343683","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Dentre os casos abaixo, o tratamento com corticosteroides para nefrite intersticial\ncomprovada por biopsia que tem mais probabilidade de influenciar a recuperação renal a longo\nprazo, é:","options":{"A":"Mulher de 45 anos de idade em uso prolongado de carbonato de lítio.","B":"Homem de 36 anos de idade com sarcoidose.","C":"Homem de 60 anos de idade com nefropatia por analgésicos.","D":"Mulher de 52 anos com nefrite intersticial por chumbo.","E":"Homem de 30 anos com nefropatia mesoamericana."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-159957","number":"159957","sourceNumber":"159957","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 74 anos, com IMC de 27,8 kg/m2, é acompanhado na Unidade da Saúde\npara tratamento de hipertensão arterial com\nenalapril, 10 mg por dia. Estava bem controlado há\nanos, mas passou a apresentar PA = 160 x 90 mmHg repetidas vezes. O médico solicitou\nacompanhamento com nutricionista e atenção do agente de saúde. No período de 60 dias, perdeu\n2 quilos e houve necessidade de aumento progressivo da medicação. Está tomando enalapril 20\nmg, hidroclorotiazida 25 mg e atenolol 50 mg, com pulso de 54 bpm e PA = 170 x 90 mmHg. A\navaliação laboratorial de rotina é normal. Nesse caso, o médico deve:","options":{"A":"dosar catecolaminas e metanefrinas urinárias.","B":"dosar atividade de renina plasmática.","C":"manter a mesma orientação, a menos que a pressão sistólica atinja 180 mmHg ou a diastólica\n100 mmHg.","D":"solicitar Doppler de artérias renais.","E":"aumentar a dose de atenolol."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-159929","number":"159929","sourceNumber":"159929","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente agricultor, morador da Zona Rural de Santarém deu entrada no Hospital\nMunicipal informando acidente ofídico em membro\ninferior direito acontecido há 8h e evoluindo com\nimportante dor e edema local. Apresenta elevação de Creatinofosfoquinase (CPK) com aumento de\npotássio (K) sérico e alterações eletrocardiográficas. Clinicamente apresenta dispneia e oligúria.\n\nNeste caso, a causa provável da oligúria e do distúrbio eletrolítico é:","options":{"A":"Alcalose metabólica.","B":"Lesão muscular com rabdomiólise.","C":"Lesão direta glomerular do veneno.","D":"Nefrite intersticial aguda.","E":"Alteração vascular."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-134475","number":"134475","sourceNumber":"134475","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Constitui alteração comum ao uso de diuréticos de alça:","options":{"A":"Hipercalcemia.","B":"Hiperaldosteronismo secundário.","C":"Hirsutismo.","D":"Acidose metabólica.","E":"Hipercalemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-134644","number":"134644","sourceNumber":"134644","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre a Síndrome de Lise Tumoral, marque a alternativa INCORRETA:","options":{"A":"Hiperuricemia","B":"Hipofosfatemia","C":"Hipocalcemia","D":"Hipercalemia","E":"Aumento de ureia e creatinina"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-86504","number":"86504","sourceNumber":"86504","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Considere a situação hipotética para responder a questão. Um homem de 68 anos de\nidade foi admitido para ressecção eletiva de um aneurisma de aorta abdominal infrarrenal. Tinha\ncomo antecedentes patológicos: hipertensão arterial sistêmica, miocardiopatia hipertensiva e\nhiperplasia prostática benigna. Na rotina laboratorial pré-operatória, apresentava ureia sérica de\n20\nmg/dl; creatinina sérica de 1,4 mg/dl e urinálise normal. A cirurgia foi complicada por períodos\nintermitentes de hipotensão, que foram revertidos com administração de sangue e soro fisiológico\n0,9%. No pós-operatório inicial, o paciente evoluiu com redução do débito urinário (0,3 ml/kg/h em\n12h). Solicitados exames para investigação, que mostraram os seguintes resultados: ureia sérica =\n33 mg/dl; creatinina sérica de 2,8 mg/dl; Na+ urinário = 61 mEq/L; osmolaridade urinária = 280\nmOsmol/kg H2O; densidade urinária = 1,010 e excreção fracional de sódio 3,4%. O exame do\nsedimento urinário revelou a presença de vários cilindros granulares pardos, proteinúria discreta,\npoucos leucócitos e ausência de hemácias. Sobre o caso descrito acima, a principal hipótese\ndiagnóstica para a insuficiência renal aguda do paciente é:","options":{"A":"Insuficiência renal pré-renal por hipovolemia.","B":"Insuficiência renal pré-renal por insuficiência cardíaca.","C":"Insuficiência renal pós-renal por uropatia obstrutiva.","D":"Necrose Tubular Aguda (NTA) isquêmica.","E":"Glomerulonefrite rapidamente progressiva."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-70807","number":"70807","sourceNumber":"70807","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente hipertenso com sopro abdominal apresenta angiotomografia mostrando\nestenose da artéria renal direita. Das\nmedicações abaixo, está contraindicada para o tratamento da\nhipertensão arterial nesse paciente:","options":{"A":"Alfametildopa.","B":"Betabloqueadores.","C":"Inibidores da enzima conversora de angiotensina.","D":"Bloqueadores dos canais de cálcio."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-68507","number":"68507","sourceNumber":"68507","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 64 anos vem à consulta e queixa-se de que no último ano passou a sentir\nmais sede e a notar um aumento do débito\nurinário, com noctúria de duas ou três vezes. Nega\nurgência miccional, disúria ou perda ponderal. Usa carbonato de lítio há 20 anos e valproato de\nsódio há 10 anos devido à doença bipolar, atualmente controlada. Seu irmão é portador de anemia\nfalciforme. Negava outros antecedentes. O exame clínico é normal, exceto por uma pressão\narterial de 148 x 88 mmHg. O laboratório evidenciou: glicemia = 133 mg/dl, sódio = 146 mg/dl,\npotássio = 3,6 mg/dl, bicarbonato = 26 mEq/L, ureia = 34 mg/dl, creatinina = 2,1 mg/dl, urina EAS\ncom pH = 7,0, densidade = 1002 e traços de proteinúria. Proteinúria de 15 mg/24h. Neste caso, o\ndiagnóstico mais provável é:","options":{"A":"Nefropatia diabética.","B":"Nefropatia induzida por lítio.","C":"Uropatia obstrutiva.","D":"Nefropatia por células falcêmicas.","E":"Nefropatia hipertensiva."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-64232","number":"64232","sourceNumber":"64232","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um quadro de febre, rash cutâneo, eosinofilia e insuficiência renal aguda é compatível\ncom:","options":{"A":"Necrose tubular aguda.","B":"Glomerulonefrite aguda.","C":"Acidose tubular renal.","D":"Nefrite intersticial.","E":"Trombose de artéria renal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-185342","number":"185342","sourceNumber":"185342","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em pacientes com estenose unilateral significativa de artéria renal, com hipertensão\nrenovascular, além da própria hipertensão arterial, espera-se:","options":{"A":"Hipocalemia, alcalose metabólica e função renal preservada.","B":"Hipercalemia, alcalose metabólica e função renal preservada.","C":"Hipocalemia, acidose metabólica e função renal comprometida.","D":"Hipercalemia, acidose metabólica e função renal comprometida.","E":"Hipocalemia, alcalose metabólica e função renal comprometida."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-352681","number":"352681","sourceNumber":"352681","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 48 anos de idade é internado na unidade de terapia intensiva com sepse\nassociada a pneumonia pneumocócica. O paciente necessita de ventilação mecânica e\nnorepinefrina para manter a pressão arterial média > 60 mmHg. Os exames hemodinâmicos\ninvasivos revelam pressões de enchimento do coração esquerdo adequadas, e, aparentemente, ele\nnão sabia ter disfunção ventricular esquerda. No terceiro dia de internação, o débito urinário cai,\no\nnível de creatinina aumenta para 3,5 mg/dl. O diagnóstico é de lesão tubular aguda. Qual dos\nseguintes agentes demonstrou melhorar os desfechos associados à lesão tubular aguda?","options":{"A":"Furosemida.","B":"Bosentana.","C":"Dopamina em baixa dose.","D":"Fator de crescimento semelhante a insulina.","E":"Nenhum dos agentes anteriores."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-257200","number":"257200","sourceNumber":"257200","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Você está de plantão na UPA e recebe um adulto jovem previamente hígido que foi\npicado por uma cascavel há alguns dias, mas\nnão procurou assistência médica. As queixas são de\ndispneia há 24 horas que piora quando deita, que não urina há pelo menos 1 dia e meio e que nas\núltimas 3 horas passou a vomitar com sangue e a ter sangramento nasal. Ao exame, apresenta:\ndispneia importante, frequência respiratória de 30 irpm, epistaxe, estertores crepitantes em bases\npulmonares, PA = 160x100mmHg e edema de membros inferiores. Os exames colhidos à admissão\nmostram: hemograma normal, ureia = 250mg/dL, creatinina = 5,0mg/dL, sódio plasmático =\n132mEq/L, potássio plasmático = 5,2mEq/L. Após as medidas iniciais de monitorização, oxigênio e\nuso de diuréticos, qual seria a melhor conduta?","options":{"A":"Iniciar solução de insulina com glicose até normalização do potássio.","B":"Indicar diálise de urgência.","C":"Iniciar anti-hipertensivo por via endovenosa.","D":"Iniciar expansão volêmica até que o paciente apresente diurese.","E":"Iniciar reposição de fatores de coagulação."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-161833","number":"161833","sourceNumber":"161833","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente idoso admitido na UTI com quadro de insuficiência cardíaca e elevação de\nenzimas discreta, sem alteração eletrocardiográfica, será submetido a cateterismo cardíaco.\n\nConsiderando que o mesmo apresenta disfunção renal crônica não dialítica, para prevenção de\nnefropatia por contraste, a MELHOR opção é:","options":{"A":"Expansão com solução salina a 0,9% e utilizar contraste iso-osmolar ou iônico, associado a NAC\n\n-N-acetilcisteína.","B":"Expansão com solução de bicarbonato de sódio, utilizar contraste de baixa osmolaridade ou não\niônico.","C":"Realizar expansão volêmica com solução salina 0,9%, preferindo contraste de alta osmolaridade\ne ou iônico.","D":"Reforçar hidratação VO e utilizar contraste de baixa osmolaridade ou não iônico.","E":"Reforçar hidratação oral, e utilizar contraste iso-osmolar ou iônico."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-160656","number":"160656","sourceNumber":"160656","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A combinação de fosfatúria, glicosúria, acidose tubular renal, hipocalemia e\naminoacidúria é mais provavelmente vista na seguinte condição:","options":{"A":"Saturnismo.","B":"Diabetes melito tipo 2.","C":"Lúpus eritematoso sistêmico.","D":"Anemia falciforme.","E":"Glomerulonefrite membranoproliferativa."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-109097","number":"109097","sourceNumber":"109097","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O rim pode ser acometido por agressão mediada por medicamentos e diversas toxinas.\nEm relação a estes aspectos, assinale a\nalternativa INCORRETA:","options":{"A":"Aminoglicosídeos podem desencadear necrose tubular aguda, cursando com insuficiência renal\naguda que, por sua vez, cursa com hipocalemia.","B":"Beta-lactâmicos (penicilinas, cefalosporinas e carbapenêmicos) podem induzir insuficiência renal\naguda principalmente através de nefrite intersticial aguda, em função da infiltração de eosinófilos\nno\nparênquima renal.","C":"Anti-inflamatórios não hormonais podem induzir diminuição da taxa de filtração glomerular em\nfunção da diminuição na produção de prostaglandinas que dilatam a arteríola aferente.","D":"Contrastes radiológicos contendo iodo podem induzir intensa vasoconstrição arteriolar renal,\nprovocando necrose tubular aguda, que cursa com sódio urinário e fração excretória de sódio\nelevados.","E":"Um padrão de lesão renal associado ao uso crônico de analgésicos combinados (paracetamol +\naspirina) é a necrose de papila."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-85826","number":"85826","sourceNumber":"85826","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 18 anos, com quadro de faringoamigdalite eritêmato-pultácea exuberante há\ncerca de 02 dias, associada à febre,\nlinfadenopatia dolorosa cervical unilateral e decaimento do\nestado geral. Dois dias após ter iniciado o uso de amoxacilina, evoluiu com surgimento de\nexantema máculo-papular pruriginoso, de distribuição céfalo-caudal. O quadro evoluiu com oligúria\ne dor lombar bilateral. Laboratório evidenciou hemograma sem alterações, creatinina sérica de 2,8\ng/dl (a mesma era de 1,0 mg/dl há duas semanas) e sumário de urina evidenciando cilindros\nleucocitários e piúria. Sódio e potássio sérico normais. Em relação ao quadro, assinale a\nalternativa\ncorreta:","options":{"A":"O quadro dermatológico após o uso de amoxacilina sugere Mononucleose Infecciosa como a\netiologia do quadro febril do paciente. A Insuficiência Renal observada deve ser atribuída ao efeito\ndireto do vírus Epstein-Barr sobre o parênquima renal.","B":"O paciente tem quadro compatível com faringite diftérica, sendo a insuficiência renal aguda\nprovocada por necrose tubular aguda\n\nassociada ao uso da amoxacilina.","C":"A faringoamigdalite é de provável etiologia estreptocócica. A insuficiência renal está mais\nprovavelmente associada à Nefrite Intersticial Aguda induzida por reação de hipersensibilidade à\namoxacilina.","D":"A presença de oligúria descarta a lesão induzida pela amoxacilina, a qual caracteriza-se por\nnecrose tubular aguda tipicamente não oligúrica, com tendência à hipocalemia.","E":"O quadro é sugestivo de Glomerulonefrite Rapidamente Progressiva complicando um paciente\nportador de Mononucleose Infecciosa. A biopsia renal está indicada."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-295727","number":"295727","sourceNumber":"295727","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"José Batista, 68 anos, DM e HAS de longa data, tabagista ativo, teve recente\ndiagnóstico de angina mesentérica em\nangiorressonância magnética mesentérica, investigando dor\nabdominal pós-prandial. Submetido à arteriografia, seguida de angioplastia de ramo mesentérico\ncom estenose crítica, evoluiu nos dias subsequentes com piora da função renal. Creatinina no\nprimeiro dia pós-procedimento 0,9, no segundo dia 1,2, quarto dia 3,7, sexto dia 6 mg/dl e anúria.\n\nQual a provável causa da disfunção renal aguda neste caso?","options":{"A":"Embolia por colesterol.","B":"Trombose de artéria renal.","C":"Nefropatia tardia do gadolínio.","D":"Nefropatia diabética acelerada.","E":"Nefropatia induzida pelo contraste da arteriografia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-313005","number":"313005","sourceNumber":"313005","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Considere um paciente em uso crônico de furosemida. Escolha a melhor alternativa\nsobre mecanismo de ação e de efeitos colaterais:","options":{"A":"A ação da furosemida é dada pela inibição da bomba de Na? / K? na alça ascendente de Henle,\na hiponatremia pela perda de sódio é efeito\ncolateral comum.","B":"A ação é na bomba de Na? /H? no túbulo proximal e a alcalose metabólica por perda de H? é\ncomplicação comum.","C":"A ação é na bomba de Na? / K? / 2 Cl?? na alça ascendente de Henle, a hiponatremia pela\nperda de sódio é efeito colateral comum.","D":"A ação é na bomba de Na? / K? / 2 Cl?? na alça ascendente de Henle, a troca de Na? por K? e\nH? no néfron distal levam a hipocalemia e\nalcalose metabólica como efeitos colaterais esperados.","E":"A ação da furosemida é dada pela inibição da bomba de Na? / K? na alça ascendente e a\nhipercalemia acontece por redução na excreção de potássio."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-27973","number":"27973","sourceNumber":"27973","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com respeito à nefrite intersticial aguda, identifique a CORRETA.","options":{"A":"Os anti-inflamatórios não esteroides desencadeiam nefrite intersticial crônica, mas não a nefrite\nintersticial aguda.","B":"A doença é comum, sendo responsável por cerca de metade dos casos de hematúria e\nproteinúria associada.","C":"A nefrite intersticial por drogas se estabelece dias a semanas após o início de tratamento.","D":"São comuns níveis de proteinúria maciça (acima de 3 g/24h), embora possam ocorrer casos que\nproteinúria discreta.","E":"O tratamento com altas doses de imunossupressores, por tempo prolongado, normalmente não\naumenta o risco de infecções sérias ou mortais."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-320904","number":"320904","sourceNumber":"320904","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre os diuréticos, seus mecanismos e efeitos colaterais, assinale a alternativa\ncorreta.","options":{"A":"A síndrome de Bartter é uma tubulopatia hereditária que simula uma intoxicação por furosemida.","B":"Hidroclorotiazida, indapamida e clortalidona possuem efeito tiazídico sobre o túbulo distal,\ninibindo a reabsorção sódio-cloro local.\nPela natriurese, geram hipercalciúria compensatória, o que\npode potencializar a formação de cálculos urinários de cálcio.","C":"A espironolactona atua no túbulo distal como antagonista da aldosterona. Tem como principal\nefeito colateral a alcalose metabólica\nhipercalêmica.","D":"A acetazolamida é um agonista da anidrase carbônica, gerando natriurese em troca de\nreabsorção de bicarbonato. É bem indicada em\npacientes hipervolêmicos em acidose metabólica.","E":"A furosemida e bumetanida são diuréticos de alça que inibem a reabsorção sódio-potássio-cloro\nna alça ascendente de Henle. Como efeitos\ncolaterais, têm-se hipocalemia, hipercalcemia,\nhipernatremia e acidose metabólica hiperclorêmica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-280277","number":"280277","sourceNumber":"280277","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre a rabdomiólise, é INCORRETO afirmar:","options":{"A":"a rabdomiólise pode ser ocorrer também após estado pós-ictal, traumas, síndrome\ncompartimental e após exercício extenuante.","B":"a hidratação precoce e vigorosa é uma das medidas essenciais na prevenção de lesão renal e\ndeve ser feita até a obtenção de fluxo\nurinário adequado, considerado como 200 a 300 mL/hora.","C":"a hiperuricemia pode ocorrer em alguns casos, podendo ser um fator de risco para a ocorrência\nde disfunção renal.","D":"a coloração escura da urina se deve à presença de hematúria."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-283997","number":"283997","sourceNumber":"283997","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma mulher de 75 anos com história de DM2, HAS, Osteoartrite, DPOC e tabagismo 30\nmaços/ano dá entrada no Pronto Socorro com história de dispneia e tosse há 1 mês. Tem\nantecedente de uso de diclofenaco e corticoides há cerca de 1 mês. O exame físico e radiológico\neram compatíveis com DPOC. Achado de exame: massa no pulmão esquerdo. Foi solicitada a\ninternação e inicialmente requisitado uma Tomografia de Tórax com contraste que confirmou a\nmassa periférica justa-pleural com linfadenopatia mediastinal à esquerda. No segundo dia de\ninternação, o débito urinário caiu para 800 mL em 24 horas e a creatinina subiu de 1,4 mg/dL para\n2,9mg/dL. Qual das opções abaixo seria a que explica a falência renal deste paciente?","options":{"A":"Necrose tubular aguda induzida por AINEs.","B":"Glomerulonefrite autoimune.","C":"Nefropatia induzida por contraste.","D":"Sindrome paraneoplásica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-266189","number":"266189","sourceNumber":"266189","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher, 74 anos, está sendo submetida a tratamento para pneumonia. Na evolução,\nobserva-se lesões eritemato-descamativas de pele. Os exames revelam: elevação dos níveis\nséricos de uréia e creatinina, urina tipo 1 com proteinúria (1,3 g/l), hematúria (50.000/mm3) e\nleucocitúria (superior a 1.000.000/mm3). Urocultura negativa. O diagnóstico mais provável é:\n(Dennis L. Kasper, Stephen L. Hauser, J. Larry Jameson . Medicina Interna de Harrison, parte 9\n\n-20.Ed? 2020.)","options":{"A":"Necrose tubular aguda","B":"Glomerulonefrite aguda","C":"Peilonefrite aguda","D":"Nefrite túbulo-intersticial aguda por droga","E":"Síndrome hemolítico-urêmica"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-253828","number":"253828","sourceNumber":"253828","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente jovem internado por abstinência de substâncias psicoativas, incluindo álcool,\nevolui com crises convulsivas. Após o manejo do quadro epilético com anticonvulsivantes\nendovenosos, em exames de controle nota-se um aumento progressivo de creatinina e urina de\ncoloração escura. Assinale a alternativa incorreta sobre o caso:","options":{"A":"A rabdomiólise apos crise convulsiva é o diagnóstico mais provável no quadro proposto, a\ncomplicação mais grave é a insuficiência renal aguda e a repleção volêmica precoce é a medidas\npreventiva mais adequada.","B":"A rabdomiólise apos crise convulsiva é o diagnóstico mais provável no quadro proposto, a\ncomplicação mais grave é a insuficiência renal aguda e o uso de furosemida nas primeiras 6 horas\nreduz o risco de lesão renal aguda por reduzir a mioglobinúria","C":"Além da rabdomiólise, a Nefrite Tubulo Intersticial pelo anticonvulsivante é um diagnóstico\ndiferencial relevante.","D":"O diagnóstico de rabdomiólise pode ser avaliado com dosagem de creatinofosfoquinase (CPK).\n\nA dosagem de mioglobina serica e urinária também podem ser realizadas. O Parcial de urina pode\nser positivo para bilirrubina e hemoglobina.","E":"Entre as medidas clínicas suportivas estão a correção de doses de medicamentos e suspensão\nde drogas nefrotóxicas"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-217099","number":"217099","sourceNumber":"217099","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em atendimento hospitalar a um paciente jovem, após quadro de crises convulsivas\ntônico-clônicas generalizadas, você nota aumento progressivo da creatinina. Escolha a opção\ncorreta.","options":{"A":"A insuficiência renal aguda é a complicação mais grave da rabdomiólise e deve ser manejada\ncom doses altas de diurético para manejo da\nhipercalemia.","B":"Na rabdomiólise o atraso da repleção volêmica por mais de 6 horas aumenta o risco de lesão\nrenal aguda.","C":"Retenção urinária por bexiga neurogênica ou medicamentos são a principal suspeita\ndiagnóstica.","D":"Hipocalemia é complicação comum da situação proposta e reposição precoce de cloreto de\npotássio é mandatória."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-199406","number":"199406","sourceNumber":"199406","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A melhor estratégia para redução do risco de injúria renal aguda associada a contraste\n(nefropatia induzida por contraste) em pacientes submetidos à angiografia é:","options":{"A":"Furosemida antes da aplicação de contraste.","B":"Manitol antes da aplicação de contraste.","C":"Solução salina 0,9% antes e após a aplicação de contraste.","D":"Acetilcisteína antes e após a aplicação do contraste.","E":"Bicarbonato de sódio antes da aplicação do contraste."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-205749","number":"205749","sourceNumber":"205749","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Causa provável de insuficiência renal aguda em paciente com uso de amicacina é:","options":{"A":"Necrose tubular aguda.","B":"Nefrite intersticial alérgica.","C":"Glomerulonefrite aguda.","D":"Obstrução renovascular.","E":"Síndrome de hiperviscosidade."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-153698","number":"153698","sourceNumber":"153698","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente pediátrico fazendo quimioterapia com ifosfamida começa a apresentar poliúria,\nacidose metabólica, fita urinária com densidade: 1005; pH: 5,0; proteína: ++; hemácias: negativo,\ncetona: negativo; glicose: ++; leucócitos: negativo. O diagnóstico mais provável é:","options":{"A":"Diabetes mellitus.","B":"Hiperidratação feita com soro glicosado.","C":"Acidose tubular renal proximal com síndrome de FANCONI.","D":"Injúria renal aguda.","E":"Síndrome da secreção inapropriada do hormônio antidiurético."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-154863","number":"154863","sourceNumber":"154863","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Não há pesquisas que comprovem, mas a revolução que o hábito de correr está\nprovocando no comportamento humano é, no\nmínimo, intrigante. Os exageros podem acontecer\ncom os menos avisados e sem orientação profissional. BRBA, corredor de 35 anos, após correr 30\nkm durante o verão, caiu na pista e apresentou-se desorientado. Na emergência hospitalar, foi\nverificado temperatura de 38,8ºC; passaram uma sonda de Foley e foi observada urina vermelha\ncom sangue 3+++ e sem células na microscopia. Qual das seguintes é a explicação mais provável\npara essa urina? (PEREIRA AB. Estudo laboratorial das proteinúerias. Em: LOPES AC. Tópicos em\nclínica médica. Editora Medsi. 2003. GRIGS RC. Doenças musculares. Em: ANDREOLI TE. Cecil ?\nmedicina interna básica. Editora Elsiever. 2005)","options":{"A":"Nefropatia subjacente.","B":"Azotemia pré-renal.","C":"Mioglobinúria.","D":"Glomerulonefrite.","E":"Cistite por bactéria Gram-negativa."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-126693","number":"126693","sourceNumber":"126693","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Considerando os efeitos específicos dos diuréticos, relacione a coluna da esquerda\ncom a da direita. (I) Furosemida. (II)\nClortalidona. (III) Manitol. (IV) Amilorida. (V) Acetazolamida. (A)\nHiponatremia isotônica. (B) Hipercalciúria. (C) Hipercalemia. (D) Acidose metabólica. (E)\nHiponatremia hipertônica. Assinale a alternativa que contém a associação CORRETA:","options":{"A":"I-A; II-B; III-D; IV-E; V-C.","B":"I-B; II-A; III-E; IV-C; V-D.","C":"I-B; II-E; III-C; IV-A; V-D.","D":"I-D; II-A; III-C; IV-E; V-B.","E":"I-D; II-B; III-E; IV-C; V-A."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-141122","number":"141122","sourceNumber":"141122","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 52 anos foi internada por quadro de peritonite e septicemia, sendo\nsubmetida a laparotomia exploradora que\nevidenciou necrose e perfuração de vesícula biliar.\nPreviamente, fazia uso praticamente contínuo de diclofenaco para tratamento de osteoartrite em\njoelhos por mais de 5 anos. No pós-operatório, foi tratada com ceftriaxona e gentamicina. Você foi\nchamado no quinto dia de pós-operatório, pois a paciente apresentava níveis de creatinina em\nelevação. Creatinina basal: 1,3; Creatinina atual: 2,8; Ureia atual:105. Ao exame físico, apresenta\nsinais de depleção do extracelular em 15%. Assinale a alternativa INCORRETA sobre o caso.","options":{"A":"É um quadro de insuficiência renal aguda de origem multifatorial: sepse, drogas nefrotóxicas e\ndepleção do extracelular. Não se pode descartar um componente crônico pelo uso de\n\nanti-inflamatório não hormonal.","B":"A dosagem de sódio urinário e a fração excretória de sódio na urina podem auxiliar no\ndiagnóstico diferencial da insuficiência renal aguda (pré-renal x necrose tubular aguda).","C":"O achado de eosinófilos e cilindros piocitários na urina descarta a participação do diclofenaco\nna\ngênese da insuficiência renal.","D":"Não há necessidade de indicar diálise no momento; deve ser avaliada a evolução diária do\npaciente, com repleção apropriada do intravascular e suspensão de drogas nefrotóxicas.","E":"O achado de cilindros granulosos na urina fortalece a hipótese de necrose tubular aguda."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106120","number":"106120","sourceNumber":"106120","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Corredor de maratona de 18 anos de idade está treinando durante uma tarde de verão\nintenso, sob sol das 13h00min, repentinamente, apresenta-se desorientado e cai na pista.\n\nTransferido para a unidade médica mais próxima, verificou-se que sua temperatura é de 38,8°C e\nentre outras medidas, foi colocada uma sonda de Foley e observou-se que macroscopicamente sua\nurina está avermelhada, com aspecto sanguinolento (+++), contudo, após a avaliação\nmicroscópica, concluiu-se que a urina não apresentava células. Entre as alternativas abaixo, qual a\nmais provável explicação para o caso acima?","options":{"A":"O paciente é portador de nefropatia subjacente.","B":"O paciente apresenta azotemia pré-renal.","C":"O paciente está cursando com mioglobinúria.","D":"O paciente está iniciando uma glomerulonefrite.","E":"Nenhuma das alternativas acima está correta."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-100845","number":"100845","sourceNumber":"100845","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Os Anti-Inflamatórios Não Esteroidais (AINEs) constituem uma das classes de\nmedicamentos mais comumente prescritas no mundo. Quanto aos seus efeitos nefrotóxicos, é\nCORRETO afirmar:","options":{"A":"O uso de AINE não é associado a distúrbios hidroeletrolíticos. Portanto, edema secundário ao\nseu uso deve ser acompanhado de eosinofilúria\npor nefrite intersticial aguda.","B":"O principal mecanismo de ação dos AINEs é a inibição das ciclo-oxigenases, induzindo assim a\nsíntese de prostaglandinas desencadeantes de seu efeito nefrotóxico.","C":"Indivíduos tratados com betabloqueadores ou\n\ndiuréticos são menos suscetíveis ao descontrole pressórico secundário ao uso de AINE.","D":"O uso crônico de acetaminofen, assim como de salicilatos, mesmo que em altas doses, pode\nsubstituir o uso de AINE para analgesia sem nenhum prejuízo renal.","E":"Os anti-inflamatórios seletivos afetam menos os indivíduos com função renal normal, e\nafetam de modo semelhante os pacientes com alterações renais prévias."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-101386","number":"101386","sourceNumber":"101386","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação à Nefropatia Induzida por Contraste (NIC), considere as afirmativas a\nseguir. I. Diabetes melito e doença renal\ncrônica são condições que elevam o risco de nefropatia\ncom necessidade de diálise. II. A maioria dos casos de nefropatia cursa com oligúria e acidose\nmetabólica de ânion gap normal. III. Concorrem para sua fisiopatologia a hiperosmolaridade e a\nvasodilatação renal exacerbada. IV. Suspensão de AINEs, uso de baixo volume de contraste e\nrepleção de volume intravascular são consideradas medidas nefroprotetoras. Assinale a alternativa\ncorreta.","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-77975","number":"77975","sourceNumber":"77975","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente alcoolista de 54 anos é encontrado inconsciente em sua casa. Levado ao\npronto-socorro, detecta-se creatinina sérica de 8,4 mg/dl (um mês atrás: 0,7 mg/dl), fita reagente\nurinária (dipstick) com pH de 5 e positiva para sangue, sedimento urinário com cilindros granulares\ne ausência de hemácias. O diagnóstico é de:","options":{"A":"Síndrome hepatorrenal.","B":"Injúria renal aguda pré-renal.","C":"Lesão tubular aguda secundária à sepse.","D":"Rabdomiólise.","E":"Nefropatia intersticial alérgica."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-82595","number":"82595","sourceNumber":"82595","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 61 anos de idade, antecedente de diabetes mellitus,\ndislipidemia e HAS, fazia uso de metformina,\nsinvastatina e iniciou recentemente uso de inibidor de\nECA. Iniciou anticoagulação com warfarina e clexane por causa de quadro de tromboembolismo\npulmonar agudo diagnosticado por angiotomografia de tórax. Após 2 dias de anticoagulação, os\ncontroles revelaram aumento de creatinina com valor de 2,5 mg/dl (o valor anterior era de 1,3\nmg/dl) e ureia de 71 mg/dl. Durante esse período, não apresentou diminuição de volume urinário\nnem hematúria. Qual seria a melhor hipótese e tratamento?","options":{"A":"Insuficiência renal aguda secundária ao uso de anticoagulante. Suspender a medicação\nimediatamente.","B":"Insuficiência renal aguda secundária ao uso de inibidor de ECA. Substituir a medicação por\nbloqueador de cálcio.","C":"Insuficiência renal crônica progressiva pelo diabetes melito. Iniciar dieta hipoproteica e\ndiurético.","D":"Insuficiência renal aguda por nefropatia do contraste. Iniciar hidratação EV e observar evolução\ne risco potencial de hemodiálise.","E":"Insuficiência renal aguda por embolização renal. Aumentar dose de anticoagulante."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-79481","number":"79481","sourceNumber":"79481","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 22 anos, interna na UTI, após acidente de trânsito, com\nesmagamento de ambas as pernas. Chega\nhipocorado (2+/4); pressão arterial: 80 x 50 mmHg;\ntaquicárdico (FC: 130 bpm); taquipneico (FR: 45 irpm). Instalado dois acessos venosos, iniciado\nreposição volêmica, instalado PVC (Pressão Venosa Central), sondagem vesical. O paciente, em\nseis horas, evoluiu com anúria, mesmo com a reposição volêmica de 1 litro de soro fisiológico 0,9%\npor hora. Melhora da pressão arterial: 120 x 70 mmHg. Os exames iniciais e de 06 (seis) horas de\nevolução foram os seguintes (VER IMAGEM). Considerando que o paciente evoluiu para anúria e\ninsuficiência renal aguda, quais as principais complicações metabólicas e qual conduta a ser\ntomada para reversão do caso:","options":{"A":"Alcalose metabólica, hiperpotassemia. Iniciar hemodiálise.","B":"Acidose metabólica, hiperpotassemia. Iniciar bicarbonato de sódio.","C":"Acidose metabólica, hiperpotassemia. Iniciar hemodiálise.","D":"Alcalose metabólica, hiperpotassemia. Iniciar furosemida.","E":"Acidose metabólica, hiperpotassemia. Iniciar furosemida."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81778","number":"81778","sourceNumber":"81778","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Criança com 3 anos de idade em acompanhamento por Síndrome de Bartter, traz\nresultado de renina sérica = 500 µUI/ml (valores de referência = 2,8 a 39,9 µUI/ml). Quais dos\nseguintes achados laboratoriais são compatíveis com essa síndrome?","options":{"A":"Baixa perda urinária de sódio.","B":"Hipercalemia.","C":"Hipocloremia.","D":"Hipoaldosteronismo.","E":"Acidose metabólica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81419","number":"81419","sourceNumber":"81419","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 58 anos, previamente normotenso, desenvolve hipertensão\narterial, acompanhado de alcalose metabólica,\nhipocalemia e progressão para insuficiência renal\ncom ultrassonografia renal mostrando desproporção no tamanho do rins. Assinale qual o\ndiagnóstico clínico e o exame necessário para sua confirmação:","options":{"A":"oclusão tromboembólica da artéria renal / arteriografia renal.","B":"estenose da artéria renal / cintilografia renal com teste do captopril.","C":"trombose da veia renal / venografia renal seletiva.","D":"nefroesclerose hipertensiva / fundo de olho.","E":"esclerodermia / biópsia renal."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81421","number":"81421","sourceNumber":"81421","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 34 anos, nos últimos 3 dias apresenta-se com febre, astenia e oligúria. Há\numa semana usou sulfa/trimetoprim para\ninfecção urinária baixa. O exame físico mostra: rash\neritematopapular na face, tórax e abdômen; PA: 140/105 mmHg, Temp.: 37,8 C (restante normal).\nExame complementar: VG: 38%, Hb: 11,7%, leucograma: 12000 leucócitos (63 segm/3 bastões/22\nlinfo/12 eosino/01 mono); ureia: 94 mg%, creatinina: 2.8 mg%, Na: 136, K: 5.2, Cl: 110 mEq/l; FAN\nnegativo, urina 12~15 piócitos por campo; incontáveis hemácias, cilindros granulosos e hemáticos;\nausência de bactérias, Clearance de creatinina: 30 ml/min, proteinúria: 1,2 g/24h. Esses dados são\nindicativos prováveis de:","options":{"A":"nefropatia por IgA","B":"púrpura anafilactoide","C":"pielonefrite aguda complicada","D":"nefrite intersticial aguda","E":"nefrite por lúpus induzido por droga"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-58599","number":"58599","sourceNumber":"58599","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 71 anos de idade é avaliado na UTI por quadro de insuficiência renal\naguda. O paciente havia sido operado há\nalguns dias para retirada de um tumor de cólon e estava\napresentando drenagem persistente em seu dreno abdominal e picos febris de até 39°C. Nos\núltimos nove dias, o paciente fez uso de gentamicina 100 mg EV de 8/8 horas e ceftriaxona 2 g EV\nem dose única diária. Nos últimos quatro dias, sua creatinina sérica atingiu valor de 6,5 mg/dl e\napresentou diurese de 40 ml/hora. Não há relato de nenhum episódio de hipotensão em momento\nalgum da internação. Ao exame físico, a PA é de 130/90 mmHg, FC de 82 bpm, FR de 18 irpm e\nTax. de 36,8ºC. Foi realizada ultrassonografia do aparelho urinário que não apresentou sinais de\nobstrução. A causa da insuficiência renal desse paciente é:","options":{"A":"Quadro de choque séptico.","B":"Traumatismo ureteral cirúrgico.","C":"Quadro de glomerulonefrite aguda.","D":"Nefrotoxicidade pela gentamicina.","E":"Insuficiência renal aguda pela ceftriaxona."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-71675","number":"71675","sourceNumber":"71675","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em um paciente de 18 anos de idade, com história de amigdalite recente, em uso de\nantibiótico e anti-inflamatório não hormonal, o achado de hipertensão arterial, aumento da\ncreatinina sérica, fração de excreção maior que 1%, rins de tamanho normal, hematúria com\nproteinúria moderada (menor que 1 g/dia) e cilindros leucocitários na urina, sugere o diagnóstico\nde:","options":{"A":"Glomerulopatia de lesões mínimas.","B":"Nefrite intersticial aguda.","C":"Ateroembolismo por êmbolos de colesterol.","D":"Crioglobulinemia mista."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-60727","number":"60727","sourceNumber":"60727","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 70 anos, diabético e hipertenso, apresenta quadro de 14 dias de\nevolução com febre, mialgia e cefaleia associada. H.M.P., há 21 dias foi submetido a procedimento\nvascular, porém não soube especificar qual tipo de tratamento. No exame físico, foi constatado\nlivedo reticular com gangrena de artelhos. Os exames investigativos evidenciaram CR (2,0 mg/dl) e\nhemograma com anemia leve, leucocitose e eosinofilúria. Assinale a alternativa INCORRETA:","options":{"A":"O diagnóstico definitivo será estabelecido por biópsia renal.","B":"O exame histológico mostraria fendas biconvexas em formato de agulha.","C":"A mortalidade atinge mais da metade destes pacientes.","D":"O tratamento deve ser iniciado o mais precocemente possível com anticoagulação plena.","E":"40% destes pacientes necessitarão de terapia renal substitutiva."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-63038","number":"63038","sourceNumber":"63038","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em qual das seguintes situações não se encontra densidade baixa no EAS?","options":{"A":"Uso de diuréticos.","B":"Diabetes mellitus.","C":"Hiper-hidratação.","D":"Diabetes insipidus.","E":"Todos os anteriores possuem densidade baixa no EAS."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-44034","number":"44034","sourceNumber":"44034","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente foi internado para investigação de dor abdominal crônica agudizada, com\ntomografia contrastada agendada após 3 dias. Trata-se de um paciente de 52 anos, sabidamente\ndiabético há 5 anos, em uso de metformina 850 mg 3x/dia, sem complicações em órgãos-alvo do\ndiabetes. Seus últimos exames de glicemia capilar pré-prandial foram: 250, 225, 192 e 200 mg/dl. A\nconduta médica correta é:","options":{"A":"Iniciar o jejum na véspera do exame, com soro fisiológico IV, mantendo sua prescrição habitual e\nevitando o soro glicosado para não elevar sua glicemia.","B":"Solicitar que o exame seja realizado sem a utilização de contraste iodado, visto que irá piorar a\nfunção renal e precipitar quadro de hipotiroidismo pela sobrecarga de iodo.","C":"Iniciar insulinoterapia intra-hospitalar conforme glicemias capilares e interromper o tratamento\ncom metformina dois dias antes do exame, mantendo o\npaciente hidratado.","D":"Iniciar insulinoterapia para corrigir hiperglicemias atuais e manter a mesma dose de metformina,\nadicionando soro fisiológico à prescrição.","E":"Manter a mesma prescrição do domicílio, considerando que o paciente não tem história de\ninsuficiência renal crônica nem apresenta alteração da diurese."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-43640","number":"43640","sourceNumber":"43640","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 68 anos de idade, portador de diabetes mellitus tipo 2, chega ao\npronto-socorro com dor torácica e é submetido a uma cineangiocoronariografia de emergência.\n\nVinte e quatro horas após o procedimento, a creatinina (que era de 1 mg/dl na admissão) sobe para\n1,8 mg/dl. Em relação ao caso clínico\ndescrito, assinale a alternativa CORRETA:","options":{"A":"A urina de 24 horas demonstra proteinúria acima de 3,0 g/dia.","B":"A fração excretora de sódio (FeNa) urinário é < 1%.","C":"Existe hematúria dismórfica e cilindros hemáticos detectados no parcial de urina.","D":"O achado de eosinofilia é indicativo de terapia com corticosteroides.","E":"Ocorre elevação da Desidrogenase Lática (LDH) e esquistócitos no sangue periférico."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34494","number":"34494","sourceNumber":"34494","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 79 anos foi submetido à aortografia. Dois dias depois, apresentou\nlivedo reticular e púrpura palpável em membros\ninferiores. Exames laboratoriais na ocasião\ndemonstraram aumento da creatinina sérica, eosinofilia e hipocomplementenemia. Trata-se de:","options":{"A":"Doença renal ateroembólica.","B":"Trombose de artéria renal.","C":"Trombose de veia renal.","D":"Síndrome hemolítica-urêmica.","E":"Vasculite leucocitoclástica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26095","number":"26095","sourceNumber":"26095","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre rabdomiólise, assinale a alternativa falsa.","options":{"A":"É definida por valores de CPK acima de 1.000 UI/L.","B":"Pode estar associada à síndrome neuroléptica maligna.","C":"Fraqueza muscular, mialgia e câimbras são as manifestações clínicas mais comuns.","D":"A insuficiência renal mioglobinúrica é uma complicação extramuscular frequente.","E":"Hidratação e alcalinização da urina fazem parte do tratamento da insuficiência renal associada."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22280","number":"22280","sourceNumber":"22280","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A maioria das complicações sistêmicas menores relacionadas ao uso dos contrastes\niodados durante angiografias ocorre devido à:","options":{"A":"osmolalidade.","B":"hiperviscosidade.","C":"lesão celular direta causada pelo iodo.","D":"ativação do sistema complemento causado pelo radical metil do anel benzênico.","E":"resposta inflamatória sistêmica desencadeada por lesão endotelial."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22718","number":"22718","sourceNumber":"22718","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 67 anos vem à consulta com uma angioressonância que demonstra\nestenose de artéria renal direita. Qual dos\ncritérios abaixo NÃO constitui indicação para\nrevascularização dessa artéria?","options":{"A":"Pressão arterial não controlada, mesmo com terapêutica anti-hipertensiva máxima.","B":"Aumento progressivo de creatinina sem outras causas aparentes.","C":"Diâmetro longitudinal do rim direito maior que 12 centímetros.","D":"Edema pulmonar recorrente ou insuficiência cardíaca congestiva.","E":"Hipercalemia grave ou aumento maior que 30% na creatinina com o uso de inibidores de enzima\nde conversão ou bloqueadores do receptor AT1 da\nangiotensina II."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22320","number":"22320","sourceNumber":"22320","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Anorexia, fraqueza, cólica abdominal, orla de Burton e anemia são alguns dos sintomas\ne sinais de intoxicação pelo:","options":{"A":"cádmio.","B":"arsênico.","C":"cromo.","D":"mercúrio.","E":"chumbo."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-313672","number":"313672","sourceNumber":"313672","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 74 anos, diabético de longa data, estava internado para tratamento de\npielonefrite. Apesar de a urocultura ter confirmado que a bactéria era sensível ao antibiótico em\nuso, ele permanecia com picos febris no quarto dia de tratamento, quando apresentou hematúria\nmacroscópica e passou a evoluir com disfunção renal, apesar de estável hemodinamicamente. Que\ncomplicação poderia justificar essa evolução desfavorável?","options":{"A":"Abscesso perinefrético.","B":"Necrose cortical bilateral.","C":"Necrose papilar renal.","D":"Pielonefrite enfisematosa.","E":"Abscesso renal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-242200","number":"242200","sourceNumber":"242200","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente foi trazido para a emergência após ter sido vítima do desabamento do\nedifício onde morava. Ficou retido nos\nescombros por oito horas, antes de ser resgatado pelos\nbombeiros. Queixava-se de dor abdominal, mas a tomografia foi normal. À admissão, foi\ndiagnosticada uma fratura no fêmur direito e várias escoriações pelo corpo. Como a urina era muito\nescura, foi solicitado um sumário de urina que demonstrou presença de sangue, mas com\nsedimentoscopia normal. Que exame, dos citados abaixo, seria mais útil para esclarecimento\ndiagnóstico quanto à alteração urinária?","options":{"A":"Gasometria arterial.","B":"Alanina aminotransferase.","C":"Bilirrubinas.","D":"Dosagem de porfirinas urinárias.","E":"Creatinofosfoquinase."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-87329","number":"87329","sourceNumber":"87329","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A sequela mais significativa da necrose de papila renal é:","options":{"A":"Falência renal.","B":"Abscesso.","C":"Obstrução.","D":"Formação de cálculos.","E":"Câncer."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-88545","number":"88545","sourceNumber":"88545","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual o índice diagnóstico urinário observado na insuficiência renal intrínseca?","options":{"A":"Excreção fracionada de sódio < 1%.","B":"Concentração urinária de sódio > 20 mmol/L.","C":"Razão entre creatinina urinária e plasmática > 40.","D":"Razão entre ureia urinária e plasmática > 8.","E":"Presença de cilindros hialinos no sedimento urinário."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-7728","number":"7728","sourceNumber":"7728","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São diuréticos poupadores de potássio:","options":{"A":"indapamida e clortalidona.","B":"acetazolamida e manitol.","C":"triantereno e amilorida.","D":"bumetamida e piretanida."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-7732","number":"7732","sourceNumber":"7732","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Para um paciente cujo esfregaço de sangue periférico apresente macrocitose e\nhipersegmentação de neutrófilos, qual das condições abaixo não deve ser considerada?","options":{"A":"Uso crônico de bloqueador de bomba protônica.","B":"História prévia de cirurgia bariátrica.","C":"Doença de Crohn.","D":"Intoxicação por chumbo."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-133714","number":"133714","sourceNumber":"133714","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Identifique a situação médica não correlacionada a um estado de hiperaldosteronismo\nsecundário:","options":{"A":"Estenose da artéria renal.","B":"Insuficiência cardíaca congestiva.","C":"Acidose tubular renal tipo IV.","D":"Síndrome nefrótica.","E":"Hipertensão maligna."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-133654","number":"133654","sourceNumber":"133654","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação às ações renais dos Inibidores da Enzima Conversora (IECA), é\nINCORRETO afirmar que:","options":{"A":"Inibem a formação da angiotensina I.","B":"Reduzem a proteinúria.","C":"Reduzem a caliurese.","D":"Atenuam a hiperplasia e fibrose.","E":"Reduzem a resistência vascular na arteríola eferente."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-82506","number":"82506","sourceNumber":"82506","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 32 anos, usuário de drogas e álcool, é encontrado inconsciente e levado\nà unidade de emergência. A glicemia estava\nnormal e a CT de crânio não mostrou alterações. A\ncreatinina sérica é de 10,5 mg/dl (estava 0,7 mg/dl no exame feito há 1 mês). O sedimento urinário\nrevelou numerosos cilindros granulares marrons, além de hemoglobina positiva (+++) na ausência\nde hemácias. O diagnóstico mais provável para esta situação médica é:","options":{"A":"Pielonefrite aguda.","B":"Nefrite intersticial alérgica.","C":"Necrose tubular aguda secundária à rabdomiólise.","D":"Ateroembolismo renal.","E":"Glomerulonefrite aguda."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-295010","number":"295010","sourceNumber":"295010","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Menina de 6 anos é levada para atendimento, pois há cinco dias apresenta fraqueza\nmuscular e cãibras em membros inferiores,\nevoluindo para incapacidade de deambular. Nega febre\nou diarreia. Ao exame físico, está pouco comunicativa, apresenta diminuição da força muscular e\ndos reflexos profundos em membros inferiores. Sensibilidade dolorosa e tátil normais. Restante do\nexame físico sem alterações. A bioquímica do sangue coletada mostrou: Na = 138 mEq/L; K = 2,0\nmEq/L; Cl = 120 mEq/L; HCO? = 10 mEq/L; ureia e creatinina normais. O EAS evidenciou Ph = 6,\ntraços de proteína, sem piúria ou hematúria. Para corroborar a principal hipótese diagnóstica desse\ncaso, deve-se complementar os exames com:","options":{"A":"Colonoscopia.","B":"Análise do liquor.","C":"Dosagem de potássio urinário.","D":"Ressonância de coluna vertebral."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-186240","number":"186240","sourceNumber":"186240","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Adolescente de 17 anos evolui com fraqueza muscular generalizada, fadiga, cãibras e\nespasmos musculares, além de poliúria. Seus exames laboratoriais mostram alcalose metabólica\ncom hipocloremia e hipocalciúria. O médico assistente considera o diagnóstico de síndrome de\nGitelman, já que, nos exames laboratoriais realizados, observa-se:","options":{"A":"Hematúria.","B":"Hipercalemia.","C":"Hipercalcemia.","D":"Hipomagnesemia."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-148817","number":"148817","sourceNumber":"148817","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 78 anos, fumante, com diabetes mellitus tipo 2 e hipertensão arterial\nsistêmica, foi internada em unidade de terapia\nintensiva apresentando dor torácica e hipertensão\narterial. Foi feita investigação diagnóstica, inclusive com cateterismo cardíaco e coronariografia.\nAlguns dias após, já na enfermaria, ela evoluiu com injúria renal aguda. Ao exame físico,\n\nobserva-se livedo reticularis e cianose fixa de dois de seus pododáctilos e, no fundo de olho, foram\nnotados êmbolos de aspecto amarelado em arteríolas retinianas (placas de Hollenhorst). O\nhemograma revelou eosinofilia. Nesse caso, a causa mais provável de deterioração da função renal\né:","options":{"A":"Nefrotoxicidade por contraste iodado.","B":"Nefrite intersticial aguda por droga.","C":"Necrose tubular aguda.","D":"Ateroembolismo."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-345102","number":"345102","sourceNumber":"345102","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, 68 anos, tabagista, hipertenso e diabético, apresenta vasculopatia\naterosclerótica em diversos vasos, submetido à\ncoronariografia, evoluiu com lesão renal aguda\n(lesão renal prévia normal) 7 dias após o procedimento. Os exames complementares mostraram\neosinofilia e eosinofilúria. Qual a provável etiologia do quadro?","options":{"A":"Doença ateroembólica.","B":"Nefropatia por contraste.","C":"Vasculite.","D":"Glomerulonefrite."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-325840","number":"325840","sourceNumber":"325840","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 59 anos, HIV há 25 anos em uso de lamivudina, raltegravir, etravirina,\ndarunavir, ritonavir e tenofovir. Nos últimos meses,\nrefere dores osteomioarticulares. Últimos\nexames laboratoriais: creatinina = 1,8 mg/dl, glicemia = 87 mg/dl com presença de glicosúria,\nfósforo sérico baixo e aumento da eliminação de fósforo e aminoácidos na urina. Presença de\nacidose metabólica na gasometria arterial. A principal suspeita diagnóstica é:","options":{"A":"Síndrome de Fanconi pelo uso de tenofovir.","B":"Acidose lática pelo uso da lamivudina.","C":"Reação de hipersensibilidade pelo uso de darunavir.","D":"Rabdomiólise pelo uso da etravirina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-310664","number":"310664","sourceNumber":"310664","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Rabdomiólise é uma condição caracterizada por dano muscular e que possui diversas\netiologias incluindo o uso de algumas medicações, suplemento dietético e intoxicações. Qual das\nopções abaixo NÃO está associada ao desenvolvimento de rabdomiólise?","options":{"A":"Cocaína.","B":"Creatina monohidratada.","C":"Cafeína.","D":"Estatina."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-316701","number":"316701","sourceNumber":"316701","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 45 anos, previamente hígido, compareceu ao ambulatório de clínica\nmédica para consulta de 1ª vez com artrite\nem pequenas articulações das mãos há 2 meses. Nesta\nocasião, foram solicitados exames laboratoriais e de imagem, bem como iniciado anti-inflamatório\nnão hormonal (ibuprofeno 1,8 g/dia). Retornou à consulta em 45 dias, tendo realizado os exames\nsolicitados na véspera da consulta. Ainda apresentava artrite, embora um pouco melhor, e\nnenhuma outra queixa. Baseado nos exames, recebeu diagnóstico de artrite reumatoide, mas\napresentava uma hematúria microscópica, o que não passou despercebido pelo médico. A melhor\nexplicação para esta hematúria seria:","options":{"A":"Nefrite intersticial associada ao uso de ibuprofeno.","B":"Amiloidose como complicação da artrite reumatoide.","C":"Glomerulonefrite membranosa associada à artrite reumatoide.","D":"Síndrome nefrítica, comum em pacientes com artrite reumatoide inicial."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-309019","number":"309019","sourceNumber":"309019","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em paciente do sexo feminino, 58 anos, com diagnóstico prévio de diabete melito tipo\n2, disfunção renal crônica leve estágio 2, apresentando hipercalemia e acidose metabólica\nhiperclorêmica, sem sintomatologia específica associada. A melhor hipótese diagnóstica é:","options":{"A":"Doença de Addison.","B":"Síndrome de Gitelman.","C":"Hipoaldosteronismo hiporreninêmico.","D":"Hiperaldosteronismo primário."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-300701","number":"300701","sourceNumber":"300701","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A prevenção da nefrotoxicidade pelos contrastes iodados passa por:","options":{"A":"Indicação criteriosa dos exames, preferência por contraste não iônico iso-osmolar, hidratação\nvigorosa e suspensão dos diuréticos quando possível.","B":"Indicação criteriosa dos exames, preferência por contraste não iônico de baixa osmolaridade,\nhidratação vigorosa e suspensão dos diuréticos sempre.","C":"Evitar exames com contraste iodado, hidratação vigorosa e suspensão dos diuréticos quando\npossível.","D":"Indicação criteriosa dos exames, preferência por contraste não iônico de baixa osmolaridade e\nhidratação otimizada logo após o uso do contraste.","E":"Indicação criteriosa do exame complementar impedindo apenas o uso do contraste."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-246939","number":"246939","sourceNumber":"246939","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 23 anos, com diagnóstico de linfoma de Burkitt com rápido crescimento de\nmassas retroperitoneais, iniciará quimioterapia.\nPrevendo uma complicação potencialmente grave,\nque incide nos primeiros dias da terapia, deve-se prescrever a partir do dia anterior à realização\ndo\nprocedimento:","options":{"A":"Hidratação e alopurinol.","B":"Antieméticos e opiáceos.","C":"Vancomicina e ceftazidima.","D":"Voriconazol e vancomicina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-154029","number":"154029","sourceNumber":"154029","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Necrose papilar, necrose isquêmica de papila renal e suas adjacências podem estar\nassociadas às seguintes condições, EXCETO:","options":{"A":"Pielonefrite.","B":"Diabetes mellitus.","C":"Uropatia obstrutiva.","D":"Nefrotoxicidade por aminoglicosídeo.","E":"Anemia de células falciformes."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-153350","number":"153350","sourceNumber":"153350","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 72 anos de idade, desenvolve insuficiência renal aguda\napós cateterismo cardíaco. O exame físico chama\natenção para diminuição dos pulsos periféricos,\nlivedo reticular, hipersensibilidade epigástrica e confusão mental. Os estudos laboratoriais incluem\n(mg/L) BUN de 131; creatinina de 5,2 e fosfato de 9,5. A urinálise demonstra valor de 10 a 15 para\nleucócitos, 5 a 10 para hemácias e 1 para cilindro hialino por campo de grande aumento (HPF). O\ndiagnóstico mais provável é:","options":{"A":"Nefrite intersticial aguda causada por drogas.","B":"Rabdomiólise com necrose tubular aguda.","C":"Necrose tubular secundária à exposição a radiocontraste.","D":"Embolização por colesterol.","E":"Dissecção arterial renal com azotemia pré-renal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-354254","number":"354254","sourceNumber":"354254","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Algumas doenças hereditárias monogênicas renais com variante genética patogênica já\ndeterminada podem ter seu fenótipo mimetizado por ação de fármacos que atuam diretamente nas\nmesmas proteínas. Pode-se afirmar que representa corretamente um fármaco, seus efeitos\nhidroeletrolíticos e uma doença hereditária com a mesma apresentação fenotípica,\nrespectivamente:","options":{"A":"hidroclorotiazída / hipopotassemia, alcalose metabólica, hipotensão arterial sistêmica / síndrome\nde Gitelman","B":"furosemida / hipopotassemia, acidose metabólica, hipotensão arterial sistêmica / síndrome de\nBartter","C":"amiloride / hiperpotassemia, acidose metabólica, hipotensão arterial sistêmica / síndrome de\nLiddle","D":"acetazolamida / hiperpotassemia, alcalose metabólica, hipertensão arterial sistêmica / acidose\ntubular renal proximal"},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-203010","number":"203010","sourceNumber":"203010","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"As patologias que estão associadas com a elevação do potássio, de maneira mais\nprecoce, por acometerem o néfron distal, são:","options":{"A":"Anemia falciforme e síndrome de Liddie.","B":"Diabetes mellitus e síndrome de Gitelman.","C":"Diabetes mellitus e nefropatia de anemia falciforme.","D":"Uropatia obstrutiva, intoxicação aguda por cioroquina."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-186771","number":"186771","sourceNumber":"186771","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A necrose tubular aguda possui como causa mais frequente a lesão:","options":{"A":"Isquêmica.","B":"Tóxica.","C":"Intersticial.","D":"Infiltrativa.","E":"Edemigênica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-80698","number":"80698","sourceNumber":"80698","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 57 anos, diabético tipo 2. Devido a histórico de precordialgia, realizou\ncineangiocoronariografia. Duas semanas após o procedimento, evoluiu com livedo reticular nos\nmembros inferiores e redução da diurese. Exames laboratoriais: hematócrito = 37%; leucócitos =\n8.400/mm³ (12% de eosinófilos e 64% de neutrófilos); sódio = 138 mEq/L; potássio = 4,8 mEq/L;\nureia = 127 mg/dl; creatinina = 3,6 mg/dl. A hipótese diagnóstica mais provável é:","options":{"A":"Ateroembolismo renal.","B":"Nefropatia por contraste.","C":"Nefrite intersticial aguda.","D":"Glomerulonefrite aguda."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-85180","number":"85180","sourceNumber":"85180","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Portador de síndrome nefrótica, em uso de esteroide, inicia quadro de náuseas, vômitos\ne dor em flanco esquerdo. Exames\ncomplementares evidenciam leucocitose, hematúria e rápido\ndeclínio da função renal. A hipótese diagnóstica mais provável é de:","options":{"A":"Tumor de rim direito.","B":"Pielonefrite aguda esquerda.","C":"Estenose de artéria renal esquerda.","D":"Tuberculose urinária no rim esquerdo.","E":"Trombose de veia renal esquerda."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-78283","number":"78283","sourceNumber":"78283","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Consiste causa de mioglobinúria, com teste positivo para sangue na urina:","options":{"A":"Tumor vesical.","B":"Tumor ureteral.","C":"Rabdomiólise.","D":"Carcinoma de células renais.","E":"Hipertensão maligna."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-78298","number":"78298","sourceNumber":"78298","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Consiste em importante causa de hipercalcemia:","options":{"A":"Deficiência de vitamina D.","B":"Pancreatite aguda.","C":"Insuficiência renal crônica.","D":"Pseudo-hipoparatireoidismo.","E":"Uso de diuréticos tiazídicos."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-47828","number":"47828","sourceNumber":"47828","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem com diagnóstico prévio de síndrome nefrótica apresenta dor súbita nos flancos\ne deterioração aguda da função renal. Considerando\na hipótese diagnóstica mais provável para o\nquadro agudo relatado, a lesão histopatológica determinante da nefrose seria:","options":{"A":"Membranoproliferativa tipo I.","B":"Membranoproliferativa tipo II.","C":"Membranosa.","D":"Segmentar e focal.","E":"Lesão mínima."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26318","number":"26318","sourceNumber":"26318","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na investigação de disfunção renal crônica acometendo mulher de 35 anos, você\npercebe Hb de 5,6 g%, creatinina de 4 mg/dl, ausência de edema, normotensão (110 x 70),\nglicemia de 129 mg/dl e proteinúria de 950 mg/24h. Fundamentado exclusivamente nessas\ninformações, você considera, como melhor hipótese diagnóstica:","options":{"A":"doença renal policística.","B":"amiloidose renal.","C":"nefrite tubulointersticial crônica.","D":"necrose cortical bilateral.","E":"nefropatia obstrutiva."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-21654","number":"21654","sourceNumber":"21654","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na avaliação clinicolaboratorial de uma criança com diagnóstico de síndrome de\nBartter, espera-se encontrar os seguintes dados clinicolaboratoriais:","options":{"A":"PA normal, sódio e potássio elevados.","B":"Hipertensão arterial e acidose metabólica.","C":"PA normal com renina e aldosterona elevadas.","D":"Hipertensão arterial com renina e aldosterona elevadas."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-7624","number":"7624","sourceNumber":"7624","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A intoxicação pelo metanol é causa de acidose metabólica grave e os seus metabólitos\ncausam:","options":{"A":"acidose metabólica com ânion-gap baixo.","B":"insuficiência renal.","C":"edema agudo de pulmão.","D":"insuficiência respiratória.","E":"severa lesão do nervo óptico e dano ao sistema nervoso central."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-351907","number":"351907","sourceNumber":"351907","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Coloque (V) verdadeiro ou (F) falso nas alternativas abaixo, em relação à injúria renal\naguda (IRA) associada ao contraste iodado,\nassinalando a seguir a opção correta. ( ) A elevação da\ncreatinina sérica ocorre nas primeiras 24/48h após a exposição ao contraste venoso e atinge níveis\nmáximos dentro de 3 a 5 semanas. ( ) O risco de desenvolver IRA ou \"nefropatia por contraste\" é\ninsignificante quando a função renal está previamente normal. ( ) Os pacientes com mieloma\nmúltiplo e doença renal prévia são particularmente suscetíveis.","options":{"A":"(F) (V) (F)","B":"(V) (V) (F)","C":"(F) (V) (V)","D":"(V) (F) (V)","E":"(V) (F) (F)"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-323872","number":"323872","sourceNumber":"323872","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Marque a opção que apresenta a relação correta entre a causa da lesão renal e\nanormalidades do sedimento urinário.","options":{"A":"Pielonefrite - cilindros pigmentados.","B":"Vasculite - cilindros hemáticos.","C":"Nefrite intersticial alérgica - eosinofilúria.","D":"Nefropatia por ácido úrico - cilindros hemáticos.","E":"Glomerulonefrite - cristalúria."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-265035","number":"265035","sourceNumber":"265035","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Vários fatores contribuem para a lesão renal do portador de mieloma múltiplo, cuja\nocorrência é em torno de 25% a 50% dos pacientes. Se o paciente com essa gamopatia\nmonoclonal começa a apresentar no exame de urina: glicosúria, aminoacidúria, bicarbonatúria e\ndificuldade na concentração urinária, a principal hipótese diagnóstica é:","options":{"A":"Hipercalcemia;","B":"Hiperuricemia;","C":"Acidose tubular renal tipo 2;","D":"Necrose tubular aguda por cadeias leves;","E":"Nefropatia por urato;"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-273239","number":"273239","sourceNumber":"273239","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 26 anos procura atendimento por quadro de mialgia súbita, astenia,\nnáuseas, parestesia de membros inferiores, redução\ndo débito urinário e a urina com cor marrom\nescura cerca de 20 horas após comer peixe de água doce da espécie Tambaqui. Ao exame físico\npaciente desidratado (2+/4+), hipocorado 1+/4+, anictérico, taquipneico e acianótico. Sinais vitais:\nFC 110 BPM; PA: 88X58 mmHg; FR: 28 IRPM; Tax 37,9º C. Foram solicitados exames laboratoriais\n(sangue) que revelaram bilirrubina total de 1,2mg/dl, bilirrubina direta de 0,8mg/dl, Aspartato\nAminotransferase de 800 UI/L, Alanina Aminotransferase de 150 UI/L, Creatinoquinase Total de\n\n20.000 UI/L, Creatinoquinase Fração MB de 180 UI/L, Lactato desidrogenase 900 UI/L. Leucócitos\nde 12.000, com diferencial 0/0/0/0/5/65/20/10,\nPlaquetas: 160.000, Hemoglobina de 13 g/dl, Uréia\nde 80mg/dl, Creatinina de 2,0 mg/dl, Sódio de 136 mEq/L, Potássio de 5,8 mEq/L, Cloreto de 102\nmEq/L e Bicarbonato de 10 mEq/L. Assinale a alternativa que contém, respectivamente o provável\ndiagnóstico, as alterações encontradas no exame de urina e a conduta terapêutica recomendada.","options":{"A":"Síndrome hemolítico-urêmica, presença de positividade para hemoglobina na tira reagente com\nhematúria microscópica e hemodiálise de urgência.","B":"Doença de Haff, presença de positividade para hemoglobina na tira reagente com hematúria\nmicroscópica e hemodiálise de urgência.","C":"Síndrome hemolítico-urêmica, presença de positividade para hemoglobina na tira reagente sem\nhematúria microscópica e hidratação venosa vigorosa.","D":"Doença de Haff, presença de positividade para hemoglobina na tira reagente sem hematúria\nmicroscópica e hidratação venosa vigorosa.","E":"Síndrome hemolítico-urêmica, presença de positividade para hemoglobina na tira reagente com\nhematúria microscópica e reposição de bicarbonato."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-262669","number":"262669","sourceNumber":"262669","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com relação às acidoses tubulares renais em crianças, é CORRETO afirmar que:","options":{"A":"A acidose tubular renal distal se caracteriza por pH urinário < `5,5, nefrocalcinose e potássio\nsérico alto.","B":"Acidose tubular renal proximal se caracteriza por ânion gap urinário positivo e potássio sérico\nalto.","C":"Acidose tubular renal tipo IV se caracteriza por pH urinário variável, potássio sérico alto e\nânion\ngap urinário positivo.","D":"Na síndrome de Fanconi há acidose tubular renal distal.","E":"Acidose metabólica com ânion gap sérico normal é mais frequentemente causada por acidose\ntubular renal."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-254312","number":"254312","sourceNumber":"254312","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 40 anos, previamente hígido, compareceu ao ambulatório de Clínica\nMédica para consulta de 1ª vez com artrite em\npequenas articulações das mãos há 2 meses. Nesta\nocasião, foram solicitados exames laboratoriais e de imagem, bem como iniciado anti-inflamatório\nnão hormonal (ibuprofeno 1,8 g/dia). Retornou à consulta em 45 dias, tendo realizado os exames\nsolicitados na véspera da consulta. Ainda apresentava artrite, embora um pouco melhor, e\nnenhuma outra queixa. Baseado nos exames, recebeu diagnóstico de artrite reumatoide, mas\napresentava uma hematúria microscópica, o que não passou despercebido pelo médico. A melhor\nexplicação para esta hematúria seria:","options":{"A":"Nefrite intersticial associada ao uso de ibuprofeno.","B":"Amiloidose como complicação da artrite reumatoide.","C":"Glomerulonefrite membranosa associada à artrite reumatoide.","D":"Síndrome nefrítica, comum em pacientes com artrite reumatoide inicial."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-246943","number":"246943","sourceNumber":"246943","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 28 anos com endocardite infecciosa, febril, inicia tratamento empírico. Após\nnove dias de tratamento, desenvolve\nretenção de escórias nitrogenadas, porém mantendo volume\nurinário normal. O sedimento urinário mostra eosinófilos e piúria estéril. O quadro clínico\nlaboratorial\ncorresponde a:","options":{"A":"Necrose tubular aguda.","B":"Nefrite intersticial aguda.","C":"Insuficiência renal aguda relacionada à sepse.","D":"Insuficiência renal aguda relacionada à isquemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-249146","number":"249146","sourceNumber":"249146","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 40 anos, masculino, em bom estado geral, apresentando quadro de mal\nestar geral, febre Tax. 38ºC e discreta dor\nlombar à direita há cerca de uma semana. Relata ter feito\nuso recente de AINE devido a trauma em joelho direito. Exame físico sem alterações. Realizou EAS\ntipo 1 que evidenciou presença de proteínas ++ e hemácias ++ além de cilindros leucocitários no\nsedimento. Com base nesses dados qual o diagnóstico mais provável?","options":{"A":"Nefrolitiase","B":"Pielonefrite aguda","C":"Nefrite intersticial aguda","D":"Glomerulonefrite aguda"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-252977","number":"252977","sourceNumber":"252977","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente com histórico de síndrome de Sjögren tem os seguintes resultados\nlaboratoriais: sódio plasmático 139 mEq / L,\ncloreto 112 mEq / L, bicarbonato 15 mEq / L e potássio\n3,0 mEq / L. Estudos de urina mostram pH de 6,0, sódio de 15 mEq / L, potássio de 10 mEq / L e\ncloreto de 12 mEq / L. Qual é o diagnóstico mais provável?","options":{"A":"Diarreia crônica","B":"Acidose tubular renal tipo I (ATR)","C":"ATR tipo II","D":"ATR tipo III","E":"ATR tipo IV"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-253729","number":"253729","sourceNumber":"253729","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente evoluiu com lesão renal aguda e o EAS apresenta eosinofilúria. De acordo\ncom esse achado, a hipótese diagnóstica mais\nprovável seria:","options":{"A":"Doença ateroembólica.","B":"Vasculite de pequenos vasos.","C":"Emergência hipertensiva.","D":"Glomerulonefrite."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-202195","number":"202195","sourceNumber":"202195","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre a nefrite intersticial, podemos afirmar que uma indicação relativa para o uso de\ncorticoides e agentes imunossupressores é a:","options":{"A":"Síndorme de Sjögren.","B":"Sarcoidose.","C":"Nefrite intersticial do LES.","D":"Criança com nefrite tubulointersticial e uveite.","E":"Nefrite intersticial idiopática."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-220504","number":"220504","sourceNumber":"220504","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Lactente, 2 meses, é admitido no PS com desidratação de 3° grau (grave). Você inicia a\nressuscitação volêmica e colhe exames: Na? = 125 mEq/ml e K? = 7,5 mEq/ml. Todas as hipóteses\nabaixo são possíveis, EXCETO:","options":{"A":"Hiperplasia adrenal congênita, perdedora de sal.","B":"Síndrome de Bartter.","C":"Hiperaldosteronismo.","D":"Disfunção renal aguda."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-205117","number":"205117","sourceNumber":"205117","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Você é ortopedista da equipe brasileira de ginástica e uma das atletas, com 16 anos de\nidade, procura seu consultório com queixa de fadiga, fraqueza difusa e câimbras musculares. Ela\nnão tem história prévia de doenças e nega uso de álcool e drogas ilícitas. O exame físico revela\numa jovem de baixa estatura, com IMC= 18 kg/m2 e com pressão arterial normal. O exame da\ncavidade oral mostra dentes em estado ruim de conservação. O tônus muscular e o exame\nneurológico são normais. Exames laboratoriais revelam hematócrito de 38,5%, creatinina de 0,6\nmg/dL, bicarbonato sérico de 30 mEq/L e potássio sérico de 2,7 mEq/L. Qual o próximo passo para\na investigação deste caso?","options":{"A":"Dosagem de renina e aldosterona plasmáticos","B":"Dosagem sérica de magnésio","C":"Urinálise e urinocultura","D":"Pesquisa toxicológica para presença de diuréticos na urina","E":"Pesquisa toxicológica para presença de opióides na urina"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-217488","number":"217488","sourceNumber":"217488","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, sexo feminino, com 32 anos, apresenta hipertensão arterial secundária a\nestenose da artéria renal. Qual a causa mais provável para a estenose?","options":{"A":"Aterosclerose","B":"Doença de behçet","C":"Displasia fibromuscular","D":"Lúpus"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-217487","number":"217487","sourceNumber":"217487","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O mieloma múltiplo é capaz de gerar distúrbios renais. A síndrome de Fanconi, que\napresenta comprometimento na reabsorção de glicose e bicarbonato, ocorre em qual segmento\nrenal?","options":{"A":"Cálice renal.","B":"Túbulo distal.","C":"Túbulo coletor.","D":"Túbulo proximal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-187815","number":"187815","sourceNumber":"187815","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 45 anos, previamente hígido, compareceu ao ambulatório da PDC para\nconsulta de 1ª vez com artrite em pequenas articulações das mãos há 2 meses. Nesta ocasião,\nforam solicitados exames laboratoriais e de imagem, bem como iniciado anti-inflamatório não\nhormonal (ibuprofeno 1,8 g/dia). Retornou à consulta em 45 dias, tendo realizado os exames\nsolicitados na véspera da consulta. Ainda apresentava artrite, embora um pouco melhor, e\nnenhuma outra queixa. Baseado nos exames, recebeu diagnóstico de artrite reumatoide, mas\napresentava uma hematúria microscópica que deixou os alunos intrigados. A melhor explicação\npara esta hematúria seria:","options":{"A":"Nefrite intersticial associada ao uso de ibuprofeno.","B":"Amiloidose como complicação da artrite reumatoide.","C":"Glomerulonefrite membranosa associada à artrite reumatoide.","D":"Síndrome nefrítica, comum em pacientes com artrite reumatoide inicial."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-180567","number":"180567","sourceNumber":"180567","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O físico alemão Georg Simon Ohm, no século XIX, apresentou à ciência sua lei, na qual\ndescrevia a resistência elétrica como sendo a razão entre a tensão entre dois pontos e a corrente\nelétrica. No mesmo século, Jean-Louis-Marie Poiseuille, renomado médico à época, publicava\ntrabalhos sobre a circulação humana cujos resultados iriam ao encontro daqueles de Georg\nOhm.No entanto, Poiseuille tratava dos fluidos enquanto Ohm, eletricidade. Em linhas gerais,\n\npode-se dizer que a resistência efetiva de um tubo é inversamente proporcional ao raio, elevado a\nquarta potência. Isto significa que uma redução do tubo pela metade aumentaria a resistência ao\nmovimento do fluido em 16 vezes.Onde:DeltaP: é a diferença de pressão; L: é o comprimento do\ntubo; ?: é a viscosidade dinâmica; Q: é a taxa volumétrica do fluxo; r: é o raio do tubo; d: é o\ndiâmetro do tubo; PI: é a constante matemática (aproximadamente 3,1416). Paciente 62 anos,\nhipertensa há 40 anos, deu entrada na emergência taquidispnéica. Apresentava PA 220x130\nmmHg, FC 88 bpm e SpO2 de 88%. A ausculta pulmonar evidenciava estertorações crepitantes,\npredominantes à direita. Após estabilização da paciente, descobriu-se que a mesma já tivera 3\nepisódios semelhantes, com entrada na emergência.Vinha em uso regular de Anlodipina 10mg/dia,\nHidroclorotiazida 25mg, Hidralazina 25mg 8/8h e Clonidina 0,1 mg. Na prescrição de alta, foi\nadicionado Captopril 25mg 8/8h. Após 8 dias, a paciente retornou à emergência, apresentando\nsingultos, bradpsiquismo, astenia importante. Apresentava um sopro abdominal com irradiação para\nflanco direito. No laboratório de admissão, evidenciou-se elevação importante de escórias\nnitrogenadas (Cr 3,8 mg/dl e uréia 196). A função renal da paciente no momento da alta, há 8 dias\natrás, era normal. Diante disso, a principal hipótese para patologia de base nesse caso, assim\ncomo o exame útil para seu diagnóstico é:","options":{"A":"Feocromocitoma - Dosagem de metanefrinas urinárias.","B":"Estenose da artéria renal - Ecodoppler de artéria renal.","C":"Hiperaldosteronismo primário - Ultrasom abdominal.","D":"Hiperaldosteronismo primário - Ressonância Magnética crânio.","E":"Estenose da artéria renal - Dosagem da atividade de renina urinária."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-182995","number":"182995","sourceNumber":"182995","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino de 28 anos, refere histórico de hipertensão arterial, e encontra-se\ncom dificuldade de controle dos níveis tensionais.\nRecentemente, foi acrescentado inibidor de\nenzima de conversão ao tratamento e observou-se expressiva retenção azotada. Assinale a opção\nmais provável em relação ao diagnóstico:","options":{"A":"Estenose renal bilateral causada por hiperplasia fibromuscular.","B":"Estenose renal unilateral causada por hiperplasia fibromuscular.","C":"Estenose renal causada por doença aterosclerótica.","D":"Doença renal tubulointersticial."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-157484","number":"157484","sourceNumber":"157484","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 52 anos, do sexo masculino, procura atendimento de urgência na UPA por\napresentar dor torácica precordial de início súbito há uma hora, enquanto dirigia, em aperto,\nirradiada para o braço esquerdo, sem fator de alívio, seguida de sudorese e sensação de morte\niminente. Nega doenças prévias, tabagismo ou história familiar de doença cardiovascular, variação\nponderal recente (peso habitual = 68 kg), afirmando apenas que há dois meses apresentou quadro\nde tosse, chieira no peito, astenia, febre baixa, atribuído a infecção respiratória por H1N1, mas\ncom\nmelhora sem uso de medicação específica. Ao chegar à emergência, são realizados\neletrocardiograma que mostra supradesnivelamento do segmento ST em parede anterolateral, e\nexames laboratoriais que mostravam: mioglobina = 0,30 ?g/ml (N= até 0,15 ?g/ml); troponina T =\n0,1 ng/ml (N = até 0,1 ng/ml); creatinofosfoquinase-fração MB (CKMB) = 3 ng/ml (N= até 5 ng/ml);\ncreatinina sérica de 4,5 mg/dl (N= 0,4 a 1,4 mg/dl); ureia = 132 mg/dl (N= 20 a 40 mg/dl); potássio\n=\n6,2 mEq/l (N = 3,5 a 5,5 mEq/L). Considerando-se a necessidade de realização de exame de\nimagem contrastado para avaliação da doença coronariana neste paciente com risco de piora da\nfunção renal, assinale a afirmativa CORRETA:","options":{"A":"Os contrastes iodados utilizados nos exames de imagem cardiovasculares não causam\ninsuficiência renal aguda, pois a elevação da\ncreatinina sérica ocorre nas primeiras 24-48 h depois\nda exposição e regride dentro de uma semana.","B":"Medidas profiláticas apropriadas devem incluir uso de diuréticos durante a exposição ao\ncontraste, escolher contrastes radiográficos com menor potencial nefrotóxicos, além da\nadministração cuidadosa de glicose e N-acetilcisteína.","C":"Nos pacientes que compreendam e aceitem os riscos associados ao cateterismo cardíaco, não\nhá\n\ncontraindicações absolutas quando o procedimento for realizado para uma intervenção\npotencialmente salvadora da vida.","D":"Em vigência do comprometimento renal, a ressonância magnética cardíaca com gadolínio\npermite identificar com melhor acurácia defeitos\nde perfusão coronariana e sua extensão, além da\n\navaliação da contratilidade miocárdica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-155994","number":"155994","sourceNumber":"155994","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na nefropatia por contraste é possível afirmar:","options":{"A":"o uso de bicarbonato é imprescindível.","B":"o uso de acetil-cisteína de comprovado efeito de proteção renal.","C":"a lesão renal não está associada a quantidade de contraste infundida no paciente.","D":"hidratação ainda é a melhor medida protetora."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-128044","number":"128044","sourceNumber":"128044","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Jovem de 23 anos apresentou síncope durante exercício físico vigoroso. Chega ao\npronto-socorro cerca de uma hora após, apresentando pulso de 95 batimentos por minuto, pressão\narterial de 120 x 80 mmHg e escore de 15 na escala de Glasgow, além do aumento de escórias\nnitrogenadas e de enzimas musculares. Ao ser sondado, nota-se que tem diurese escura. Assinale\no diagnóstico mais provável e o melhor tratamento:","options":{"A":"Choque hipovolêmico/reposição volêmica.","B":"Síndrome de Gilbert/hidratação com solução salina isotônica.","C":"Lesão traumática de uretra/cistostomia.","D":"Rabdomiólise/hidratação venosa.","E":"Porfiria aguda intermitente/diuréticos."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-136499","number":"136499","sourceNumber":"136499","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Como tratamento da hipercalcemia grave em paciente com síndrome de lise tumoral\nestá indicado:","options":{"A":"Hidratação com solução salina, vitamina D, uso de bifosfonatos e fosfato oral.","B":"Restrição hídrica, diurese forçada, glicocorticoides e vitamina D.","C":"Hidratação com solução salina, diurese forçada, uso de bifosfonatos e glicocorticoides.","D":"Restrição hídrica, diurese forçada, fosfato oral e glicocorticoides."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-138890","number":"138890","sourceNumber":"138890","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com relação à nefrite intersticial, qual das indicações abaixo é relativa para o uso de\ncorticoides e agentes imunossupressores?","options":{"A":"Síndrome de Sjögren.","B":"Sarcoidose.","C":"Nefrite intersticial do LES.","D":"Criança com nefrite tubulointersticial com uveíte.","E":"Nefrite intersticial idiopática."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-135148","number":"135148","sourceNumber":"135148","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na síndrome de Bartter e na síndrome de Gitelman, ocorrem distúrbios autossômicos\nrecessivos com pressão arterial normal e:","options":{"A":"Diminuição do cloreto urinário, alcalose metabólica e hipernatremia.","B":"Diminuição do cloreto urinário, acidose metabólica e hipercalcemia.","C":"Elevação do cloreto urinário, alcalose metabólica e hipocalemia.","D":"Elevação do cloreto urinário, acidose metabólica e hiponatremia."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-102546","number":"102546","sourceNumber":"102546","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Hiperuricemia e insuficiência renal aguda podem resultar de síndrome de lise tumoral\napós quimioterapia para algumas neoplasias hematológicas. Com relação ao tratamento de\nemergência da hiperuricemia grave, assinale a alternativa errada:","options":{"A":"Promover hiper-hidratação","B":"Em casos muito graves, realizar hemodiálise de emergência","C":"Alcalinizar a urina com bicarbonato de sódio intravenoso para prevenção da cristalização do\nácido úrico","D":"Ofertar alopurinol, um inibidor competitivo da xantina-oxidase","E":"Forçar diurese com diuréticos tiazídicos para evitar depósitos de cristais nos túbulos renais"},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-110859","number":"110859","sourceNumber":"110859","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"No paciente com estenose de artéria renal, é indicação absoluta a revascularização da\nlesão caso o paciente apresente:","options":{"A":"piora progressiva da função renal associada ao uso de anti-inflamatório.","B":"hipertensão arterial sistêmica bem controlada.","C":"edema agudo de pulmão refratário sem outra causa atribuível.","D":"hipocalemia.","E":"hipermagnesemia."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-105440","number":"105440","sourceNumber":"105440","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 25 anos de idade, dá entrada na emergência com agitação\npsicomotora e alucinações auditivas e\nvisuais. Refere fraqueza muscular difusa. Ao exame,\nencontra-se febril 39°C, PA = 160 x 100 mmHg e FC = 124 bpm. A urina encontra-se em coloração\nchá escuro, e o exame EAS revela proteinúria sem hematúria. Pesquisa de cocaína na urina é\npositiva. O diagnóstico clínico mais provável é:","options":{"A":"Leptospirose.","B":"Rabdomiólise.","C":"Encefalopatia hepática.","D":"Nefropatia por IgA."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106217","number":"106217","sourceNumber":"106217","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Os receptores mineralocorticoides presentes no túbulo renal são responsáveis pela\nretenção de sódio e espoliação de potássio que ocorre nos casos de excesso de\nmineralocorticoides, como a presença de tumores secretores de aldosterona. No entanto em\nestados de excesso de glicocorticoides (Síndrome de Cushing), também pode ocorrer\nhipernatremia com hipocalemia. Qual característica das vias mineralocorticoide-glicocorticoide\nexplica esse achado?","options":{"A":"Menor afinidade dos receptores mineralocorticoides por glicocorticoides.","B":"Saturação da via de degradação glicorticoide em estados de excesso de glicocorticoides.","C":"Sítios de ligação de DNA distintos, porém com similaridades que os levam a produzir o mesmo\nefeito metabólico.","D":"Um aumento do número de proteínas ligadoras de mineralocorticoides (\"upregulation\") nos\nestados de excesso de glicocorticoides.","E":"Saturação da enzima 11-B hidroxidesidrogenase em estados de excesso de glicocorticoides."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-82790","number":"82790","sourceNumber":"82790","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino jovem, com agitação psicomotora, agressividade e alucinações\nauditivas e visuais. Queixa-se também de\nfraqueza muscular difusa. Ao exame: temperatura de\n38°C; FC = 120 bpm; PA = 150 x 100 mmHg. A urina tem coloração de chá escuro, o EAS revela\nproteinúria sem hematúria. A pesquisa de cocaína na urina é positiva. O diagnóstico mais provável\npara o quadro clínico é:","options":{"A":"Rabdomiólise.","B":"Leptospirose.","C":"Nefropatia por IgA.","D":"Encefalopatia hepática."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81873","number":"81873","sourceNumber":"81873","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente 29 anos, masculino, solteiro, previamente hígido, refere história de edema de\nmembros inferiores de início há dois meses e que, em três dias, evoluiu para um quadro anasarca.\nEsteve internado, onde recebeu diurético e melhorou do edema generalizado. Refere odinofagia\numa semana antes do início do edema. Refere urina espumosa com cor avermelhada. Refere\nlombalgia de característica mecânica, pela qual fez uso crônico de anti-inflamatórios previamente\nao quadro de anasarca e hiperlipidemia de longa data. Exame físico: Peso: 68,5 kg, Altura: 1,70 m,\nIMC: 24 kg/m², FC: 68 bpm, PA: 160,95 mmHg. Bom estado, eupneico, afebril, corado, hidratado,\nglasgow 15. Orofaringe sem alterações, MV+ e simétrico, sem RA. 2BRNF, sem sopros. Abdômen\nindolor, sem massas ou visceromegalias. Membros inferiores com edema 1+/4+ até terço médio\ndas pernas, bilateralmente. Exames laboratoriais: creatinina 3,5 mg/dl, ureia 149 mg/dl, Na: 135, K:\n3,5, albumina de 2,2 g/dl, hemoglobina 11,6 g/dl, hematócrito 34,5%, leucócitos 7870 (com\n\neosinofilia 600), plaquetas 260000, PCR 0,9 mg/dl; Urina tipo 1: pH: 5; d:1015, proteínas > 4 g/L,\nhemácias +100/c; leucócitos +100/c; proteinúria de 24h: 12,8 g; urocultura negativa. Sorologias\npara HIV e hepatite C e B negativas; FAN, anti-ENA e ANCA negativos. Dosagem de complemento\nCH100: 250 (VR: 150-350). ASLO negativo. Qual o provável diagnóstico?","options":{"A":"Síndrome nefrítica.","B":"Síndrome nefrótica.","C":"Necrose tubular aguda isquêmica e tóxica.","D":"Nefrose intersticial relacionada à infecção.","E":"Glomérulo nefrite rapidamente progressiva."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83221","number":"83221","sourceNumber":"83221","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente diabético apresenta o seguinte perfil laboratorial: acidose metabólica,\nhipercloremia, com ânion-gap normal,\nhiponatremia, hiperpotassemia e PH urinário < 5,5. Qual é o\nprovável diagnóstico?","options":{"A":"Hipoaldosteronismo hiporreninêmico (acidose tubular renal do tipo IV).","B":"Acidose tubular renal distal (tipo I).","C":"Acidose tubular renal proximal (tipo II).","D":"Excesso de reposição volêmica com solução salina.","E":"Intoxicação por salicilato."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83362","number":"83362","sourceNumber":"83362","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Síndrome de lise tumoral é caracterizado por:","options":{"A":"Hipercalcemia, hipocalemia, hiperuricemia, alcalose metabólica, hiponatremia.","B":"Hiperuricemia, hipercalemia, hiperfosfatemia, acidose láctica, hipocalcemia.","C":"Hipouricemia, hipercalemia, hipofosfatemia, acidose láctica, hipocalcemia.","D":"Hiperuricemia, hipercalemia, hiperfosfatemia, alcalose metabólica, hipocalcemia.","E":"Hiperuricemia, hipercalemia, hipofosfatemia, hipercalcemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-82911","number":"82911","sourceNumber":"82911","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na intoxicação pelo chumbo, observa-se que:","options":{"A":"os efeitos tóxicos manifestam-se sobretudo nos sistemas gastrointestinal, hematopoiético,\nnervoso (central e periférico) e renal.","B":"não há associação clara entre os níveis de chumbo no sangue e a presença de sintomas.","C":"a forma de intoxicação mais comum é a crônica.","D":"a anemia é geralmente macrocítica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83365","number":"83365","sourceNumber":"83365","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Ainda em relação à síndrome de lise tumoral, a prevenção da insuficiência renal aguda\ndeverá ser com:","options":{"A":"Diurético.","B":"Acidificação da urina.","C":"Nacetilcisteína.","D":"Alopurinol, hidratação e alcalinização da urina.","E":"Diálise."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84036","number":"84036","sourceNumber":"84036","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente jovem, do sexo masculino, deu entrada neste hospital com intensa dor\nmuscular e fraqueza de membros inferiores.\nRelatava ter reiniciado atividade física havia 48 horas,\napós longo tempo de inatividade. Exames laboratoriais revelavam hemograma com série vermelha\nnormal, leucograma = 12.120 mm³ com diferencial 0/0/0/0/3/76/20/1, creatinina = 2,2 mg/dl, ureia =\n68 mg/dl, eletrólitos normais, CPK = 5580 U/L. Com as informações acima, qual das opções abaixo\nassinala uma droga que deve ser evitada neste caso?","options":{"A":"Diclofenaco de sódio;","B":"Bicarbonato de sódio;","C":"Lansoprazol;","D":"Tramadol."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-89883","number":"89883","sourceNumber":"89883","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Você está fazendo a rotina da enfermaria quando há necessidade de tomografar um\npaciente de 54 anos, diabético e hipertenso, o qual tendo apresentado quadro de dor abdominal em\nepigástrico de forte intensidade e apresentando discreta icterícia de escleras, ele tem como\nsuspeita um quadro de pancreatite biliar. Sendo assim foi proposta realização de tomografia\ncomputadorizada contrastada. Que medida você adotaria visando minimizar nefropatia induzida por\ncontraste baseado em melhores evidências:","options":{"A":"Fazer uso de acetil cisteína 600 mg intra-venosa 1h antes do exame e 6h após.","B":"Fazer hidratação venosa com SFO,9% 1 ml/Kg/h 12h antes e manter por 12h após exame.","C":"Fazer uso de 100 ml manitol 20% intra-venoso 1h antes do exame.","D":"Indicar uso de ácido ascórbico 4G via oral antes do procedimento visando maior eliminação de\nradical livre.","E":"Indicar uso de furosemida pré e pós uso contraste visando maior eliminação do mesmo."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-88228","number":"88228","sourceNumber":"88228","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Entre as alternativas abaixo, assinale a que mais sugere um quadro de insuficiência\nrenal aguda de etiologia pré-renal:","options":{"A":"Osmolaridade urinária aumentada, sódio urinário baixo, proteinúria aumentada.","B":"Osmolaridade urinária aumentada, fração de excreção de sódio reduzida, hematúria dismórfica.","C":"Osmolaridade urinária reduzida, fração de excreção de sódio reduzida, sedimento normal.","D":"Osmolaridade urinária aumentada, fração de excreção de sódio reduzida, sedimento urinário\nnormal.","E":"Osmolaridade urinária aumentada, sódio urinário aumentado, sedimento urinário normal."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81611","number":"81611","sourceNumber":"81611","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual dos marcadores laboratoriais abaixo é mais útil como indicador de melhora da\nfunção renal em um paciente com Síndrome de Lise Tumoral e Insuficiência Renal Aguda?","options":{"A":"Creatinina.","B":"Potássio.","C":"Cálcio.","D":"Fosfato.","E":"Acido úrico."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81595","number":"81595","sourceNumber":"81595","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 70 anos, submetido a cateterismo cardíaco na suspeita de doença\ncoronariana oclusiva, passou a apresentar\nconfusão mental, epigastralgia, diminuição de pulsos\nperiféricos e livedo reticular. Exames de sangue mostravam ureia de 165 mg/dl, creatinina de 5,1\nmg/dl. O sedimento urinário acusava 10 a 15 leucócitos, 10 hemácias e alguns cilindros hialinos. O\ndiagnóstico mais provável é:","options":{"A":"Dissecção arterial com lesão renal aguda pré-renal.","B":"Necrose tubular aguda por contraste.","C":"Nefrite intersticial aguda.","D":"Doença ateroembólica.","E":"Rabdomiólise com necrose tubular aguda."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-63613","number":"63613","sourceNumber":"63613","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A Insuficiência Renal Crônica (IRC) é uma afecção cada vez mais comum na população\nmundial, principalmente com o envelhecimento e aumento de doenças crônicas como diabetes e\nhipertensão. Várias estratégias têm sido empregadas para prevenir a deteriorização adicional da\nfunção renal em pacientes já acometidos pela doença e em pacientes internados por outras\nafecções. Dentre as estratégias abaixo, qual apresenta MENOR evidência científica de prevenção\nde piora da função renal?","options":{"A":"Reposição venosa de albumina em pacientes cirróticos que realizam paracentese com retirada\nsuperior a 5 litros","B":"Uso de N-acetilcisteína antes da realização de exames contrastados","C":"Uso de alopurinol ou rasburicase em pacientes com neoplasias hematológicas em quimioterapia","D":"Monitoramento do nível sérico de drogas nefrotóxicas, quando necessário seu uso."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-64548","number":"64548","sourceNumber":"64548","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 80 anos, com arterioesclerose generalizada, interna com quadro de\nInsuficiência Renal Aguda (IRA), 4 dias após\nrealização de aortografia. Ao exame físico, notava-se\nlivedo reticularis em membros inferiores, dedos dos pés azulados, hipocomplementenemia e\neosinofilúria. O diagnóstico mais provável é:","options":{"A":"IRA por aneurisma dissecante de aorta.","B":"IRA pós-contraste.","C":"IRA por nefrite intersticial.","D":"IRA ateroembólica."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-63180","number":"63180","sourceNumber":"63180","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 72 anos de idade, desenvolve insuficiência renal aguda\napós cateterismo cardíaco. O exame físico chama\natenção para diminuição dos pulsos periféricos,\nlivedo reticular, hipersensibilidade epigástrica e confusão mental. Os estudos laboratoriais incluem\n(mg/L) BUN de 131, creatinina de 5,2 e fosfato de 9,5. A urinálise demonstra valor de 10 a 15 para\nleucócitos, 5 a 10 para hemácias e 1 para cilindro hialino por campo de grande aumento (HPF). O\ndiagnóstico mais provável é:","options":{"A":"Nefrite intersticial aguda causada por drogas.","B":"Rabdomiólise com necrose tubular aguda.","C":"Necrose tubular secundária à exposição à radiocontraste.","D":"Embolização por colesterol.","E":"Dissecção arterial renal com azotemia pré-renal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-61124","number":"61124","sourceNumber":"61124","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A síndrome de Bartter, doença tubular renal genética, caracteriza-se por apresentar:","options":{"A":"Perda de sódio, potássio e cloro com níveis pressóricos elevados.","B":"Sódio e potássio baixo associado à acidose metabólica hipocalêmica.","C":"Poliúria, polidipsia, deficiência de ganho ponderoestatural e níveis pressóricos normais.","D":"Alcalose metabólica hipocalêmica com níveis de renina e aldosterona normais.","E":"Poliúria, polidipsia e acidose metabólica hipocalêmica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-71098","number":"71098","sourceNumber":"71098","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"M.G.R, 41 anos, feminino, parda, diarista, previamente hígida, internada com história de\ndor lombar crônica em uso constante de anti-inflamatórios não hormonais. Após realização de\ngrande esforço físico, apresentou piora importante da dor lombar, aumentando por conta própria a\ndose do Diclofenaco sódico, passando a fazer 3 comprimidos de 100 mg ao dia. Cerca de 5 dias\napós, iniciou rash cutâneo, febre de 38ºC, cefaleia occipital, diminuição significativa da diurese,\nedema de face e MMII, além de anorexia e náuseas. Procurou atendimento na UPA onde foi\nverificada pressão arterial = 160/100 mmHg e foram realizados os seguintes exames laboratoriais:\nHemograma: Hematócrito = 37%; Hemoglobina = 12,7 g/dl; Hm = 4400000 mm³; Leucócitos = 9600\ncel./mm³, com 8 com 8 eosinófilos. Bioquímica: Glicemia = 86 mg%, Ureia = 64 mg%, Creatinina =\n1,4 mg% Na+ = 135 mEq/L, K+ = 4,9 mEq/L. Foi encaminhada para internação no dia seguinte,\ncom os seguintes resultados de exames laboratoriais: Ureia = 104 mg%, Creatinina = 3,7mg%, Na+\n\n= 134 mEq/L, K+ = 5,1 mEq/L. Diante do caso relatado, assinale a opção que identifica os achados\nde exame complementar compatíveis com a\nhipótese diagnóstica:","options":{"A":"Gasometria arterial com alcalose metabólica, devido à Insuficiência Renal Crônica;","B":"Eosinofilúria na análise do EAS, sugerindo a hipótese de Nefrite Intersticial Aguda;","C":"Sedimentoscopia no EAS com cilindros céreos, relacionados à Insuficiência Renal Aguda;","D":"Gasometria arterial com acidose respiratória, decorrente do quadro de Síndrome Nefrótica."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-71112","number":"71112","sourceNumber":"71112","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"M.G.R, 41 anos, feminino, parda, diarista, previamente hígida, internada com história de\ndor lombar crônica em uso constante de anti-inflamatórios não hormonais. Após realização de\ngrande esforço físico, apresentou piora importante da dor lombar, aumentando por conta própria a\ndose do Diclofenaco sódico, passando a fazer 3 comprimidos de 100 mg ao dia. Cerca de 5 dias\napós, iniciou rash cutâneo, febre de 38ºC, cefaleia occipital, diminuição significativa da diurese,\nedema de face e MMII, além de anorexia e náuseas. Procurou atendimento na UPA onde foi\nverificada pressão arterial = 160/100 mmHg e foram realizados os seguintes exames laboratoriais:\nHemograma: Hematócrito = 37%; Hemoglobina = 12,7 g/dl; Hm = 4400000 mm³ ; Leucócitos = 9600\ncel./mm³, com 8 eosinófilos. Bioquímica: Glicemia = 86 mg%, Ureia = 64 mg%, Creatinina = 1,4\nmg% Na+ = 135 mEq/l, K+ = 4,9mEq/L. Foi encaminhada para internação no dia seguinte, com os\nseguintes resultados de exames laboratoriais: Ureia = 104 mg%, Creatinina = 3,7 mg% Na+ = 134\nmEq/l, K+ = 5,1 mEq/L. A hipótese etiológica mais provável para este caso:","options":{"A":"Nefroesclerose Hipertensiva;","B":"Glomeruloesclerose Diabética;","C":"Glomerulonefrite Aguda Pós-Infecciosa;","D":"Lesão renal por uso de AINH."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-47902","number":"47902","sourceNumber":"47902","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Todas as afirmativas abaixo estão erradas, EXCETO:","options":{"A":"A Síndrome de Lise Tumoral manifesta-se geralmente nas primeiras 24-48h após a realização\nda quimioterapia.","B":"O tumor maligno de pulmão é o mais frequente no Brasil.","C":"Na neutropenia febril geralmente identifica-se pneumonia ou infecção do catéter.","D":"A infecção por Helicobacter pylori está relacionada com as neoplasias gástricas tipo GIST,\nlinfoma Malt e adenocarcinoma.","E":"O tabagismo não é fator de risco para o câncer do colo uterino."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-47938","number":"47938","sourceNumber":"47938","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Leia atentamente as afirmativas abaixo e assinale a opção correta: 1- Podemos estimar\no clearance de creatinina a partir de uma\nfórmula que utiliza a idade, o peso do paciente e a\ncreatinina sérica no seu cálculo. 2 - Diante de um paciente com edema generalizado, proteinúria\nmaciça, hipoalbuminemia e aumento do colesterol, devemos pensar em doença glomerular,\ninsuficiência renal obstrutiva e toxicidade por aminoglicosídeos. 3 - A presença de disúria, queda\ndo\nestado geral, febre e a presença do sinal de Giordano sugerem fortemente pielonefrite aguda, cujo\ndiagnóstico é clínico. 4- Hipertensão renovascular é considerada uma forma de hipertensão\nsecundária e deve-se à estenose da artéria renal. Pode acontecer no jovem, em razão de\nalterações displásicas do vaso, e no idoso em razão da aterosclerose.","options":{"A":"1,2 e 3 estão corretas.","B":"Todas estão corretas.","C":"1, 3 e 4 estão corretas.","D":"1 e 4 estão corretas.","E":"2 e 4 estão corretas."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-45111","number":"45111","sourceNumber":"45111","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A rabdomiólise é uma importante causa de insuficiência renal aguda. É INCORRETO\nafirmar:","options":{"A":"Pode ter causa infecciosa.","B":"A creatinofosfoquinase sérica está aumentada.","C":"A função renal é recuperada na maioria dos pacientes com tratamento adequado.","D":"O principal passo terapêutico é a alcalinização da urina."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-49058","number":"49058","sourceNumber":"49058","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 4 anos, branco, apresentando há 1 mês quadro de febrícula\nintermitente, cansaço, dor óssea e equimoses em\nmmii. Relata também alguns episódios de\nepistaxe e sangramento gengival no período. Ao exame encontra-se com palidez cutaneomucosa\nacentuada, desatento, eupneico em ar ambiente, ausculta cardíaca com sopro sistólico em foco\nmitral ++/6+ ritmo em 2 tempos, hepatoesplenomegalia, lesões equimóticas e petequiais\nprincipalmente em membros. Exames laboratoriais revelam hamatócrito 19%, hemoglobina 6,0 g/dl,\nreticulócitos 0,2%, leucócitos 100.000/mm³, plaquetas 15.000/mm³. TAP 90%, INR 1,2, PTT 35seg,\nrelação 1,0. Glicemia 75 mg/dl, Na 144 mEq/L, K6,0 mEq/L, Ca 8,5 mg/dl, P 7,0 mg/dl, Mg 1,5\n\nmEq/L, CI 106 mEq/L, U 60 mg/dl, Cr 1,2 mg/dl, LDH 900 U/L, AST 50 U/L, ALT 55 U/L, BT 1,0\n\nmg/dl. Em relação à principal hipótese diagnóstica, a complicação apresentada pelo paciente à\nadmissão é:","options":{"A":"Síndrome de ativação macrofágica.","B":"Síndrome hamofagocítica.","C":"Síndrome de lise tumoral.","D":"Síndrome hemoliticourêmica.","E":"Síndrome da hiperinfecção."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-51314","number":"51314","sourceNumber":"51314","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"É contraindicação relativa ao uso da tomografia computadorizada com meio de\ncontraste venoso, EXCETO nos pacientes:","options":{"A":"com creatinina acima de 1,5 mg/dl.","B":"que usaram metformina nas últimas 6h.","C":"portadores de mieloma múltiplo.","D":"em diálise."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-52090","number":"52090","sourceNumber":"52090","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A meia-vida do chumbo encontrada no sangue e nos tecidos moles é de,\nrespectivamente:","options":{"A":"Sangue: 05 a 10 dias e tecidos moles: 93 dias.","B":"Sangue: 35 a 60 dias e tecidos moles: 125 dias.","C":"Sangue: 28 a 36 dias e tecidos moles: 46 dias.","D":"Sangue: 07 a 21 dias e tecidos moles: 86 dias.","E":"Sangue: 45 a 70 dias e tecidos moles: 33 dias."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-51406","number":"51406","sourceNumber":"51406","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A mais comum causa de estenose da artéria renal é:","options":{"A":"aterosclerose.","B":"displasia fibromuscular.","C":"trombose.","D":"pós-trauma."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-36314","number":"36314","sourceNumber":"36314","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 58 anos, portadora de obesidade, e Hipertensão Arterial Sistêmica há\ncerca de 16 anos, relata que apesar do uso regular da medicação, vem apresentando níveis\npressóricos mais elevados, edema de membros inferiores,\n\nsendo necessários reajustes de sua medicação com aumento da dose de vasodilatadores e uso de\ndiurético. Realizou exames recentes, sendo informada por seu médico que havia comprometimento\nda função renal, classificada como\n\ndoença renal crônica em estágio 3. Esta paciente necessitou realizar exame com contraste\nendovenoso, sendo orientada por seu médico assistente a utilizar:","options":{"A":"N- acetilcisteína na dose de até 1,8 g por 3 dias, iniciando na véspera do exame e suspender o\nuso de diuréticos;","B":"Prednisona 1 a 2 mg/kg de peso na véspera e no dia do exame; aumentar a dose do diurético\npor 48h a partir do dia do exame;","C":"Anti-inflamatório não hormonal 48 horas antes do exame; iniciar uso de captopril 25 mg na\nvéspera do exame;","D":"Loratadina 10 mg /dia por 3 dias, iniciando na véspera do exame; bicarbonato de sódio\nintravenoso 24 horas após a realização do exame."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-37787","number":"37787","sourceNumber":"37787","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Pedro Paulo, 18 anos, negro, é trazido por familiares ao Pronto Atendimento do HE\ncom queixa de prostração, febre, dor\ngeneralizada, redução do débito urinário e urina avermelhada.\nNega doenças prévias. É usuário de cocaína. Mãe informa que no final de semana Pedro Paulo\ningeriu grande quantidade de bebida alcoólica e fez uso de cocaína. Ao exame, apresenta-se\nprostrado e referindo dor muscular. Corado, taquipneico, anictérico. PA ? 150/90 mmHg, TAx ?\n\n38,6ºC, FC ? 100 bpm, FR ? 26 irpm. RCR 2T. Pulmões limpos. Abdome doloroso à palpação, sem\nsinais de irritação peritoneal. Edema de membros inferiores +/4+. Baseando-se na provável\nhipótese diagnóstica para o caso descrito, que achado laboratorial não seria esperado?","options":{"A":"Hipercalemia.","B":"Redução da haptoglobina sérica.","C":"Hiperuricemia.","D":"Aumento de CPK e LDH.","E":"Hipocalcemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-22030","number":"22030","sourceNumber":"22030","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Evandro tem 48 anos e trabalha, desde os 20 anos, em oficina de ferro-velho com\natividade principal de desmanche de baterias\nde automóvel. Chega ao ambulatório com queixa de\ndor abdominal intensa e difusa. O exame de cavidade oral evidencia dentes em péssimo estado de\nconservação com halo azul acinzentado escuro no rebordo alveolar dos dentes. O abdome exibe\ncicatriz paramediana direita infraumbilical e cicatriz mediana xifopubiana decorrentes de duas\ncirurgias prévias realizadas, respectivamente, cinco e três anos antes em razão de sintomatologia\nsemelhante à atual. A palpação abdominal é compatível com abdome agudo. Evandro informa que\nteve o apêndice cecal retirado na primeira cirurgia. O diagnóstico mais provável de Evandro é:","options":{"A":"brida com torção e necrose de segmento intestinal.","B":"úlcera péptica perfurada e bloqueada.","C":"pancreatite adematosa.","D":"saturnismo."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-21772","number":"21772","sourceNumber":"21772","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 72 anos apresenta insuficiência renal aguda após realização de cateterismo\ncardíaco. Ao exame físico, apresenta\nredução dos pulsos periféricos, livedo reticular, epigastralgia e\nconfusão mental. Seus exames laboratoriais mostram ureia de 260 mg%, creatinina de 5,2 mg%,\nfósforo de 9,5 mEq/L. EAS mostra 10 a 15 leucócitos por campo, 5 a 10 hemácias por campo e 1\ncilindro hialino por campo. O diagnóstico mais provável para o paciente é:","options":{"A":"Embolia de colesterol.","B":"Necrose tubular aguda.","C":"Nefrite intersticial aguda.","D":"Dissecção da artéria renal."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26742","number":"26742","sourceNumber":"26742","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação à síndrome de lise tumoral podemos afirmar:","options":{"A":"É a principal emergência oncológica do tumor de Wilms.","B":"As principais manifestações clínicas são secundárias a hiperuricemia; hipercalemia e\nhiperfosfatemia.","C":"O tratamento de escolha é a restrição hídrica.","D":"Não há relato de ocorrência nos casos de leucemia e linfoma.","E":"A convulsão secundária à hiponatremia é a principal manifestação clínica."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-26729","number":"26729","sourceNumber":"26729","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Os órgãos mais afetados na intoxicação pelo cobre são:","options":{"A":"pulmão e SNC.","B":"SNC e fígado.","C":"ossos e fígado.","D":"pulmão e ossos.","E":"fígado e pulmão."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-6641","number":"6641","sourceNumber":"6641","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma angiografia renal foi realizada em paciente com aumento dos níveis tensionais e\nsopro sistodiastólico audível nos flancos. No exame, visualizaram-se estenoses e dilatações\n\npós-estenóticas em sequência no terço proximal das artérias renais, produzindo típico aspecto em\n\n?colar de contas?. Estudos estatísticos, englobando sexo e idade, assinalaram que a hipertensão\narterial secundária a essa vasculopatia predomina em:","options":{"A":"homens idosos.","B":"homens jovens.","C":"mulheres idosas.","D":"mulheres jovens."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-174962","number":"174962","sourceNumber":"174962","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 79 anos, com antecedentes de síndrome demencial e alteração do humor,\nem uso de trazodona e clonazepam, está\ninternada em uma unidade de cuidados intensivos no pós\n\n- operatório de correção de fratura do fêmur esquerdo. No centro cirúrgico, foi submetida à sedação\ne raquianestesia sem intercorrências. À admissão,\napresentava 9 pontos na escala de coma de\nGlasgow, sem sinais localizatórios, ritmo sinusal, pressão arterial 150/90 mmHg, pulso 98 bpm,\ncrepitacões em bases pulmonares, saturação de 94% em uso de máscara de venturi 40% e\ndesconforto respiratório com uso de musculatura acessória. Colhida gasometria arterial: Ph: 7,10;\nPCO2: 92; PAO2: 60; HCO3: 20; BE: - 6; SAT: 94%. Nesse momento, em relação ao quadro\napresentado, o manejo adequado dessa paciente deve ser:","options":{"A":"Iniciar inotrópico em infusão - dobutamina 5 mcg/kg/min.","B":"Iniciar a reposição de bicarbonato de sódio 8,4% - 100 ml endovenoso.","C":"Iniciar a ventilação mecânica não invasiva com bipap máscara facial.","D":"Iniciar a heparinização plena com heparina não fracionada."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-102927","number":"102927","sourceNumber":"102927","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma paciente de 50 anos de idade apresenta elevação de creatinina 3 dias após\nrealizar uma tomografia com contraste no\nestadiamento de tumor colorretal. A medida profilática\nmais eficaz para prevenir essa complicação é administrar:","options":{"A":"Furosemida.","B":"Hidratação vigorosa.","C":"Dopamina.","D":"Peptídio natriurético atrial."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-7085","number":"7085","sourceNumber":"7085","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Ao prescrever medicamentos para uma pessoa idosa, o médico deve estar atento para\no fato de que:","options":{"A":"o idoso, por ser portador de doenças crônicas e, por isso mesmo, fazer uso continuado de\nmedicamentos, torna-se naturalmente resistente a efeitos colaterais.","B":"as substâncias de primeira escolha para se diminuir a ansiedade no idoso são os barbitúricos.","C":"os anti-inflamatórios não hormonais podem provocar nela distúrbios na função renal e prejudicar\na excreção de outros medicamentos.","D":"o idoso acometido de quadros demenciais deve ser tratado, preferentemente, com\nbenzodiazepínicos."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-184421","number":"184421","sourceNumber":"184421","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual das medidas seguintes é eficaz para prevenir ou atenuar a insuficiência renal\naguda?","options":{"A":"dopamina em doses renais.","B":"infusão de soro fisiológico 0,9, previamente e após a infusão de contraste radiológico.","C":"diuréticos de alça por via endovenosa em altas doses.","D":"infusão de fator de crescimento semalhante à insulina."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-184446","number":"184446","sourceNumber":"184446","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Vítima de acidente automobilístico que ficou preso nas ferragens, internado no CTI há\n48 horas, em ventilação mecânica, evolui com\noligúria, aumento de escorias nitrogenadas\nCreatinina=3,2 mg/dl (na admissão era de 0,9 mg/dl) e creatinofosfoquinase (CPK= 840.000 U/L).\nApresenta potássio sérico K= 8,6 mEq/L e os seguintes achados no ECG. A causa mais provável\nda lesão renal aguda e a primeira medida terapêutica a ser dotada para controlar alterações no\nRCG são, respectivamente:","options":{"A":"sepse e furosemida.","B":"rabdomiólise e furosemida.","C":"rabdomiólise e gluconato de cálcio.","D":"desidratação e solução polarizante."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-294017","number":"294017","sourceNumber":"294017","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A anemia falciforme pode causar uma nefropatia com manifestações clínicas diversas.\nNa medula renal, que é relativamente hipoxêmica e\nhipertônica, a crise de falcização pode causar\numa necrose de papila, que se manifesta por:","options":{"A":"Hematúria macroscópica.","B":"Poliúria.","C":"Proteinúria.","D":"Acidose tubular renal."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-158634","number":"158634","sourceNumber":"158634","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Nefrite intersticial tem sido classificada clinicamente e histopatologicamente em formas\naguda e crônica, levando a graus variados\nde insuficiência renal. São causas de nefrite intersticial:\n\nI. Penicilina; II. Analgésicos; III. HIV; IV. Diabetes mellitus. Assinale:","options":{"A":"Se apenas I, II e III são corretas.","B":"Se apenas I e III são corretas.","C":"Se apenas II e IV são corretas.","D":"Se apenas IV é correta.","E":"Se todas são corretas."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-127386","number":"127386","sourceNumber":"127386","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A causa mais comum de doença tubulointersticial crônica é:","options":{"A":"Refluxo vesicoureteral.","B":"Uso de rifampicina.","C":"Obstrução prolongada do trato urinário.","D":"Uso de furosemida.","E":"Infecção por Corynebacterium diphtheriae."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-79858","number":"79858","sourceNumber":"79858","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na insuficiência renal aguda, a presença de eosinofilia no sangue periférico e a\nassociação com sedimento urinário contendo hematúria e leucocitúria (predomínio de eosinófilos)\npode sugerir:","options":{"A":"Nefrite intersticial aguda.","B":"Glomerulonefrite.","C":"Necrose tubular aguda isquêmica.","D":"Necrose tubular aguda tóxica.","E":"Síndrome hemolítico-urêmica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34287","number":"34287","sourceNumber":"34287","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, em prolongada imobilidade, apresenta insuficiência renal aguda com níveis\naumentados de Creatinina-Quinase (CK), presença de hemoglobina no ?dipstick? e ausência de\nhemácias na análise de urina. Esse quadro sugere como diagnóstico:","options":{"A":"Doença de Takayasu.","B":"Glomerulonefrite difusa aguda.","C":"Rabdomiólise.","D":"Hiperuricemia.","E":"Granulomatose de Wegener."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-33089","number":"33089","sourceNumber":"33089","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Não constitui fator de risco para falência renal no pós-operatório de cirurgia de grande\nporte:","options":{"A":"Hipovolemia.","B":"Insuficiência cardíaca congestiva.","C":"Hipertensão arterial sistêmica.","D":"Disfunção renal prévia.","E":"Cirrose com falência hepática (Child C)."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-33162","number":"33162","sourceNumber":"33162","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Associe as medidas terapêuticas propostas às respectivas substâncias tóxicas. 1 -\n\nN-acetilcisteína. 2 - Hemodiálise/hemoperfusão. 3 - Desferroxamina. 4 - Teofilina. 5 - Naloxona. ( )\nFerro. ( ) Acetaminofeno. ( ) Salicilatos. A sequência numérica correta, de cima para baixo, é:","options":{"A":"1 - 2 - 4.","B":"1 - 5 - 2.","C":"3 - 1 - 2.","D":"3 - 2 - 1.","E":"5 - 1 - 4."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-25972","number":"25972","sourceNumber":"25972","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Dentre os fármacos abaixo, qual NÃO está relacionado com rabdomiólise ou miopatia\ncrônica?","options":{"A":"Atorvastatina.","B":"Ciclosporina.","C":"Cefalexina.","D":"Lítio.","E":"AZT."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-351387","number":"351387","sourceNumber":"351387","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino com 70 anos, fumante com dislipidemia, hipertensão e aneurisma\nabdominal, é submetido a uma aortografia e desenvolve uma lesão renal aguda. No exame físico é\nobservado livedo reticular em membros inferiores e no exame qualitativo de urina apresenta\nhematúria e 1+ de albumina. Constata-se ainda, proteína C reativa elevada e eosinofilia transitória.\nSobre a abordagem da lesão renal aguda, marque a alternativa CORRETA:","options":{"A":"Administrar corticóide.","B":"Administrar antiadesivo plaquetário.","C":"Administrar anticoagulante.","D":"Não há tratamento específico para reverter a causa."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-229411","number":"229411","sourceNumber":"229411","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 34 anos, diagnóstico de epilepsia em uso regular de anticonvulsivantes, é\nlevado à emergência por familiares que\nrelatam ter presenciado crise convulsiva que durou,\naproximadamente, 35 minutos. Negam diagnóstico de outras doenças prévias. Exame físico na\nchegada demonstra: Escala de Glasgow 10, pressão arterial 110/60 mmHg, FC 90 bpm,\nextremidades aquecidas, pulsos preservados. Exames complementares evidenciam: creatinina de\n2,3 mg/dL, potássio de 5,9 mEq/L, sódio de 140 mEq/L, creatinoquinase (CK) de 5.200 UI/L, exame\ncomum de urina com mioglobina+++, 3 hemácias / campo, sem proteinúria significativa e ausência\nde cilindros. Passada sonda vesical de demora, presença de 50 mL de urina no momento do\nprocedimento e mais 50 mL ao final das seis primeiras horas em que permaneceu na emergência.\nEm relação ao caso clínico, assinale a alternativa correta.","options":{"A":"A lesão renal é de origem parenquimatosa, provavelmente associada à medicação em uso, e\ndeve ser manejada com hidratação com\nsolução salina 0.9% em bomba de infusão a 1 ml/Kg/hora.","B":"Não é possível fazer o diagnóstico de lesão renal aguda, uma vez que não há registro de\ndosagens prévias de creatinina sérica, relação\nproteína/creatinina em amostra de urina, e não foi\nrealizada ultrassonografia de rins e vias urinárias.","C":"A causa mais provável da perda de função renal é relacionada ao aumento de CK e mioglobina\natravés da liberação de espécies ativas de\noxigênio, levando à vasoconstrição intraparenquimatosa\ne ao dano tubular.","D":"A alcalinização da urina com bicarbonato de sódio profilaticamente está indicada, uma vez que a\nmioglobina é tóxica para as células tubulares, e a terapia renal substitutiva deve ser indicada."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-205310","number":"205310","sourceNumber":"205310","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Militar, 20 anos, chega à emergência após 12 horas de intenso treinamento em campo,\ncom queixas de dor e fraqueza proximal em\nmembros inferiores, associadas à oligúria. Referiu,\nainda, que o pouco de urina produzida tinha cor de ferrugem. Eletrocardiograma realizado\napresentou o traçado a seguir. Em relação ao caso clínico, afirmar-se: I. Ocorre acidose metabólica\ncom \"ânion-gap\" normal. II. A reposição hidrossalina vigorosa é um tratamento adequado. III.\nInfundir 10 ml de gluconato de cálcio 10% em 10-20 minutos juntamente com nebulização com beta\nagonista é a primeira conduta terapêutica. Está/Estão correta (s) apenas a (s) afirmativa (s):","options":{"A":"I.","B":"III.","C":"I e II.","D":"II e III."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-173991","number":"173991","sourceNumber":"173991","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 48 anos, com diabete melito em uso de hipoglicemiante oral há 2 anos, vem à\nemergência com febre (38,2°C) há 2 dias. Relata que utilizou amoxilina 500 mg de 8/8 h logo que\niniciou o quadro. Na revisão de sistemas, relata artralgias generalizadas. Creatinina 1,9 mg/dL;\npotássio 5,0 mEq/L; exame comum de urina com proteína 2+, 50 hemácias/campo e >50\nleucócitos/campo, relação proteinúria/creatininúria em amostra de 1,5 g/mg de\ncreatinina.Hemograma com 9.000 leucócitos/mm³ (250 bastonados, 750 eosinófilos e 2.000\nlinfócitos). Sobre o caso, é CORRETO afirmar que:","options":{"A":"A proteinúria pode ser atribuída ao diabete, o que leva ao diagnóstico de doença renal crônica\ncom piora aguda relacionada ao quadro infeccioso.","B":"A lesão renal é aguda, provavelmente ocasionada pelo quadro infeccioso, sem relação com a\ndoença de base.","C":"A causa mais provável para a perda de função renal é nefrite intersticial, sendo que o exame\ncomum de urina e o hemograma corroboram essa\nhipótese.","D":"A causa mais provável da perda de função renal é a necrose tubular aguda, ocasionada por\nquadro de sepse e uso de antibiótico associado à nefrite intersticial.","E":"O quadro de febre, a leucocitúria e as artralgias levam ao diagnóstico de lesão renal secundária\nà infecção de provável foco urinário."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-134160","number":"134160","sourceNumber":"134160","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Feminina 65 anos interna na emergência com quadro de insuficiência renal aguda,\nredução do sensório e insuficiência\nrespiratória aguda necessitando suporte ventilatório\ninvasivo. Paciente havia realizado primeiro ciclo de quimioterapia há 1 semana. Qual destas\nhipóteses diagnósticas possui menor associação com a provável síndrome apresentada pela\npaciente:","options":{"A":"Linfoma não-Hodgkin difuso de grandes células","B":"Doença de Hodgkin","C":"Câncer de mama","D":"Leucemia mielóide aguda","E":"Câncer de pulmão de pequenas células"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-107263","number":"107263","sourceNumber":"107263","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma paciente de 72 anos interna através da emergência com quadro de insuficiência\nrenal aguda, redução do sensório e\ninsuficiência respiratória aguda necessitando suporte\nventilatório invasivo na emergência. Revisando o histórico com familiares, o paciente tinha\nrealizado\nprimeiro ciclo de quimioterapia há 1 semana. Qual destas hipóteses diagnósticas possui menor\nassociação com síndrome de lise tumoral?","options":{"A":"Linfoma não-Hodgkin difuso de grandes células.","B":"Doença de Hodgkin.","C":"Câncer de mama tipo HER2 positivo.","D":"Leucemia mieloide aguda.","E":"Câncer de pulmão de pequenas células."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-85717","number":"85717","sourceNumber":"85717","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual afirmativa é falsa?","options":{"A":"O termo HAS renovascular refere-se ao aumento na pressão arterial induzida pela perfusão\nrenal reduzida.","B":"Stent aórtico endovascular pode ocasionar HAS renovascular por oclusão vascular.","C":"Vasculite de Takayasu é causa de HAS renovascular.","D":"Uma perfusão renal aumentada é causa de HAS renovascular.","E":"Ao tentar diminuir a pressão arterial no paciente com HAS renovascular crítica poderá ocorrer\nliberação de renina com ativação sistêmica renina angiotensina."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-87035","number":"87035","sourceNumber":"87035","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente feminina com 77 anos de idade, hipertensa em tratamento, vinha em\nacompanhamento ambulatorial com creatinina\nplasmática estável em torno de 1,5 mg/dl nos últimos\n12 meses. Há poucas semanas, foi modificado o esquema anti-hipertensivo com a inclusão de\nenalapril na dose de 20 mg/dia. Agora ela vem consultar com queixas de tonturas quando em\nortostatismo, principalmente ao levantar da cama pela manhã, e traz novos exames que revelam\numa creatinina plasmática de 2,4 mg/dl. Ao exame físico, não apresenta edema, a ausculta\npulmonar é normal, a pressão arterial é 90 x 70 mmHg e a frequência cardíaca é 90 bpm.\n\nConsidere as frases abaixo a respeito deste caso e escolha aquela que apresenta-se correta:","options":{"A":"A piora da função renal é importante e indica a necessidade de investigar a possibilidade de\nhipertensão secundária.","B":"A paciente desenvolveu um quadro de insuficiência cardíaca e, por baixo débito cardíaco, a\nfunção renal deteriorou-se.","C":"A função renal piorou como consequência de uma baixa perfusão renal devido ao efeito\nexcessivo do enalapril sobre a pressão\narterial e sobre o mecanismo hemodinâmico de controle da\npressão de filtração glomerular.","D":"A inibição da enzima de conversão da angiotensina provocou uma vasodilatação da arteríola\naferente, o que causou modificação no fluxo\ne na pressão do sangue dentro do capilar glomerular\npiorando a taxa de filtração glomerular."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-80307","number":"80307","sourceNumber":"80307","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"H.V.M., 70 anos, feminina, diabética e hipertensa, hospitalizada por herpes-zóster\noftálmico, em tratamento com aciclovir\nendovenoso há cinco dias. Apresenta, no momento, lesão\nrenal aguda, com Cr = 5,5 mg/dl (Cr basal = 0,8 mg/dl), K+ = 5,3 mEq/L, Ur = 200 mg/dl, gasometria\ncom pH = 7,33, pCO2 = 24 mmHg, pO2= 70 mmHg, SatHb = 93%, HCO3 = 12 mEq. EQU: d =\n\n1015, Hem. = 8, Leuc. = 10, Prot.+, Prot./Creat. (urina) = 0,4; Na+ urinário = 20 mEq, C3 e C4\nnormais. Afebril, queixava-se de dor em\nflanco esquerdo ao exame. Diurese de 300 ml nas últimas\n12 horas. Ecografia do aparelho urinário sem alterações dignas de nota. Ao exame, corada,\nmucosas pouco secas, Glasgow = 15. ACV:RR2t BNF, sem sopros; PA = 100 x 60 mmHg. AP =\npulmões limpos; Abdome inocente; Boa perfusão periférica. Qual o diagnóstico mais provável e o\nseu tratamento imediato?","options":{"A":"Lesão pré-renal; reposição volêmica.","B":"Lesão renal aguda induzida por cristais; reposição volêmica e interromper aciclovir.","C":"Nefrite intersticial aguda; terapia dialítica e interromper aciclovir.","D":"Glomerulopatia aguda pós-infecciosa; tratamento de suporte.","E":"Necrose tubular aguda por nefrotoxicidade; terapia dialítica e interromper aciclovir."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-79175","number":"79175","sourceNumber":"79175","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Entre os fármacos abaixo listados, qual NÃO induz nefrite túbulo-intersticial aguda?","options":{"A":"Rifampicina.","B":"Tiazidas.","C":"Prednisona.","D":"Omeprazol.","E":"Sulfatrimetroprim-Metoxazol."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-65192","number":"65192","sourceNumber":"65192","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A maior parte da glicose que é filtrada no glomérulo é reabsorvida no:","options":{"A":"Túbulo proximal.","B":"Ramo descendente da alça de Henle.","C":"Ramo ascendente da alça de Henle.","D":"Túbulo distal.","E":"Ducto coletor."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-60002","number":"60002","sourceNumber":"60002","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 85 anos, após iniciar quimioterapia para mieloma múltiplo, refere diminuição\ndo volume urinário, permanecendo com PA normal.\nCreatinina passa de 1,2 mg/dl para 2,3 mg/dl;\necografia: rins de dimensões normais, cortical preservada, sem litíase ou dilatação das vias\nurinárias. Sobre este quadro, são apresentadas as seguintes assertivas: I. A causa provável da\nperda da função renal está relacionada ao uso do quimioterápico. II. Os distúrbios eletrolíticos a\nserem tratados\n\npara recuperar a função renal são hipercalcemia e hiperuricemia. III. O manejo fundamental deste\ncaso é alcalinizar a urina a fim de tratar\no depósito de ácido úrico e de cálcio intrarrenal. Qual é a\nalternativa CORRETA?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas II e III.","E":"I, II e III."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-33520","number":"33520","sourceNumber":"33520","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente feminina, branca, 63 anos, 60 kg, hipertensão arterial estágio 1 com\ndiagnóstico há 8 anos, sem outras\ncomorbidades, submetida à laminectomia por hérnia de disco,\napresentou, como complicação em Pós-Operatório (PO), extensa lesão muscular, provavelmente\nem função da imobilização prolongada. No terceiro PO, passou a apresentar urina escura, diurese\nde 200 ml em 24h; dipstick positivo para hemoglobina; CPK total = 15840 U/L; creatinina = 3,5\nmg/dl; pH urinário = 7,0; potássio plasmático = 7,1 mEq/L e ECG normal. O adequado manejo\ndessa paciente deve incluir:","options":{"A":"Reposição volêmica com bicarbonato de sódio em solução isotônica, monitoração de magnésio\nplasmático e glicoinsulina.","B":"Reposição volêmica com solução de cloreto de sódio 0,9%, monitoração de cálcio plasmático e\nPVC, hemodiálise.","C":"Reposição volêmica com solução de albumina 20%, furosemida e gluconato de cálcio\nendovenosos.","D":"Restrição de infusão de volume, concentrar diluições de medicamentos, furosemida endovenoso\nem altas doses.","E":"Restrição de infusão de volume, gluconato de cálcio endovenoso, hemodiálise."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-33529","number":"33529","sourceNumber":"33529","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 69 anos, portador de diabetes tipo 2 há 12 anos e hipertensão\narterial há 15 anos, sofre infarto agudo do\nmiocárdio anterior extenso, apresentando angina\n\npós-infarto. É solicitada angiografia coronariana. Está indicado para a profilaxia da nefropatia por\ncontraste:","options":{"A":"Hidratação endovenosa, contendo NaHCO3, N-acetilcisteína em altas doses, minimizar dose e\nosmolaridade do meio de contraste.","B":"Expansão volêmica com coloide, furosemida endovenoso, minimizar dose e osmolaridade do\nmeio de contraste.","C":"Suspensão da angiografia coronariana, que está formalmente contraindicada pelo risco de\nnefrotoxicidade do contraste.","D":"Hidratação endovenosa com solução fisiológica, infusão de dopamina e dose mínima de\ncontraste.","E":"Furosemida endovenosa e N-acetilcisteína em altas doses."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-33533","number":"33533","sourceNumber":"33533","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, 70 anos, portador de doença renovascular bilateral por\naterosclerose, com estenose estimada em 60%\nda artéria renal direita e 80% da artéria renal\nesquerda por Doppler, pressão arterial adequadamente controlada com uso de medicamentos\nanti-hipertensivos, inclusive ramipril, e depuração da creatinina endógena de 80 ml/min/1,73 m²,\nestável no último ano. Considerando a melhor evidência científica disponível, o manejo desse\npaciente deve incluir:","options":{"A":"Angioplastia percutânea com stent bilateral.","B":"Revascularização cirúrgica da artéria renal esquerda.","C":"Manter tratamento clínico, mas suspender inibidor da ECA.","D":"Manter tratamento clínico incluindo inibidor da ECA ou bloqueador do receptor da angiotensina.","E":"A sua submissão à angiografia percutânea das artérias renais (padrão-ouro), antes de definir o\nmanejo subsequente."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-37713","number":"37713","sourceNumber":"37713","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Sobre Insuficiência Renal Aguda (IRA), considere as assertivas a seguir:\n\n(I) Sulfonamidas podem causar IRA tanto por dano tubular (necrose tubular aguda) como por\nreação do tipo alérgico (nefrite intersticial aguda).\n\n(II) Tanto cocaína como inibidores de redutase da coenzima-A podem causar IRA através de\nnefrotoxicidade tubular pelo pigmento heme através de rabdomiólise.\n\n(III) A mortalidade na IRA pré-renal costuma ser inferior a 10%, enquanto que naqueles com IRA\nintrarrenal a mortalidade pode chegar a 80%.\n\n(IV) Estudos recentes demonstram que, dentre as diversas variáveis clínicas que aumentam o risco\nde IRA, o de maior valor preditivo é a presença prévia de algum grau de insuficiência renal\ncrônica.\n\n(V) Em pacientes com IRA pré-renal que não tenham utilizado diurético, a fração de excreção de\nsódio tipicamente será > 1%.\n\nDentre as assertivas acima, estão corretas:","options":{"A":"II, III e IV.","B":"I, IV e V.","C":"I, II e III.","D":"III, IV e V."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-35924","number":"35924","sourceNumber":"35924","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação à nefrotoxicidade dos antibióticos, são apresentadas as seguintes\nassertivas: I. As penicilinas estão associadas a\nquadros de síndrome nefrítica aguda. II. As\ncefalosporinas são causas conhecidas de síndrome nefrótica. III. As tetraciclinas podem causar\nsíndrome de Fanconi. Qual é a alternativa correta?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-23652","number":"23652","sourceNumber":"23652","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 27 anos, é trazido à Emergência por agitação psicomotora, agressividade e\nalucinações auditivas e visuais. Queixa-se de fraqueza muscular difusa. Ao exame, TAX 38ºC, FC\n120 bpm, PA 150/100 mmHg. A urina apresenta coloração de chá escuro. EQU revela proteinúria\nsem hematúria. A pesquisa de cocaína na urina é positiva. Qual o provável diagnóstico clínico?","options":{"A":"Rabdomiólise.","B":"Nefropatia por IgA.","C":"Delirium tremens.","D":"Leptospirose.","E":"Encefalopatia hepática."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-28193","number":"28193","sourceNumber":"28193","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, HIV positivo, usuário de drogas endovenosas, é internado com\nquadro de dispneia crescente. No exame\nfísico apresenta PA = 120/70 mmHg e ausculta pulmonar\ncom raros sibilos. O RX de tórax apresenta infiltrado bilateral, ureia de 42 mg/dl, creatinina de\n1,3\nmg/dl, sódio plasmático de 131 mEq/l, potássio de 4,8 mg/dl e bicarbonato plasmático de 22 mEq/l.\nO restante da investigação levou ao diagnóstico de pneumonia por Pneumocystis jirovecii e foi\niniciado sulfametoxazol/trimetoprim parenteral. Após uma semana de internação, os exames\nlaboratoriais mostravam: ureia de 53 mg/dl, creatinina de 1,8 mg/dl, sódio plasmático de 130 mEq/l,\npotássio de 6,2 mg/dl e bicarbonato plasmático de 24 mEq/l. Qual das seguintes situações é a\nmais provável causa do aumento do potássio plasmático?","options":{"A":"Destruição do tecido pulmonar devido à pneumocistose.","B":"Excreção de potássio diminuída devido à função renal deteriorada.","C":"Nefrite intersticial devido ao sulfametoxazol.","D":"Bloqueio da excreção de potássio no túbulo distal devido ao trimetoprim.","E":"Doença de Addison devido à infecção adrenal pelo HIV."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-108914","number":"108914","sourceNumber":"108914","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente com queixa de tosse, principalmente no período noturno, associada a cefaleia\ne obstrução nasal, procurou assistência médica\ne obteve o diagnóstico de sinusopatia. Foi prescrito\namoxicilina e liberada. Após cerca de quatro dias, retornou ao pronto atendimento com queixa de\nrash cutâneo, náuseas e vômitos. Ao exame, apresentou rash cutâneo em tórax e abdome,\npruriginoso, e se encontrava afebril, com pressão arterial de 120 x 80 mmHg; frequência cardíaca =\n86 bpm; e o restante do exame normal. Nos exames de entrada, apresentou hemoglobina = 13 g/dl;\nhematócrito = 39%; leucócitos = 10.000/mm³ sem bastão; 59% segmentados; 15% eosinófilos;\nplaquetas = 220.000 /mm³; ureia = 110 mg/dl; creatinina = 2,2 mg/dl; Na = 140 mEq/L; K = 4,5\nmEq/L; exame de urina = pH 5,5; densidade = 1.020; traços de proteína; hemácias = 7 p/c;\nleucócitos = 10 p/c e cilindros leucocitários. Nesse caso, o diagnóstico mais provável é:","options":{"A":"Pielonefrite aguda.","B":"Glomerulonefrite pós-infecciosa.","C":"Nefrite intersticial aguda.","D":"Nefropatia por lesão mínima.","E":"Necrose tubular aguda."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-89437","number":"89437","sourceNumber":"89437","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O Sistema Renina-Angiotensina-Aldosterona (SRAA):","options":{"A":"Está envolvido na patogênese da hipertensão arterial tanto pelas suas ações pressoras diretas\nquanto pelos efeitos promotores de hipertrofia.","B":"É inibido quando a ingesta de sódio é reduzida, o que leva ao aumento da renina e da\nangiotensina II e estimula a secreção de\naldosterona com consequente aumento da retenção renal\nde sódio e água.","C":"É inibido tanto pelos betabloqueadores quanto pelos inibidores da enzima conversora de\nangiotensina e pelos diuréticos.","D":"Todas as alternativas estão corretas.","E":"Deve ser estimulado na fase aguda do pós-infarto para manter a estabilidade hemodinâmica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84607","number":"84607","sourceNumber":"84607","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 25 anos de idade é trazido de ambulância após atendimento\n\npré-hospitalar de emergência em uma festa no 3º dia de carnaval. Ao exame: pulso = 140 bpm; FR\n\n= 32 bpm; PA = 180 x 120 mmHg; e temperatura = 39°C. Oximetria na ambulância entre 90 e 95%.\nAlém de uma convulsão tratada com diazepam, tinha pupilas dilatadas, sudorese e odor alcoólico.\nUm amigo que o acompanhava, relata que ele estava há 3 dias em Salvador \"brincando o\ncarnaval\". No pronto atendimento, os exames revelaram pH = 7,25; K = 2,7 mEq/L; creatinina = 3;\nureia = 220; PaCO2 = 40; HCO3 = 18; Na 125; cloro = 89; PO2 = 85 e CPK = 100.000 U. Frente ao\n\nquadro, o paciente recebeu fluidos, bicarbonato e melhorou acentuadamente. Metabólitos de\ncocaína negativa. Posteriormente, admitiu ter\nusado uma droga. O quadro ácido-básico,\nrabdomiólise, mioglobulinúria, desidratação, hipertensão e hipertermia sugerem que esse paciente\nusou:","options":{"A":"Ketamina.","B":"Inalantes voláteis (\"lança perfume\").","C":"MDMA (\"êxtase\").","D":"Anfetamina","E":"Tetraidrocanabiol."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-67599","number":"67599","sourceNumber":"67599","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual dos achados abaixo favorece o diagnóstico de nefrite intersticial aguda em\npaciente em investigação de oligúria?","options":{"A":"Rins de tamanho diminuído.","B":"Eosinofilúria.","C":"Proteinúria nefrótica.","D":"Creatinina normal.","E":"Hematúria macroscópica."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-36553","number":"36553","sourceNumber":"36553","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Podemos observar acidose metabólica na (o):","options":{"A":"Hipertensão arterial.","B":"Rabdomiólise.","C":"DPOC.","D":"Hipocalemia.","E":"Nenhuma das anteriores."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-345858","number":"345858","sourceNumber":"345858","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O paciente hipertenso que tem elevação acentuada dos níveis de creatinina após início\ndo uso de inibidores da enzima conversora\nda angiotensina provavelmente é portador de:","options":{"A":"Coarctação de aorta.","B":"Doença renal crônica.","C":"Doença renovascular.","D":"Feocromocitoma.","E":"Síndrome de Cushing."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-84279","number":"84279","sourceNumber":"84279","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na avaliação da urina, qual o melhor indicador de necrose tubular aguda?","options":{"A":"Volume urinário menor que 400 ml/m².","B":"Hematúria.","C":"Índice proteína - creatinina urinário > 3.","D":"Presença de cilindros granulosos grosseiramente pigmentados."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-89475","number":"89475","sourceNumber":"89475","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Chamado para avaliar um paciente na UTI com insuficiência renal após bypass\ncardiopulmonar durante cirurgia para troca de\nvalva mitral, você desconfia de êmbolo de colesterol.\nQual o resultado que você espera encontrar no EPU?","options":{"A":"Cristais de oxalato de cálcio.","B":"Cilindros granulosos.","C":"Eosinofilúria.","D":"Cilindros leucocitários.","E":"EPU normal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-68832","number":"68832","sourceNumber":"68832","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com relação aos diuréticos é correto afirmar:","options":{"A":"Tiazídicos e diuréticos de alça tem efeitos semelhantes na excreção urinária de cálcio.","B":"A hipocalemia é a principal complicação do uso da espironolactona.","C":"A alcalose metabólica hipoclorêmica pode ser causada pelos diuréticos de alça.","D":"A hidroclorotiazida age no túbulo contornado proximal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-35952","number":"35952","sourceNumber":"35952","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São causas de hipercalcemia, exceto:","options":{"A":"Doenças granulomatosas;","B":"Rabdomiólise;","C":"Uso de tiazídico;","D":"Neoplasias;","E":"Feocromocitoma."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-32724","number":"32724","sourceNumber":"32724","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação às intoxicações exógenas e seus antídotos, correlacione os antídotos com\na intoxicação exógena correspondente.\n1.Flumazenil. 2.N-acetilcisteína. 3.Glucagon. 4.Cálcio.\n\n5.EDTA. ( ) Chumbo. ( ) Paracetamol. ( ) Propanolol. ( ) Hipermagnesemia. ( ) Diazepam. Assinale a\nalternativa que apresenta a numeração correta da coluna da direita, de cima para baixo.","options":{"A":"4 - 2 - 1 - 3 - 5.","B":"5 - 2 - 4 - 1 - 3.","C":"5 - 2 - 3 - 4 - 1.","D":"3 - 2 - 1 - 5 - 4.","E":"1 - 3 - 2 - 5 - 4."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-275462","number":"275462","sourceNumber":"275462","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente em uso recente de anti-inflamatórios não hormonais por cefaleia, evolui com\nfebre, artralgia disseminada, rash cutâneo, eosinofilia e cilindros leucocitários na urina. O\ndiagnóstico mais provável é:","options":{"A":"Pielonefrite aguda.","B":"Púrpura trombocitopênica trombótica.","C":"Síndrome hemolítico-urêmica.","D":"Endocardite infecciosa.","E":"Nefrite intersticial alérgica."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-210829","number":"210829","sourceNumber":"210829","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Exame considerado como padrão-ouro no diagnóstico da hipertensão renovascular:","options":{"A":"Ressonância nuclear magnética.","B":"Atividade de renina nas veias renais.","C":"Arteriografia.","D":"Cintilografia renal com captopril.","E":"Duplex-scan."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-177825","number":"177825","sourceNumber":"177825","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente feminina, 75 anos de idade, com história pregressa de hipertensão arterial\nsistêmica, há sete dias apresentando dor abdominal, náuseas, vômitos e diarreia profusa.\n\nFamiliares relatam recusa alimentar e redução significativa do volume urinário. Faz uso de captopril\ne nimesulida devido à dor lombar crônica. Ao\nexame físico, encontra-se sonolenta e desidratada;\nFC = 120 bpm; PA = 100 x 60 mmHg. O abdome é difusamente doloroso à palpação, mas não há\nsinais de irritação peritoneal. Os exames laboratoriais são: creatina = 2,0 mg/dl; ureia = 120\nmg/dl;\nsódio sérico = 138 mg/dl; potássio sérico = 3,5 mg/dl; sódio urinário = 10 mEq/L; creatinina\nurinária\n\n= 70 mEq/L; osmolalidade urinária = 720 mEq/L; parcial de urina sem alterações. No caso relatado,\na causa da insuficiência renal é:","options":{"A":"Insuficiência renal pré-renal.","B":"Necrose tubular aguda.","C":"Nefrite intersticial aguda pelo uso de AINH.","D":"Glomerulonefrite pós-infecciosa.","E":"Rabdomiólise."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-152752","number":"152752","sourceNumber":"152752","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 26 anos, procurou atendimento devido a mialgia, fraqueza muscular e urina\nescurecida. Participou de corrida de 42 km há três dias. Nega comorbidades, uso de medicações\nou drogas ilícitas. Exame físico: bom estado geral, corado, desidratado +/4, sem alterações\nrespiratórias ou abdominais; PA: 150 x 100 mmHg; dor à palpação de membros inferiores. Qual é a\nalteração laboratorial esperada?","options":{"A":"Hipomagnesemia.","B":"Hipocalcemia.","C":"Hipofosfatemia.","D":"Hipocalemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-150412","number":"150412","sourceNumber":"150412","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher, 32a, previamente hígida, internada há 9 dias para tratamento de pneumonia em\nuso de ceftriaxona e azitromicina\nintravenosos. Há 48 horas apresenta diminuição da diurese e\nvermelhidão pelo corpo. Exame físico: PA = 136 x 90 mmHg; FC = 82 bpm; T = 37,5°C; presença\nde exantema maculopapular discreto e difuso. Exames laboratoriais: Hb = 11,5 g/dl; Ht = 35%;\nleucócitos = 10.800/mm³; (56% segmentados, 23% linfócitos, 21% eosinófilos), plaquetas =\n180.000/mm³; Na = 137 mEq/L; K = 4,2 mEq/L; Ca = 9,8 mg/dl. Creatinina = 2,5 mg/dl e ureia = 100\nmg/dl. Urina: densidade = 1015; pH = 5.5; proteína negativa; leucócitos = 20.000/mm³; hemácias =\n5.000/mm³; eosinófilos presentes. O diagnóstico é:","options":{"A":"Nefrite tubulointersticial aguda.","B":"Infecção do trato urinário.","C":"Necrose tubular aguda.","D":"Glomerulonefrite difusa aguda."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-150426","number":"150426","sourceNumber":"150426","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 64a, descontinuou acompanhamento em unidade básica de saúde. Exame\nfísico: PA = 160 x 110 mmHg; FC = 88 bpm;\nFR = 16 irpm; oximetria de pulso (ar ambiente) = 96%;\nIMC = 32 kg/m². Pulmões: murmúrio vesicular presente e simétrico; estertores crepitantes em bases\ne campos médios. Extremidades: edema em membros inferiores +++/4+; diminuição do pulso\npedioso à direita. Neurológico: diminuição da sensibilidade vibratória em pés. Exames laboratoriais\nrealizados para essa consulta: Hb = 14,3 g/dl; Ht = 43%; Na = 141 mEq/L; K = 4,1 mEq/L; glicemia\nde jejum = 187 mg/dl; HbA1c = 7,8%; colesterol total = 256 mg/dl; HDL = 24 mg/dl; LDL = 190\nmg/dl; triglicérides = 230 mg/dl; ureia = 56 mg/dl; creatinina = 1,0 mg/dl; AST = 17 U/dl; ALT = 21\nU/dl. Inicia tratamento com metformina, furosemida, captopril, atenolol, sinvastatina. Após 10 dias\nde tratamento, colheu exames com os seguintes resultados: ureia = 105 mg/dl; creatinina = 1,87\nmg/dl; ALT = 41 mg/dl; AST = 37 mg/dl; CK = 250 mg/dl. O diagnóstico e a conduta são:","options":{"A":"Glomeruloesclerose; suspender a metformina.","B":"Rabdomiólise; suspender sinvastatina.","C":"Estenose de artérias renais; suspender o captopril.","D":"Necrose tubular aguda; suspender a furosemida."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-343871","number":"343871","sourceNumber":"343871","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 38 anos, portador de prolapso da válvula mitral, é admitido com febre e\nqueda do estado geral. Há crescimento de\nStaphylococcus aureus em três hemoculturas\nsucessivas e ele está em tratamento com oxacilina e gentamicina. No sétimo dia de tratamento,\napresenta-se hemodinamicamente estável, mas sua creatinina aumenta de 0,9 mg/dl (admissional)\npara 1,5 mg/dl, e o exame de urina I demonstra hematúria 2+ e proteinúria 2+; com cilindros\ngranulares e piócitos. Dosados C3 e C4 que se apresentaram normais. Apresenta eosinofilia e\neosinofilúria. O quadro deve ser devido a:","options":{"A":"Glomerulonefrite pós-infeciosa.","B":"Nefrite intersticial aguda.","C":"Necrose tubular aguda por isquemia.","D":"Sepse.","E":"Trombose de veia renal."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-345195","number":"345195","sourceNumber":"345195","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual é a alteração laboratorial esperada em um quadro de rabdomiólise, entre as\ncitadas abaixo?","options":{"A":"Hipocalemia.","B":"Hiponatremia.","C":"Hipocalcemia.","D":"Hipofosfatemia.","E":"Hipomagnesemia."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-304896","number":"304896","sourceNumber":"304896","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um paciente de 35 anos de idade vem perdendo a função renal progressivamente nos\núltimos dois meses. Quando foi consultar o médico nefrologista, elucidou como hipótese Nefrite\nIntersticial Aguda (NIA). A respeito de NIA, assinale a alternativa CORRETA.","options":{"A":"Rifampicina é o principal fármaco associado à NIA.","B":"Pacientes que apresentam vírus da imunodeficiência humana (HIV) são naturalmente protegidos\ncontra NIA.","C":"A presença de anticorpos anti-Tubular Basement Membrane (anti-TBM) é comum na presença\nde NIA.","D":"Há associação de NIA com uveíte.","E":"Infecções são a causa mais prevalente de NIA."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-312596","number":"312596","sourceNumber":"312596","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 73 anos, vem ao pronto-socorro com queixa de redução do volume urinário,\nedema em membros inferiores e escurecimento da coloração da urina há 1 dia. Nega traumas.\n\nRefere antecedentes de dislipidemia e hipertensão, em uso atual de sinvastatina, fenofibrato e\nhidroclorotiazida. Ao exame físico, apresenta edema até o terço proximal da perna ++/++++\nbilateralmente. O exame laboratorial mais indicado para esclarecimento diagnóstico neste momento\né:","options":{"A":"Bilirrubina.","B":"BNP.","C":"CPK.","D":"CK-MB.","E":"Proteinúria."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-303170","number":"303170","sourceNumber":"303170","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente feminina de 18 anos, apresentando transtorno alimentar e em uso de\nmedicações para emagrecer, é admitida na\nemergência com queixa de fraqueza e dificuldade de\ndeambular há 1 dia. Ao exame físico, seus sinais vitais eram normais, e chamava a atenção a\npresença de força muscular grau 3 bilateralmente em membros inferiores, com reflexos diminuídos.\nEm relação ao caso clínico, assinale a alternativa CORRETA:","options":{"A":"A sibutramina tem ação no túbulo distal bloqueando o transportador sódio-cloro.","B":"Os análogos de GLP-1 podem ser os causadores dos achados clínicos da paciente.","C":"A furosemida, por bloquear o canal de sódio-potássio-2 cloros, pode ser uma causa dos achados\nclínicos da paciente.","D":"A hidroclorotiazida, por bloquear o transportador sódio-potássio no túbulo distal, pode ser uma\ncausa dos achados clínicos da paciente."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-237237","number":"237237","sourceNumber":"237237","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"As tubulopatias hereditárias geralmente são doenças graves, que podem levar à\ndoença renal crônica terminal ou até mesmo à\nmorte. Sobre elas, assinale a opção CORRETA:","options":{"A":"A acidose tubular renal proximal (tipo II) é causada por um defeito na reabsorção de H+ no\ntúbulo proximal, levando a um quadro de alcalose metabólica.","B":"A síndrome de Bartter acomete o túbulo distal, cursando com hipocalemia hiporreninêmica,\nalcalose metabólica e pressão arterial normal ou baixa.","C":"A síndrome de Gitelman acomete o túbulo distal, sendo caracterizada por alcalose metabólica,\nhipocalemia, hipomagnesemia e hipocalciúria.","D":"A síndrome de Liddle caracteriza-se por hipertensão grave, acidose metabólica, hipocalemia e\nbaixas concentrações plasmáticas de renina e aldosterona.","E":"Crianças com diabetes insipidus nefrogênico cursam com polidipsia, poliúria, desidratação,\nisostenúria, hipernatremia e deficit de crescimento."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-159769","number":"159769","sourceNumber":"159769","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Você atende Recém-Nascido (RN) do sexo masculino, prematuro, 32 semanas de\nidade gestacional, devido a polidrâmnio que não\nrespondeu à amniocentese. Ele nasceu bem, não\nnecessitou de suporte respiratório. Hoje, ele está com 4 dias de vida; o exame físico é normal, bem\ncomo sua pressão arterial. Sua diurese é > 10 ml/kg/h e ele perdeu mais de 20% do seu peso de\nnascimento. Exames laboratoriais evidenciam hiponatremia, hipocalemia e hipercalciúria. Qual o\ndiagnóstico mais provável?","options":{"A":"Síndrome da secreção inapropriada de hormônio antidiurético.","B":"Diabetes insipidus nefrogênico.","C":"Síndrome de Bartter.","D":"Deficiência de mineralocorticoide."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-350468","number":"350468","sourceNumber":"350468","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 70 anos, tabagista e hipertenso crônico está em tratamento com anlodipino.\n\nHá 6 meses o controle da pressão arterial ficou difícil mesmo com acréscimo de outros\n\nanti-hipertensivos. PA: 160 x 100 mmHg, ureia: 42 mg/dL e creatinina: 1,1 mg/dL. Entre as opções\nabaixo, o exame que tem maior probabilidade de indicar o motivo da piora da hipertensão arterial é","options":{"A":"ecodopplecardiograma transesofágico.","B":"dosagem de metanefrinas urinárias.","C":"tomografia computadorizada de tórax.","D":"ultrassonografia com doppler de artérias renais."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-246870","number":"246870","sourceNumber":"246870","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual é a causa mais frequente de nefrite intersticial aguda?","options":{"A":"Infecciosa.","B":"Doença sistêmica.","C":"Medicamentosa.","D":"Idiopática."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-210737","number":"210737","sourceNumber":"210737","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A cintilografia com Gálio é recurso propedêutico indicado na investigação de:","options":{"A":"Nefrites rapidamente progressivas.","B":"Nefrite intersticial aguda.","C":"Doença policística.","D":"Nefropatia de lesões mínimas.","E":"Nefropatia por contraste iodado."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-176365","number":"176365","sourceNumber":"176365","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 78 anos, hipertenso, diabético tipo 2 e tabagista, em uso de furosemida 40\nmg/dia, metformina 1.000 mg/dia, AAS 100 mg/dia e losartana 100 mg/dia. Foi submetido a\ncateterismo e angioplastia devido à angina instável de alto risco com lesão significativa em\ndescendente anterior. Manteve-se assintomático, estável hemodinamicamente, euvolêmico, com\ndiurese satisfatória, sem sinais de infecção. Apresentou piora da função renal: creatinina basal e\nda\nadmissão: 0,8 mg/dl; após 72h do procedimento: 1,2 mg/dl. O provável diagnóstico e as medidas\nque poderiam ter sido feitas para evitá-lo são, respectivamente:","options":{"A":"Nefropatia induzida por contraste; suspender drogas nefrotóxicas antes do procedimento,\nrealizar hidratação endovenosa pré e\npós-procedimento e usar contraste isosmolar (ou hiposmolar)\nem menor volume.","B":"Nefropatia induzida por contraste; suspender drogas nefrotóxicas antes do procedimento,\nrealizar hidratação endovenosa pré e pós-procedimento,\nadministrar acetilcisteína e estatina.","C":"Doença renal ateroembólica; suspender drogas nefrotóxicas antes do procedimento, realizar\nhidratação endovenosa pré e pós-procedimento.","D":"Doença renal ateroembólica; nada poderia ser feito para prevenção dessa patologia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-132143","number":"132143","sourceNumber":"132143","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 55 anos, com antecedente de hipertensão arterial e diabetes mellitus, é\ninternado em unidade coronariana com\ndiagnóstico de angina instável de alto risco, sendo\nsolicitado cateterismo cardíaco. Exame físico: bom estado geral, corado, hidratado, eupneico, sem\nedemas. FC = 85 bpm; PA = 130 x 80 mmHg; sem alterações na ausculta cardíaca ou respiratória.\nExames laboratoriais: creatinina = 2,7 mg/dl; ureia = 77 mg/dl; Na+ = 138 mEq/L; K+ = 5,3 mEq/L;\nUrina tipo I: proteína 1+/4+. Qual é a conduta mais adequada?","options":{"A":"Estimular a ingestão hídrica.","B":"Expandir a volemia com salina isotônica.","C":"Furosemida endovenosa após o cateterismo.","D":"Hemodiálise após o cateterismo."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-104854","number":"104854","sourceNumber":"104854","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Considere os índices urinários: I. Sódio > 40 mEq/L; II. Fração de excreção de sódio <\n1%; III. Osmolaridade < 350 mOsm/L; IV. Densidade urinária > 1.015. São encontrados, nos casos\nde necrose tubular aguda, com maior probabilidade:","options":{"A":"III e IV.","B":"I e III.","C":"I e IV.","D":"II e IV.","E":"I e II."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106345","number":"106345","sourceNumber":"106345","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Hepatotoxicidade por sobredose, mialgia/elevação de creatinofosfoquinase, fibrose\npulmonar e edema são, respectivamente, efeitos colaterais de:","options":{"A":"Ácido ascórbico, orfenadrina, dexametasona e nifedipino.","B":"Paracetamol, estatina, amiodarona e pioglitazona.","C":"Cianocobalamina, carisoprodol, aspirina e diclofenaco.","D":"Propranolol, tizanidina, colchicina e espironolactona."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-102650","number":"102650","sourceNumber":"102650","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual das seguintes drogas NÃO está associada ao desenvolvimento de\ninsuficiência renal aguda por toxicidade tubular direta?","options":{"A":"Ciclosporina.","B":"Radiocontraste.","C":"Metotrexato.","D":"Anfotericina B.","E":"Anti-inflamatórios não hormonais."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-106330","number":"106330","sourceNumber":"106330","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual dos seguintes diuréticos pode ser utilizado no tratamento de um paciente com\nhistória de glaucoma, epilepsia e edema?","options":{"A":"Clorotiazida","B":"Acetazolamida","C":"Espironolactona","D":"Polimixida"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-102654","number":"102654","sourceNumber":"102654","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Jovem, 22 anos, foi submetido à enterectomia segmentar por um ferimento, por projétil\nde arma de fogo, abdominal. Apresentava\ntambém outro ferimento, por projétil de arma de fogo,\ntransfixante na perna Direita (D), na altura do cavo poplíteo. A arteriografia e a flebografia da\nperna\nforam normais. Após dois dias da laparotomia exploradora, evoluiu com febre, oligoanúria, com\nurina castanho-avermelhada, dosagem da enzima Creatinofosfoquinase (CPK) de 20.000 U/L e\ncreatinina sérica de 6,2 mg/dl. Ao exame clínico, apresentava grande edema e endurecimento de\ntodo membro inferior direito, que se apresentava mais frio em relação ao contralateral e sem pulso\ndistal palpável. Com relação ao caso, podemos encontrar todas as alterações laboratoriais abaixo,\nEXCETO:","options":{"A":"Hipercalemia.","B":"Hipofosfatemia.","C":"Distúrbio da coagulação.","D":"Acidose metabólica.","E":"Hipocalcemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-80046","number":"80046","sourceNumber":"80046","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 49 anos de idade. HMA: há 2 meses iniciou tratamento para hanseníase com\ndapsona, rifampicina e clofazimina. Após a dose supervisionada, apresentou dor lombar bilateral,\ncontínua, sem febre e que levou à interrupção do tratamento. O tratamento foi reiniciado há 10 dias\nevoluindo novamente com dor lombar, acompanhada de náuseas, vômitos, evacuações pastosas e\noligúria. Nega disúria e polaciúria. EF: edema em tornozelos ++/4+; pressão arterial: 140 x 90\nmmHg; abdome sem dor à palpação, sem visceromegalias e sinal de Giordano negativo. ES:\ncreatinina = 8,5 mg/dl; ureia = 270 mg/dl; sódio = 138 mEq/L; potássio = 5,7 mEq/L. EI:\nultrassonografia mostra rins com aumento de volume. A alteração urinária mais compatível é:","options":{"A":"Cilindros céreos.","B":"Eosinofilúria.","C":"Proteinúria de cadeia leve.","D":"Cristais amorfos."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-79693","number":"79693","sourceNumber":"79693","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"NÃO é condição que piore o risco de desenvolvimento de lesão renal aguda, associada\nao uso de contraste iodado intravenoso:","options":{"A":"nefropatia diabética.","B":"taxa de filtração glomerular < 60 ml/1,73 m².","C":"sexo masculino.","D":"administração de manitol.","E":"uso de contraste com alta osmolaridade."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-82238","number":"82238","sourceNumber":"82238","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"É (são) situação (ões) associadas (s) à insuficiência renal intrínseca em relação à\nnecrose tubular aguda:","options":{"A":"vasculite.","B":"glomerulonefrite aguda.","C":"infecções.","D":"isquemia.","E":"hipertensão maligna."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-61604","number":"61604","sourceNumber":"61604","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São medidas usadas na prevenção da nefropatia induzida por contraste, EXCETO:","options":{"A":"Utilizar contraste não iônico quer seja de baixa ou iso-osmolaridade.","B":"Alcalinizar urina com solução bicarbonatada.","C":"Dopamina em dose dopaminérgica.","D":"Suspender diurético.","E":"Utilizar N-acetilcisteína."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-60127","number":"60127","sourceNumber":"60127","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Todas as alternativas abaixo são complicações da rabdomiólise, com EXCEÇÃO de:","options":{"A":"Hiperuricemia.","B":"Arritmia cardíaca.","C":"Hipercalcemia.","D":"Hipercalemia.","E":"Coagulação intravascular disseminada."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-61209","number":"61209","sourceNumber":"61209","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Menina de 12 anos apresenta cefaleia há 6 meses. Exame físico: peso e estatura no\npercentil 50; PA = 150 x 100 mmHg. Eletrólitos e lipidograma normais. Ultrassonografia renal com\nDoppler: diminuição de fluxo da artéria renal à esquerda de 70%. A conduta para o diagnóstico é:","options":{"A":"Dosar metanefrinas na urina.","B":"Realizar arteriografia.","C":"Dosar ácido vanilmandélico na urina.","D":"Realizar cintilografia renal com DTPA com captopril.","E":"Realizar cintilografia renal com DMSA."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-44238","number":"44238","sourceNumber":"44238","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São medidas preventivas de Insuficiência Renal Aguda associada a procedimentos\ncontrastados, EXCETO:","options":{"A":"Utilização de N-acetilcisteína.","B":"Infusão de bicarbonato de sódio.","C":"Hidratação com cloreto de sódio 0,9%.","D":"Evitar diuréticos.","E":"Uso de contraste de alta osmolaridade."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-47527","number":"47527","sourceNumber":"47527","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O efeito colateral mais grave relacionado ao uso de sinvastatina associada à\ngenfibrozila no tratamento de dislipidemias é:","options":{"A":"Rabdomiólise.","B":"Fibrose retroperitonial.","C":"Hepatite.","D":"Leucopenia.","E":"Convulsão."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-44849","number":"44849","sourceNumber":"44849","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 65 anos é trazido por familiares com relato de queda da própria altura.\nHavia história de diarreia há dois dias. No\nexame físico, paciente encontra-se sonolento,\ndesidratado, FC = 100 bpm e PA = 90 x 60 mmHg. Exames laboratoriais: Ureia sérica = 225 mg/dl;\ncreatinina sérica = 1,7 mg/dl; presença de cilindros hialinos na urina. Permaneceu oligoanúrico\napós hidratação com soro fisiológico parenteral guiado por pressão venosa central, quando recebeu\nduas ampolas de furosemida IV. Neste momento, é CORRETO afirmar que: (VER IMAGEM).","options":{"A":"Trata-se de IRA pré-renal se FENa+ < 2 e FEUr > 35.","B":"Trata-se de IRA renal se FENa+ < 2 e FEUr < 35.","C":"Trata-se de IRA pré-renal se FEUr < 35.","D":"Trata-se de IRA renal se FENa+ > 2 e FEUr < 35.","E":"Trata-se de IRA pré-renal se FEUr > 35."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-47549","number":"47549","sourceNumber":"47549","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em pacientes portadores de alguns tumores sólidos estadiados como no limite da\nressecabilidade cirúrgica, lança-se mão da quimioterapia neoadjuvante, com o intento de reduzir as\ndimensões tumorais de forma a tornar a sua ablação mais segura e radical. Ocorrendo um súbito\nsurto de morte de células tumorais, pode instalar-se a síndrome de lise tumoral, que se associa às\nseguintes aberrações eletrolíticas, EXCETO:","options":{"A":"Hipercloremia.","B":"Hipocalcemia.","C":"Hiperfosfatemia.","D":"Hiperuricemia.","E":"Hiperpotassemia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-36101","number":"36101","sourceNumber":"36101","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher branca, de 21 anos, foi atendida no PS com queixa de crises de cefaleia há\ncerca de 5 meses, tendo sido atendida no PS\npor diversas vezes e medicada com analgésicos com\npouca melhora. Ao exame físico, foi observado: PA em braço direito de 180 x 100 e FC = 90 bpm e\npresença de sopro em topografia de artéria renal direita, de ++/4+. Considerando que a principal\nhipótese para o caso seja de hipertensão renovascular, assinale a afirmativa CORRETA:","options":{"A":"Provas de atividade inflamatória alteradas poderiam ser de grande valor para se fazer o\ndiagnóstico etiológico.","B":"Hemossedimentação de 60 mm poderia indicar possibilidade de arterite temporal.","C":"Há indicação imediata de arteriografia para colocação de stent em artéria renal.","D":"A principal hipótese diagnóstica para o caso seria de panarterite nodosa, pois a hipertensão\narterial ocorre em mais de 70% destes casos.","E":"Está indicada nefrectomia neste caso."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34703","number":"34703","sourceNumber":"34703","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 39 anos de idade, é soterrado por uma parede, onde permaneceu por 6 horas\naté ser retirado. A melhor abordagem\nterapêutica para prevenir a lesão renal aguda é:","options":{"A":"Soro fisiológico EV a 1 L/h.","B":"Bicarbonato de sódio EV diluído com soro glicosado em manitol 10% a 125 ml/h.","C":"N-acetilcisteína oral e NaCl 0,45% EV a 1 ml/kg/h.","D":"Dopamina EV na dose que não exceda 1,5 µg/kg/min."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34823","number":"34823","sourceNumber":"34823","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em paciente com quadro típico de necrose tubular aguda é provável o encontro de:","options":{"A":"exame de urina mostrando cilindros granulosos e epiteliais.","B":"fração de excreção de sódio < 1%.","C":"osmolalidade urinária > 350 mOsm/L.","D":"relação osmolalidade urinária sobre plasmática > 1.","E":"sódio urinário < 20 mEq/L."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-34869","number":"34869","sourceNumber":"34869","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um bebê de 15 meses de vida é levado à Unidade de Saúde por baixo ganho\nponderoestatural. Próximo do nascimento\nencontrava-se no percentil 50 e está, atualmente, no\npercentil 3. Detalhando a história, é possível perceber que a menor vinha apresentando algum grau\nde poliúria e polidipsia. A pesquisa laboratorial revela: sódio = 132 mEq/L; potássio = 3,2 mEq/L;\ncloro = 126 mEq/L e bicarbonato = 15 mEq/L. Estudos urinários específicos revelam um pH urinário\nde 5 e que há um ânion-gap urinário positivo. O provável diagnóstico desta criança é:","options":{"A":"Acidose tubular renal.","B":"Ingestão de dieta com formulação inadequada.","C":"Diabetes insipidus central.","D":"Diabetes insipidus nefrogênico.","E":"Secreção inapropriada de vasopressina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-27247","number":"27247","sourceNumber":"27247","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Considere alguns mecanismos que predispõem à insuficiência renal aguda: I.\nVasoconstrição. II. Lesão tubular direta. III.\nNefrite intersticial aguda. IV. Obstrução intratubular.\nContraste radiológico, lise tumoral pós-quimioterapia, aminoglicosídeos e penicilinas relacionam-se,\nrespectivamente, a:","options":{"A":"I, II, III e IV.","B":"I, IV, II e III.","C":"II, III, I e IV.","D":"III, IV, II e I.","E":"IV, I, III e II."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-29171","number":"29171","sourceNumber":"29171","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma paciente de 65 anos, assintomática, apresenta quadro de hipertensão arterial há\n25 anos, controlada com diurético tiazídico.\nSeus pais são hipertensos. Após a menopausa, houve\naumento dos níveis tensionais, sendo necessária a associação com inibidor da enzima conversora\nde angiotensina e amlodipina em doses adequadas, sem descontinuidade do tratamento. Ao exame\nclínico observou-se: índice de massa corpórea: 35; PA: 160x 50 mmHg, fundo de olho com\nalterações vasculares discretas sem papiledema, sopro sistólico em carótida direita, coração com\n4ª . bulha, pulsos tibial posterior e pedioso direitos reduzidos, com leve edema de tornozelo. Ao\neletrocardiograma, sinais de sobrecarga ventricular esquerda e hipertrofia miocárdica ao\necocardiograma. No exames laboratoriais mostrou: glicemia de jejum 130 mg/DL; creatinina: 1,5\nmg/DL; ureia: 60mg/DL; Na: 136 mEq/L; K: 4,2 mEq/L; proteínas totais no soro de 7,4 mg/DL e\nalbumina 3,7 mg/DL; colesterol total: 264 mg/DL; sedimento urinário normal. Podemos afirmar que:","options":{"A":"trata-se de paciente renal crônica e necessita tratamento dialítico.","B":"provavelmente tem hipertensão essencial necessitando redução vigorosa de peso como medida\ninicial. Caso a medida eficaz não surta efeito, pensar em hipertensão renovascular secúndaria a\naterosclerose.","C":"a primeira hipótese é hiperaldosteronismo primário, devendo realizar dosagem de\naldosterona/renina plasmáticas e tomografia computadorizada de abdomen.","D":"não pode ser afastada a hipótese de hipertensão secundária a feocromocitoma.","E":"pode ser considerado um caso de hipertensão arterial sistêmica em fase de malignização."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-11973","number":"11973","sourceNumber":"11973","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual das alternativas abaixo não pode ser considerada isoladamente medida\nnefroprotetora para o desenvolvimento de\ninsuficiência renal crônica na síndrome metabólica?","options":{"A":"Inibidor da enzima de conversão da angiotensina.","B":"Antagonista do receptor da angiotensina.","C":"Alopurinol.","D":"Estatina.","E":"N-acetilcisteina."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-11974","number":"11974","sourceNumber":"11974","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Na insuficiência renal aguda intrínseca, podemos afirmar que:","options":{"A":"em metade dos casos, pode ser corrigida com o restabelecimento da perfusão renal e da\npressão de filtração glomerular.","B":"a necrose tubular aguda ocorre nos casos de embolia ou estenose crítica da artéria renal.","C":"o uso de dopamina aumenta o fluxo sanguineo renal e previne efetivamente o desenvolvimento\nde IRA isquêmica ou nefrotóxica.","D":"o diagnóstico pode ser caracterizado quando em geral a fração de excreção do sódio é inferior a\n1%.","E":"a primeira medida a ser tomada na hiperpotassemia acompanhada de alterações\neletrocardiográficas é o tratamento dialitico."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-363806","number":"363806","sourceNumber":"363806","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 32 anos é avaliado devido hipertensão arterial e hipercalemia persistente\n(5,9 mEq/L). Ele não usa nenhum medicamento e\ndois membros de sua família apresentam quadro\nclínico semelhante. Demais exames de sangue: sódio: 140 mEq/L; cloreto: 114 mEq/L; bicarbonato:\n16 mEq/L; creatinina: 0,8 mg/dL; glicemia: 90 mg/dL. Os níveis séricos de renina e aldosterona são\nbaixos. O sódio urinário é de 30 mEq/L. A gasometria arterial mostra acidose metabólica\nhiperclorêmica. Considerando a principal hipótese para doença de base, o tratamento inicial\nrecomendado é","options":{"A":"acetazolamida.","B":"furosemida.","C":"hidroclorotiazida.","D":"substituto de sal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-371314","number":"371314","sourceNumber":"371314","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A observação de sinais de hipovolemia e hipotensão arterial ou sinais de obstrução do\ntrato urinário auxiliam o diagnóstico diferencial de IRA pré ou pós-renal. Sendo correto que:","options":{"A":"Devem-se procurar sinais associados com a etiologia e complicações da IRA. A ausência de\nlivedo reticular e micro-infartos digitais podem sugerir doença renal ateroembólica.","B":"Devem-se procurar sinais associados com a etiologia e complicações da IRA. A presença de\nlivedo reticular e não os micro-infartos digitais, podem sugerir doença renal ateroembólica.","C":"Devem-se procurar sinais associados com a etiologia e complicações da IRA. A presença de\nlivedo reticular e micro-infartos digitais podem sugerir doença renal ateroembólica.","D":"Devem-se procurar sinais associados com a etiologia e complicações da IRA. A presença de\nlivedo reticular e micro-infartos digitais, excluem doença renal ateroembólica."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-371303","number":"371303","sourceNumber":"371303","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"IRA RENAL intrínseca ou estrutural apresenta como principal causa:","options":{"A":"A necrose tubular aguda (NTA isquêmica e/ou tóxica), sendo causas as nefrites\ntubulo-intersticiais (drogas, infecções),\npielonefrites, glomerulonefrites e necrose cortical\n(hemorragias ginecológicas, peçonhas).","B":"A necrose tubular aguda (NTA isquêmica e não a tóxica), sendo causas as nefrites\ntubulo-intersticiais (drogas, infecções), pielonefrites, glomerulonefrites e necrose cortical\n(hemorragias ginecológicas, peçonhas).","C":"A necrose tubular aguda (NTA isquêmica e/ou tóxica), sendo causas as nefrites\n\ntubulo-intersticiais (drogas, infecções), pielonefrites, glomerulonefrites e não a necrose cortical\n(hemorragias ginecológicas, peçonhas).","D":"A necrose tubular aguda (NTA isquêmica e/ou tóxica), sendo causas as nefrites\ntubulo-intersticiais (drogas, infecções), pielonefrites, glomerulonefrites e necrose central\n(hemorragias ginecológicas, peçonhas)."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-367075","number":"367075","sourceNumber":"367075","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 18 anos é avaliado em consulta pelo o 3o epi- sódio de gota nos últimos 12\nmeses. Antes desse epi- sódio, ele estava saudável. Os episódios anteriores de gota foram\ntratados com prednisona, anti-inflamatórios não esteroides e, mais recentemente, iniciou tratamento\ncom alopurinol, 100 mg/dia. Os sinais vitais são normais e, exceto por um tornozelo direito dolorido\ne inchado, seu exame é normal. A história familiar revela vários familiares com gota e dois\nfamiliares fazem diálise. Exames de sangue: creatinina: 1,4 mg/dL (há 1 ano, era 1,1 mg/dL); ácido\núrico: 9,7 mg/dL. Exame de urina: negativo para sangue e proteína. A ultrassonografia renal é\nnormal. Considerando a principal hipótese, a doença se associa à mutação de","options":{"A":"mucina-1.","B":"policistina-1.","C":"renina.","D":"transportador de cloreto dependente de voltagem.","E":"uromodulina."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-329424","number":"329424","sourceNumber":"329424","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 33 anos, atleta de crossfit e sem comorbidades, é admitido no pronto\natendimento por mialgia intensa há 5 dias,\nevoluindo com náuseas, vômitos, inapetência e queda\ndo estado geral há 1 dia. Exames laboratoriais evidenciaram creatinina = 6,82 mg/dL, ureia 202\nmg/dL e exame de urina com hemácias 2/campo e hemoglobina ++++. O principal mecanismo\nfisiopatológico da insuficiência renal aguda desse paciente é:","options":{"A":"isquemia renal medular.","B":"depósito de imunocomplexos em glomérulo.","C":"obstrução tubular por pigmentos heme em associação com ácido úrico.","D":"dilatação de arteríola eferente glomerular.","E":"ação direta de toxinas no túbulo distal."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-333351","number":"333351","sourceNumber":"333351","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 20 anos, gênero feminino, procura atendimento de emergência por queixas\nde fraqueza muscular e câimbras há 2 semanas\ncom piora importante na data da admissão\nhospitalar. Sinais vitais: PA=114x71mmHg, FR=18ipm, FC=78bpm, afebril. Não apresenta\ndisestesias ou alterações em reflexos tendinosos. Exames laboratoriais: Hb=12,5g/dl, leucócitos\ntotais=7400/mm? e plaquetas=180mil, Na=137mEq/l, K=2,1mEq/l, creatinina=1,0mg/dl, gasometria\nvenosa: ph=7,15 HCO?=15 pCO?=28, glicemia=98mg/dl Cl=112mEq/l, Urina I: ph=6,7\ndensidade=1015 ausência de proteínas, corpos cetônicos, leucocitúria ou hematúria. Qual\ndiagnóstico poderia justificar o quadro clínico e os achados laboratoriais da paciente?","options":{"A":"Amiloidose","B":"Síndrome de Sjogren","C":"Síndrome de Bartter","D":"Hiperaldosteronismo primário"},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-287808","number":"287808","sourceNumber":"287808","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 78 anos, hipertenso, diabético tipo 2 e tabagista, em uso de furosemida 40\nmg/dia, metformina 1.000 mg/dia, AAS 100 mg/dia e losartana 100 mg/dia. Foi submetido a\ncateterismo e angioplastia devido à angina instável de alto risco com lesão significativa em\ndescendente anterior. Manteve-se assintomático, estável hemodinamicamente, euvolêmico, com\ndiurese satisfatória, sem sinais de infecção. Apresentou piora da função renal: creatinina basal e\nda\nadmissão = 0,8 mg/dl; após 72h do procedimento = 1,2 mg/dl. O provável diagnóstico e as medidas\nque poderiam ter sido feitas para evitá-lo são, respectivamente:","options":{"A":"Nefropatia induzida por contraste; suspender drogas nefrotóxicas antes do procedimento,\nrealizar hidratação endovenosa pré e\npós-procedimento e usar contraste isosmolar (ou hiposmolar)\nem menor volume.","B":"Nefropatia induzida por contraste; suspender drogas nefrotóxicas antes do procedimento,\nrealizar hidratação endovenosa pré e pós-procedimento,\nadministrar acetilcisteína e estatina.","C":"Doença renal ateroembólica; suspender drogas nefrotóxicas antes do procedimento, realizar\nhidratação endovenosa pré e pós-procedimento.","D":"Doença renal ateroembólica; nada poderia ser feito para prevenção dessa patologia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-272867","number":"272867","sourceNumber":"272867","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher, 74 anos de idade, com antecedente de acidente vascular isquêmico há 8 anos,\nsem sequelas, com bom controle da pressão\narterial, em uso de anlodipino 10 mg/dia. Em sua\núltima consulta, apresentou diário de controle pressórico repleto de valores fora da meta, (valores\nde pressão arterial sistólica sempre em torno de 190 mmHg). A paciente negava qualquer mudança\nde dieta ou má aderência medicamentosa. Optou-se pela introdução de enalapril e\nhidroclorotiazida. Na consulta de retorno, após o uso das medicações, a paciente traz exames\nlaboratoriais com creatinina = 2,8 mg/dl (valor prévio = 1,3 mg/dl); ureia = 196 mg/dl; K = 5,1\nmEq/L.\nAs condutas medicamentosa e diagnóstica para esta paciente devem ser, respectivamente:","options":{"A":"Início de alisquireno; ultrassonografia de abdome total.","B":"Suspensão do enalapril; ultrassonografia com Doppler de artérias renais.","C":"Suspensão de hidroclorotiazida; ultrassonografia com Doppler de artérias renais.","D":"Suspensão do enalapril; dosagem de renina e aldosterona plasmática."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-248519","number":"248519","sourceNumber":"248519","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente de 31 anos, atleta de cross-fit e sem comorbidades, admitido no\n\nPronto-Socorro por mialgia intensa há 4 dias, evoluindo com náuseas, vômitos, inapetência e\nprostração há 1 dia. Solicitados exames\nlaboratoriais que evidenciaram Creatinina 6,8mg/dL, Uréia\n202 mg/dL; exame de urina com 2 hemácias por campo e Hemoglobina ++++. Qual o principal\nmecanismo fisiopatológico da insuficiência renal aguda desse paciente?","options":{"A":"Depósito de imunocomplexos em glomérulo.","B":"Obstrução tubular dos pigmentos heme em associação com ácido úrico.","C":"Ação direta de toxinas no túbulo distal.","D":"Dilatação de arteríola eferente glomerular.","E":"Isquemia renal medular."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-250422","number":"250422","sourceNumber":"250422","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente vítima de trauma ocorrido há 5 horas com esmagamento de membros\ninferiores e suspeita de rabdomiólise. São\ncondutas adequadas no manejo desse caso, EXCETO:","options":{"A":"Iniciar hidratação vigorosa, em caso de confirmação do diagnóstico de rabdomiólise.","B":"Acompanhar a função renal, em caso de confirmação do diagnóstico de rabdomiólise.","C":"Solicitar dosagem de potássio, uma vez que, hipercalemia é comum e pode necessitar de\ntratamento.","D":"Solicitar dosagem sérica de mioglobina, uma vez que, este é o método mais sensível para\nconfirmar o diagnóstico."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-250425","number":"250425","sourceNumber":"250425","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 27 anos é trazido ao pronto atendimento após esmagamento do membro\ninferior direito em acidente de trabalho. Queixa-se de parestesia nos quatro membros e fraqueza\ngeneralizada. Os exames eram creatinina: 1,2mg/dL, potássio: 7,5meq/L, CK total: 5.670. O ECG\nestá apresentado a seguir: Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Deve-se iniciar hidratação venosa vigorosa para prevenção de injúria renal aguda, e o ringer\nlactato é uma alternativa adequada.","B":"Os beta-2-agonistas e a insulina regular com glicose podem reduzir os níveis séricos do\npotássio.","C":"Além da hipercalemia, esse paciente possui risco aumentado de outros distúrbios eletrolíticos,\ncomo hipocalcemia e hiperfosfatemia.","D":"O paciente deve ser monitorizado, e deve-se administrar gluconato de cálcio 1g endovenoso, e\nrepetir a cada 10 minutos se persistirem as alterações elétricas cardíacas."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-244863","number":"244863","sourceNumber":"244863","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em quadros de Nefrite Intersticial Aguda, a tríade de febre, rash e artralgias é mais\nrelacionada ao uso de:","options":{"A":"Anti-inflamatórios não estereoidais (AINE?s).","B":"Beta-lactâmicos.","C":"Anticonvulsivantes.","D":"Sulfas."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-226247","number":"226247","sourceNumber":"226247","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em pacientes vítimas de lesões renais que provocaram áreas de isquemia no\nparênquima renal, podemos encontrar como complicação tardia:","options":{"A":"Cólicas intermitentes;","B":"Sangramento e instabilidade hemodinâmica;","C":"Insuficiência renal dialítica.","D":"Hipertensão Arterial;"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-255857","number":"255857","sourceNumber":"255857","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um menino de 05 anos, com atraso na fala, apresenta hematúria macroscópica.\nAudiometria revela perda auditiva bilateral para altas frequências. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Síndrome de Berger.","B":"Síndrome de Goodpasture.","C":"Síndrome de Alport.","D":"Síndrome de Batter."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-212348","number":"212348","sourceNumber":"212348","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher, 60 anos, diabética, com quadro de urina escura e dor lombar há 2 dias.\nSumário de urina: hemácias 2/campo, Hb +++,\nproteína traços, leucócitos 3/campo. Refere ser\ntabagista e está fazendo uso de estatina para controle de dislipidemia há 30 dias. O diagnóstico\nMAIS PROVÁVEL é:","options":{"A":"Neoplasia do trato urinário.","B":"Rabdomiólise.","C":"Necrose de papila renal.","D":"Litíase renal.","E":"Porfiria."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-208466","number":"208466","sourceNumber":"208466","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente JB, 42 anos, chega ao serviço de Clínica Médica, portando o exame de urina\n1 com glicosúria e fosfatúria. Considerando\na principal hipótese diagnóstica, são sintomas que\npodem estar presentes em sua forma hereditária, EXCETO:","options":{"A":"Raquitismo hipofosfatêmico.","B":"Hipercalemia.","C":"Acidose tubular proximal.","D":"Poliúria.","E":"Polidipsia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-213014","number":"213014","sourceNumber":"213014","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual a principal medida terapêutica a ser utilizada em um paciente com rabdomiólise?","options":{"A":"Hemodiálise precoce.","B":"Reposição volêmica precoce.","C":"Manitol.","D":"Uso de diuréticos."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-212245","number":"212245","sourceNumber":"212245","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em um paciente com uso recente de antibio?tico e que passa a apresentar febre,\nartralgia disseminada, rash cuta?neo, eosinofilia e\ncilindros leucocita?rios na urina, o diagno?stico\nmais prova?vel é de","options":{"A":"pielonefrite aguda.","B":"pu?rpura trombocitope?nica trombo?tica.","C":"si?ndrome hemoliticoure?mica.","D":"endocardite infecciosa.","E":"nefrite intersticial ale?rgica."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-214773","number":"214773","sourceNumber":"214773","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"De acordo com o Guideline da American Heart Association, são consideradas\nindicações para o tratamento invasivo da estenose da artéria renal, EXCETO","options":{"A":"hipertensão arterial associada a rim único.","B":"insuficiência renal crônica (creatinina sérica > 1mg/dL).","C":"hipertensão arterial associada à intolerância medicamentosa.","D":"hipertensão arterial refratária ao tratamento, com pelo menos três medicações de diferentes\nclasses."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-184554","number":"184554","sourceNumber":"184554","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Não é causa de Rabdomiólise:","options":{"A":"Psicose aguda","B":"Imobilização prolongada","C":"Status Asmáticus","D":"Hiperfosfatemia","E":"Hipertermia"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-158727","number":"158727","sourceNumber":"158727","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Indique qual das alternativas abaixo é a mais eficaz para prevenir a insuficiência renal\naguda pós-cinecoronariografia com agente radiológico contendo contraste iodado:","options":{"A":"Uso de agente radiológico com alta osmolaridade (entre 1500 e 1800 mosm/kg).","B":"Adminstração durante e imediatamente após o procedimento de dopamina intravenosa, 2\nµg/kg/min.","C":"Administração de solução salina intravenosa, 1 ml/kg/h antes e após o procedimento.","D":"Infusão intravenosa de furosemide (5 mg/h) durante e após o procedimento.","E":"Infusão intravenosa de manitol 20% (1 ml/kg) durante o procedimento."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-152827","number":"152827","sourceNumber":"152827","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Faça a correlação entre a situação clínica e a conduta recomendada. Situação clínica:\n\n1. Infecção urinária; 2. Investigação de disfunção renal; 3. Nefrite tóxica; 4. Nefrite\ntubulointersticial\naguda; 5. Nefropatia diabética. Conduta\nrecomendada: A. Corticosteroides; B. Inibidores de enzima\nde conversão; C. Antibioticoterapia; D. Taxa de depuração da creatinina; E. Retirada da droga\nsuspeita. A sequência CORRETA de correlações é:","options":{"A":"1a, 2b, 3c, 4d, 5e.","B":"1a, 2c, 3d, 4e, 5b.","C":"1c, 2e,3a, 4b, 5d.","D":"1c, 2d, 3e, 4a, 5b.","E":"1b, 2d,3e, 4a, 5c."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-160964","number":"160964","sourceNumber":"160964","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 69 anos de idade tem apresentado Diabetes Mellitius bem controlado por 12\nanos. Sua terapia consiste de metformina, 500 gramas três vezes ao dia, com as refeições; a\nfunção renal tem sido normal. O paciente desenvolve fadiga grave e falta de ar, o\neletrocardiograma e as medidas de enzima cardíacas corroboram um infarto do miocárdio anterior.\nEncontram-se hemodinamicamente estável. Seu cardiologista aconselha uma angiografia\ncoronariana e pergunta sobre a terapia do diabetes. O que você recomendaria?","options":{"A":"Interromper a metformina por três dias e trocá-la por insulina","B":"Interromper a metformina por três dias antes do procedimento e iniciar sulfoniluréia","C":"Continuar a metformina se a uréia nitrogenada sanguínea e a creatinina sérica forem normais","D":"Interromper a metformina no dia do procedimento e medir a creatinina sérica em 24 horas; se\nnormal, reiniciar a metformina","E":"Interromper a metformina no dia do procedimento e medir o acido láctico; se normal, iniciar o\ntratamento com metformina"},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-132670","number":"132670","sourceNumber":"132670","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A causa provável de insuficiência renal aguda nos pacientes que utilizam amicacina é:","options":{"A":"Necrose tubular aguda.","B":"Nefrite intersticial.","C":"Obstrução renovascular.","D":"Síndrome de hiperviscosidade.","E":"Nenhuma das anteriores."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-133350","number":"133350","sourceNumber":"133350","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Você é chamado para avaliar e dar seu parecer sobre um paciente que fará\nangioressonância magnética cerebral para\ndiagnóstico diferencial de cefaleia. Trata-se de um\nhomem com 55 anos, branco, diabético há 10 anos, em uso de insulina NPH e vildagliptina com\nbom controle ambulatorial. Faz acompanhamento com nefrologista por nefropatia diabética (A3) em\nuso de Losartana 50 mg/dia, furosemida 40 mg/dia, anlodipino 5 mg/dia. Exame físico sem\nalterações. O que você recomenda?","options":{"A":"Suspender a angiorressonância, pois este exame estaria contraindicado para este paciente.","B":"Liberar o paciente para o exame, sendo realizada hidratação venosa e N acetilcisteína.","C":"Liberar o paciente sem recomendações adicionais.","D":"Sugerir a não realização do exame, pois este paciente tem alto risco para piora na função renal\nmesmo com profilaxia renal adequada.","E":"Liberar o exame e recomendar que o paciente faça uma adequada hidratação oral pré-exame e\nprescreve N acetilcisteína 600 mg via oral 12/12hs antes e após a RNM."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-130417","number":"130417","sourceNumber":"130417","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente, 36 anos, internado na Unidade de Terapia Intensiva após traumatismo\ncraniano (queda de laje), evoluiu com poliúria (7 litros/24 horas) de causa indeterminada.\n\nApresentava função renal preservada, glicemia de 76 mg/dl, sódio sérico de 156 mEq/L (normal ?\n136 a 145), e osmolalidade urinária de 180\nmOsm/kg/H2O (normal - 250 a 900). O diagnóstico para\neste paciente é:","options":{"A":"Diurese osmótica.","B":"Síndrome perdedora de sal central.","C":"Diabetes insipidus.","D":"Síndrome da secreção inapropriada de ADH."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-132554","number":"132554","sourceNumber":"132554","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"O sistema renina-angiotensina-aldosterona ? SRAA é diretamente ativado pelas\ncondições abaixo, EXCETO:","options":{"A":"Insuficiência cardíaca.","B":"Hipocalemia.","C":"Desidratação/diarreia.","D":"Hipotensão arterial."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-111966","number":"111966","sourceNumber":"111966","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Corredor amador de corrida de São Silvestre, sexo masculino, 32 anos, pele negra,\nsem doenças preexistentes, faltando apenas 1\nquilômetro para finalizar o percurso, cai no meio da\nAvenida Paulista e é levado ao PS. No momento do resgate apresentou temperatura corporal de\n42,5 graus Celsius, taquipneico e letárgico. Após a chegada no PS, no exame de urina com fita\nreagente mostra sangue, não havendo eritrócitos na análise. Raio X de tórax apresenta índice\ncardiotorácico menor que 0,50. ECO com fração de ejeção estável em 50%. ECG normal. Exame\nde sangue apresenta nível de creatina quinase aumentado em 5 vezes. Em repouso está\napresentando FC de 60 bpm. Pressão sistólica abaixo de 130. Pressão Diastólica abaixo de 85. O\ndiagnóstico mais provável e o tratamento mais correto são:","options":{"A":"Rabdomiólise causado por Heat stroke. Tratamento: Hidratação IV imediata e agressiva com\nsoro fisiológico;","B":"Infarto do Miocárdio. Tratamento: Clopidogrel 75mg/dia;","C":"Insuficiência Cardíaca. Tratamento: Metoprolol 50mg/dia;","D":"Toxídrome antimuscarínica. Tratamento: Atropina 100mg/dia."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-105337","number":"105337","sourceNumber":"105337","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Assinale a alternativa CORRETA quanto aos distúrbios metabólicos encontrados na\nsíndrome de lise tumoral:","options":{"A":"Hipercalemia, hiperuricemia, hipocalcemia e acidose metabólica.","B":"Hipercalemia, hiperuricemia, hipocalcemia e alcalose metabólica.","C":"Hipercalemia, hiperuricemia, hipercalcemia e acidose metabólica.","D":"Hipocalemia, hiperuricemia, hipocalcemia e acidose metabólica."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-103375","number":"103375","sourceNumber":"103375","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo feminino, 30 anos, procurou a unidade de emergência municipal\ndevido a quadro de febre (38,5°C) aferida\nem casa, astenia e oligúria nos últimos três dias. Em sua\nhistória clínica, foi referido que, há oito dias, procurou a unidade básica de saúde próxima de sua\ncasa, com queixas urinárias, sendo recomendado o uso de sulfametoxazol + trimetoprima para\ninfecção urinária baixa. O exame físico de entrada evidenciou: rash cutâneo, de característica\neritematopapular, nas regiões da face, do tórax e do abdome; pressão arterial de 140 x 100 mmHg;\ntemperatura axilar de 38,2°C. Exames laboratoriais: hematócrito = 34%; hemoglobina = 10,5 g%;\nleucograma = 14.000/mm³ (60% seg. / 4% bast. / 22% linfo. / 12% eos. / 2% mono.); ureia = 100\nmg%; creatinina = 3,0 mg%; Na = 137; K = 5,2; Cl = 112 mEq/L; FAN = negativo; urina = 10\npiócitos/campo; hemácias = 20/campo; cilindros granulosos e hemáticos ausentes; bacteriúria\nescassa; <i>clearance</i> de creatinina = 40 ml/min; proteinúria = 1,3 g/24h. Esses dados são\nsugestivos de:","options":{"A":"Pielonefrite aguda complicada com insuficiência renal.","B":"Nefropatia por IgA.","C":"Nefrite intersticial aguda.","D":"Nefrite secundária, devido à doença exantemática.","E":"Nefrite por lúpus induzido por droga."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-80198","number":"80198","sourceNumber":"80198","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma mulher de 22 anos está em tratamento de amigdalite purulenta há 9 dias com\namoxacilina com melhora das dores, porém voltou a apresentar febre baixa. Ao exame físico\nverifica-se exantema macular em MMII, MMSS e tronco. Os exames laboratoriais disponíveis são\nos seguintes: creatinina 1,2 mg%, Na 136 mEq/l, K 4,8 mEq/l. Cloreto 109 mEq/l, bicarbonato 18\nmEq/l. Urina I densidade 1010, leucócitos 15-20 campo, hemácias 4-5 /campo, protéina +/++++.\nHemograma Hb 13 Ht 43% GB 13000 (leucócitos 70%, eosinófilos 9%, linfócitos 12%, Monócitos\n9%). Esta paciente provavelmente deve apresentar:","options":{"A":"Um quadro de glomerulonefrite difusa e aguda.","B":"Doença de Berge,","C":"Nefropatia lúpica Classe III,","D":"Insuficiência renal crônica estágio II,","E":"Nefrite túbulo-intersticial aguda."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83004","number":"83004","sourceNumber":"83004","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A lesão renal mais frequentemente causada pelo uso de aminoglicosídeos é:","options":{"A":"Nefropatia obstrutiva por cristais.","B":"Proliferação da membrana basal glomerular.","C":"Nefrite intersticial.","D":"Necrose tubular aguda.","E":"Glomerulonefrite por imunocomplexos."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-83020","number":"83020","sourceNumber":"83020","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem, 62 anos de idade, hipertenso há 22 anos, faz uso regular das medicações. Há\num ano o controle da hipertensão se tornou\nmais difícil e exigiu a introdução de novas medicações.\nAtualmente usa: hidroclorotiazida = 25 mg/dl; propranolol = 240 mg/dl; anlodipino = 10 mg/dl. Não\ntem queixas clínicas. Exame clínico: PA = 182 x 116 mmHg; FC = 64 bpm. O restante do exame é\nnormal. Exames recentes: ureia = 55 mg/dl; Cr = 1,7 mg/dl; Na+ = 131 mEq/L; K+ = 4,0 mEq/L.\nUltrassonografia de abdome: rim esquerdo = 7,8 cm; rim direito = 10,1 cm, sem outras alterações. A\nprincipal hipótese para o quadro atual do paciente é:","options":{"A":"Hiperaldosteronismo primário.","B":"Nefroesclerose hipertensiva.","C":"Falta de aderência ao tratamento.","D":"Aterosclerose de artéria renal.","E":"Displasia fibromuscular de artéria renal."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-62055","number":"62055","sourceNumber":"62055","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Um homem de 27 anos iniciou tratamento com penicilina (ampicilina) para faringite\nestreptocócica. Ele não relatava problemas\nmédicos anteriores. Duas semanas depois,\ndesenvolveu eritema e fadiga generalizada. A erupção era macular e simétrica na aparência. O\nexame físico revelou um paciente com aparência debilitada e com diminuição do turgor cutâneo. Os\nexames laboratoriais revelam uma creatinina sérica de 2,4 mg/dl (em comparação com uma basal\nde 1,1 mg/dl) e ureia de 114 mg/dl. O melhor exame na avaliação da lesão renal aguda desse\npaciente é:","options":{"A":"Fração de excreção do sódio.","B":"Concentração urinária do sódio.","C":"Leucograma com diferencial.","D":"Exame microscópico do sedimento urinário.","E":"Osmolaridade urinária."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-62107","number":"62107","sourceNumber":"62107","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"A síndrome da lise tumoral ocorre em pacientes portadores de tumores no qual há uma\nalta taxa de proliferação celular. Durante o tratamento oncológico, ocorre uma liberação rápida de\nmetabólitos intracelulares, comprometendo a capacidade de excreção renal. Desta forma podemos\nconcluir que a síndrome da lise tumoral caracteriza-se por:","options":{"A":"Aumento de ácido úrico, fosfato e potássio com diminuição do cálcio sérico.","B":"Aumento de ácido úrico e fosfato com diminuição do cálcio sérico e potássio.","C":"Aumento de potássio com diminuição do cálcio sérico, ácido úrico e fosfato.","D":"Aumento de ácido úrico, cálcio sérico e potássio com diminuição do fosfato.","E":"Aumento de ácido úrico, fosfato, potássio e cálcio sérico."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-48421","number":"48421","sourceNumber":"48421","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Com relação à síndrome de lise tumoral, marque a alternativa CORRETA.","options":{"A":"A síndrome de lise tumoral é mais frequente após início do tratamento de tumores de baixo grau\ncomo linfoma folicular.","B":"A lise tumoral está associada ao início da quimioterapia, radioterapia ou corticoterapia de\ntumores de alto grau como o linfoma difuso de grandes células B e a neoplasia de pequenas\ncélulas de pulmão.","C":"A medida mais eficaz na prevenção da síndrome de lise tumoral é o uso de agentes que\ninduzem a diminuição do nível sérico de ácido úrico como o alopurinol.","D":"A síndrome de lise tumoral geralmente é acompanhada de hipocalemia e hiperuricemia."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-37257","number":"37257","sourceNumber":"37257","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Nas primeiras 6 horas de pós-operatório de embolectomia de artéria ilíaca esquerda, foi\nverificado aumento de consistência e dor importante no compartimento anterior da perna esquerda\ne presença de urina avermelhada. Podemos dizer que:","options":{"A":"A heparinização foi feita de maneira inadequada e provavelmente o sangue do doente está\nincoagulável, havendo formação de hematomas generalizados, inclusive no plano subaponeurótico.","B":"A fasciotomia deve ser realizada imediatamente e provavelmente está ocorrendo a síndrome\nmetabólica mionefropática.","C":"Devemos aguardar a mensuração da pressão intracompartimental para realizar a fasciotomia e\nprovavelmente houve uma lesão na passagem da sonda uretral, responsável pela hematúria.","D":"A fasciotomia deve ser realizada imediatamente e devemos instalar uma sonda de três vias para\nlavagem da bexiga evitando a formação de hematomas intravesicais.","E":"Houve lesão arterial feita pela passagem do cateter de Fogarty e está se formando um grande\nhematoma no compartimento anterior, não havendo necessidade de fasciotomia de urgência."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-35537","number":"35537","sourceNumber":"35537","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Das seguintes afirmativas relacionadas ao mercúrio: 1- O mercúrio é um metal líquido\nque se volatiliza facilmente à temperatura\nambiente. 2- A intoxicação profissional pelo mercúrio se\nfaz principalmente através da pele. 3- Trabalhadores da indústria de termômetros ou barômetros\nestão particularmente expostos ao mercúrio. 4- O mercúrio é eliminado pela respiração e urina,\nespecialmente. Estão CORRETAS:","options":{"A":"Somente 1 e 3.","B":"Somente 2 e 4.","C":"Somente 1, 3 e 4.","D":"Somente 1, 2 e 3.","E":"Todas (1 a 4)."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-28422","number":"28422","sourceNumber":"28422","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação ao diabetes insipidus, é correto afirmar que:","options":{"A":"poliúria acentuada, volume urinário diário superior a 3000 ml e urina hipertônica. Osmolaridade\nplasmática maior que 300 mOsm/L e densidade urinária maior que 1010.","B":"se a osmolaridade plasmática for de 295 mOsm/L ou maior, e a urinária for inferior a do plasma,\nou seja, urina hipotônica, com densidade\nurinária menor que 1010, o diagnóstico de diabetes\ninsipidus já pode ser estabelecido.","C":"o teste da deprivação hídrica, no qual se observa a osmolaridade plasmática máxima e a\nosmolaridade urinária, é especialmente recomendado a pacientes com diurese aquosa e\nhipernatremia.","D":"os pacientes com diabetes insipidus nefrogênico respondem significantemente ao DDAVP\n(desamino-Darginina-8-vasopressina), o que não é observado na forma neurogênica.","E":"ocorrem níveis muito elevados do hormônio antidiurético e isso resulta em surgimento de\nhiponatremia com níveis de osmolaridade urinária muito reduzidos, caracterizando a diurese\naquosa e volumosa desses pacientes."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-28409","number":"28409","sourceNumber":"28409","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Em relação à nefropatia induzida por contraste, é CORRETO afirmar que:","options":{"A":"Na maioria dos casos, a insuficiência renal aguda induzida pelo contraste é oligúrica, por isso,\né\nrecomendado o uso profilático de diuréticos de alça 12 horas antes e 12 horas após o contraste, na\nproteção da nefropatia por contraste.","B":"O uso profilático de drogas renoprotetoras, como inibidores do sistema\n\nrenina-angiotensina-aldosterona, 12 horas antes e 12 horas após o contraste, na proteção da\nnefropatia por contraste é fortemente reforçado pela literatura.","C":"Lesão renal prévia, ou seja, creatinina superior a 1,5 mg/dl, é o mais importante fator de risco\npara nefropatia induzida por contraste. Hidratação\nadequada com soluções de cloreto de sódio e a\nmenor dose de contraste, sua melhor prevenção.","D":"Ocorre aumento abrupto da creatinina sérica, aumento de 0,5 mg/dl ou queda de 25% no\nclearance de creatinina, após cinco a sete dias do exame contrastado. A N-acetilcisteína sua\nmelhor prevenção.","E":"O uso profilático de metformina em diabéticos, 12 horas antes e 12 horas após o contraste, é\nfortemente reforçado pela literatura, na proteção da nefropatia por contraste."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-28013","number":"28013","sourceNumber":"28013","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 34 anos, nos últimos três dias apresenta-se com febre, astenia e oligúria. Há\numa semana usou sulfa/trimetoprim para\ninfecção urinária baixa. O exame físico mostra: rash\neritematopapular na face, tórax e abdome; PA = 140 x 100 mmHg; temp. ax = 37,8°C (restante\nnormal). Exame complementar: Ht = 38%; Hb= 11,7g%; leucograma =12.000/mm³ (62 SEGM/3\nBASTI22 LINFO/12 EOSINO/1 MONO); ureia = 94 mg%; creatinina = 2,8 mg%; Na = 136; K = 5,2;\nCl = 110 mEq/L; FAN - negativo; urina: 12-15 piócitos/campo; Incontáveis hemácias; cilindros\ngranulosos e hemáticos; ausência de bactérias; clearance de creatinina = 30 ml/min; proteinúria =\n1,2 g/24h. Esses dados são indicativos prováveis de:","options":{"A":"nefropatia por IgA","B":"púrpura anafilactoide","C":"nefrite intersticial aguda","D":"pielonefrite aguda complicada","E":"nefrite por lúpus induzido por droga"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-28062","number":"28062","sourceNumber":"28062","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"As condições clínicas abaixo são indicativas de arteriografia renal, exceto:","options":{"A":"Poliarterite nodosa;","B":"Hipertensão arterial renovascular;","C":"Tumor retroperitoneal de origem não determinada;","D":"Hemorragia persistente com urografia normal;","E":"Tumores renais e suprarrenais."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-238133","number":"238133","sourceNumber":"238133","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente vítima de esmagamento apresenta quadro de rabdomiólise que evolui com\ninsuficiência renal aguda. Qual o principal mecanismo da lesão renal?","options":{"A":"Glomerulonefrite.","B":"Alteração pós-renal.","C":"Alteração pré-renal.","D":"Nefrite intersticial aguda.","E":"Necrose tubular aguda."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-217522","number":"217522","sourceNumber":"217522","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Qual dos itens NÃO é indício de hipertensão renovascular?","options":{"A":"Níveis plasmáticos de renina baixos.","B":"Hipertensão grave ou resistente.","C":"Piora da função renal com o uso de inibidores da enzima conversora de angiotensina.","D":"Sopros abdominais."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-217509","number":"217509","sourceNumber":"217509","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Homem de 58 anos de idade, 70Kg, diabético e hipertenso, com função renal\npreviamente normal (creatinina 0,7mg/dL),\napresentou quadro de dor precordial durante uma festa\ne foi encaminhado à urgência. Ao chegar ao hospital, foi diagnosticado infarto do miocárdio com\nrepercussão hemodinâmica importante. Fez-se cineangiocoronariografia 03 horas após a admissão\nhospitalar. Hoje, dois dias após o quadro, encontra-se hipotenso, dependente de droga vasoativa e\noligúrico. A creatinina plasmática se encontra em 1,7mg/dL. Qual(is) o(s) mecanismo(s) mais\nprovável(veis) para o desenvolvimento de injúria renal aguda?","options":{"A":"Necrose tubular aguda isquêmica.","B":"Necrose tubular aguda nefrotóxica.","C":"Nefrite intersticial aguda.","D":"Necrose tubular aguda isquêmica e nefrotóxica."},"answer":"D","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-158882","number":"158882","sourceNumber":"158882","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Mulher de 65 anos foi encaminhada para realizar cineangiocoronariografia de urgência\ndevido a quadro de angina. É diabética e possui taxa de filtração glomerular estimada pela fórmula\nMDRD em 39 mL/min/1,73m2. Qual das medidas a seguir não se recomenda?","options":{"A":"Hidratação com soro fisiológico antes e durante o exame.","B":"Furosemida imediatamente após o procedimento.","C":"N-acetilcisteína antes do procedimento e após ele.","D":"Hidratação com solução de bicarbonato de sódio antes e durante o exame."},"answer":"B","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-154306","number":"154306","sourceNumber":"154306","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente com insuficiência renal agudo devido rabdomiólise. São causas de\nrabdomiólise, EXCETO:","options":{"A":"Sepse.","B":"Cocaína.","C":"Estatinas.","D":"Veneno de cobras.","E":"Aminoglicosídeo."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-129367","number":"129367","sourceNumber":"129367","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Uma jovem de 25 anos está em investigação de hipertensão arterial\n\nrecém-diagnosticada (PA = 180 x 100 mmHg). Ultrassonografia de rins e vias urinárias com Doppler\ne, posteriormente, estudo angiográfico revelaram\nestenose da artéria renal. Qual é a melhor terapia\ninicial, dentre as alternativas abaixo, para a estenose de artéria renal?","options":{"A":"Angioplastia da artéria renal e implantação de stent.","B":"Furosemida.","C":"Reserpina.","D":"Clonidina.","E":"Minoxidil."},"answer":"A","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-81509","number":"81509","sourceNumber":"81509","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"São achados da NTA (Necrose Tubular Aguda):","options":{"A":"Densidade urinária > 1020","B":"Osmolalidade urinária > 500 mOsm/kg","C":"Sódio urinário > 40 mEq/L","D":"Fração de excreção de sódio (FENa%) < 1","E":"Sedimento urinário geralmente normal"},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-179870","number":"179870","sourceNumber":"179870","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente masculino, de 22 anos, deu entrada no pronto-socorro com desidratação,\nagitação e diminuição do volume urinário.\nTem relato de participação de meia-maratona três dias\nantes da internação. Na admissão, apresentava-se hipertenso (PA = 170 x 90 mmHg), taquipneico\ne taquicárdico. Exames laboratoriais: hemoglobina = 14,6 mg/dl; hematócrito = 44%; plaquetas =\n250.000; ureia = 232 mg/dl; creatinina = 6,9 mg/dl; potássio = 6,9 mEq/L; sódio = 148 mEq/L; cálcio\n\n= 7,8 mg/dl; CPK = 188.000 UI/L. Você é o plantonista do pronto-socorro e está acompanhado de\ninternos de medicina. Como você relataria para seus internos a condição clínica mais provável para\njustificar o quadro desse paciente?","options":{"A":"Que se trataria de uma glomerulonefrite aguda.","B":"Que se trataria de uma insuficiência renal aguda por desidratação.","C":"Que se trataria de uma insuficiência renal aguda por provável leptospirose.","D":"Que se trataria de uma provável nefrite túbulo intersticial.","E":"Que se trataria de uma insuficiência renal aguda por rabdomiólise."},"answer":"E","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-343522","number":"343522","sourceNumber":"343522","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Paciente do sexo masculino, 38 anos, internado na enfermaria de ortopedia para\ntratamento de lesão de ligamento cruzado\nanterior há 3 dias, apresentando febre, dor lombar, rash\ncutâneo e redução do volume urinário. Exames laboratoriais de hoje demonstram: Cr 2,0 mg/dL (na\nadmissão: 0,8 mg/dL), hemograma com 13.800 leucócitos/mm³ (na admissão: 8.700/mm³). Contam\nna prescrição itens como dieta geral, tromboprofilaxia com heparina de baixo peso molecular,\n\nanti-inflamatório não esteroidal, analgésicos simples e antieméticos se necessário. Qual a possível\nexplicação para a lesão renal aguda?","options":{"A":"Descamação de células tubulares formando plugs dentro do lúmen tubular.","B":"Fibrose difusa do interstício renal e atrofia tubular.","C":"Infiltração intersticial renal por eosinófilos.","D":"Descamação das pontas das papilas renais, com fragmentos de tecido necrótico na via urinária."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-nefrologia-nef-2-52730","number":"52730","sourceNumber":"52730","collectionBlock":"medcurso:medcurso-nefrologia-nef-2","collectionLabel":"Medcurso · NEF 2","documentBlock":"","area":"Nefrologia","specialty":"Nefrologia","topic":"NEF 2","subtopic":"","stem":"Assinale a alternativa CORRETA, com relação à avaliação laboratorial da oligúria em\numa criança que ainda não esteja fazendo uso de\ndiuréticos ou fármacos como dopamina:","options":{"A":"A relação ureia/creatinina > 20 tem maior relação com a necrose tubular aguda do que com a\ninsuficiência pré-renal.","B":"A relação creatinina urinária/creatinina plasmática elevada (acima de 40) pressupõe uma\ninsuficiência renal intrínseca (necrose tubular renal).","C":"Na necrose tubular aguda a reabsorção de sódio e água está comprometida, levando a um\nconsequente aumento da concentração urinária de sódio.","D":"Hematúria, proteinúria e cilindros granulosos são\n\nconstatações observadas tanto na insuficiência pré-renal como na necrose tubular aguda.","E":"Na insuficiência pré-renal, a osmolalidade urinária (mOsm/kg de água é, na quase totalidade das\nvezes, baixa, ao contrário da necrose tubular aguda)."},"answer":"C","source":"Nefrologia/NEF 2/NEF 2.txt","sourceLabel":"Medcurso · NEF 2","images":[],"optionImages":{},"commentImages":[],"tags":["Nefrologia","NEF 2","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
